    function switchWomAuthTab(tab) {
      const regTab = document.getElementById('womTabRegisterBtn');
      const loginTab = document.getElementById('womTabLoginBtn');
      const regForm = document.getElementById('womRegisterForm');
      const loginForm = document.getElementById('womLoginForm');
      if (tab === 'register') {
        if (regTab) {
          regTab.style.background = '#3b82f6';
          regTab.style.color = '#fff';
        }
        if (loginTab) {
          loginTab.style.background = 'transparent';
          loginTab.style.color = '#94a3b8';
        }
        if (regForm) regForm.style.display = 'block';
        if (loginForm) loginForm.style.display = 'none';
        const regInput = document.getElementById('womNameInput');
        if (regInput) setTimeout(() => regInput.focus(), 100);
      } else {
        if (regTab) {
          regTab.style.background = 'transparent';
          regTab.style.color = '#94a3b8';
        }
        if (loginTab) {
          loginTab.style.background = '#3b82f6';
          loginTab.style.color = '#fff';
        }
        if (regForm) regForm.style.display = 'none';
        if (loginForm) loginForm.style.display = 'block';
        const loginInput = document.getElementById('womLoginHandleInput');
        if (loginInput) setTimeout(() => loginInput.focus(), 100);
      }
    }

    async function triggerUserLogin() {
      const input = document.getElementById('womLoginHandleInput');
      const pinInput = document.getElementById('womLoginPinInput');
      const errBox = document.getElementById('womLoginErrorMsg');
      const btn = document.getElementById('womLoginSubmitBtn');
      if (!input) return;
      let identifier = input.value.trim();
      if (!identifier) {
        if (errBox) {
          errBox.innerText = 'Please enter your username or handle.';
          errBox.style.display = 'block';
        }
        return;
      }
      if (!identifier.startsWith('@') && !identifier.startsWith('did:')) {
        identifier = '@' + identifier;
      }
      var pinVal = pinInput ? pinInput.value.trim() : '';
      if (!pinVal) {
        var localPin = localStorage.getItem('sovra_lock_pin');
        if (localPin) pinVal = localPin;
      }
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>Verifying credentials... ⏳</span>';
      }
      var loginAbortCtrl = new AbortController();
      var loginTimeout = setTimeout(function() { loginAbortCtrl.abort(); }, 9000);
      try {
        const res = await fetch('/api/user/login', {
          method: 'POST',
          signal: loginAbortCtrl.signal,
          headers: { 
            'Content-Type': 'application/json',
            'bypass-tunnel-reminder': 'true'
          },
          body: JSON.stringify({
            identifier: identifier,
            pin: pinVal,
            totpCode: pinVal,
            device: isMobileDevice ? 'Mobile' : 'Desktop'
          })
        });
        clearTimeout(loginTimeout);
        let data;
        const text = await res.text();
        try {
          data = JSON.parse(text);
        } catch (jsonErr) {
          if (errBox) {
            errBox.innerText = 'Server returned proxy notice (' + res.status + '): ' + text.slice(0, 120);
            errBox.style.display = 'block';
          }
          return;
        }
        if (!res.ok || !data.ok || !data.user) {
          if (errBox) {
            if (res.status === 404 || (data.error && data.error.includes('not found'))) {
              errBox.innerHTML = 'Account <strong>' + identifier + '</strong> not found. <button type="button" id="btnAutoRegisterFallback" style="margin-top: 6px; width: 100%; padding: 6px 12px; background: #3b82f6; color: #fff; border: none; border-radius: 8px; cursor: pointer; font-weight: 700; font-size: 0.8rem;">✨ 1-Click Auto-Create & Log In</button>';
              var fallbackBtn = document.getElementById('btnAutoRegisterFallback');
              if (fallbackBtn) fallbackBtn.onclick = function() { autoRegisterAndLogin(identifier, pinVal); };
            } else {
              errBox.innerText = data.error || 'Authentication failed. Please check your credentials.';
            }
            errBox.style.display = 'block';
          }
          return;
        }

        if (errBox) errBox.style.display = 'none';
        myProfile = data.user;
        if (data.sessionToken) {
          myProfile.sessionToken = data.sessionToken;
        }
        window.myProfile = myProfile;
        currentUserHandle = myProfile.handle;

        try { document.documentElement.classList.remove('sovra-unauthenticated'); } catch(e) {}
        localStorage.removeItem('sovra_logged_out');
        localStorage.removeItem('sovra_is_guest');
        localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
        if (data.sessionToken) {
          localStorage.setItem('sovra_session_token', data.sessionToken);
          localStorage.setItem('sovra_auth_active', 'true');
          try {
            document.cookie = 'sovra_session_token=' + encodeURIComponent(data.sessionToken) + '; Path=/; SameSite=Strict; max-age=2592000';
            document.cookie = 'sovra_session=' + encodeURIComponent(data.sessionToken) + '; Path=/; SameSite=Strict; max-age=2592000';
          } catch(e) {}
        }

        // 1. Immediately dismiss modal & display app UI (Zero latency)
        var womEl = document.getElementById('welcomeOnboardingModal');
        if (womEl) {
          womEl.classList.add('modal-dismissed');
          womEl.style.setProperty('display', 'none', 'important');
        }
        showAuthenticatedAppView();

        // 2. Background sync (non-blocking)
        try {
          registerPeerOnLan(myProfile);
          contactsData = [];
          chatMessages = [];
          lastContactsSignature = '__RESET__';
          lastChatSyncTimestamp = 0;
          activeContactDid = 'self';
          if (typeof syncPeersAndContacts === 'function') syncPeersAndContacts();
          if (typeof syncChatMessages === 'function') syncChatMessages();
          if (typeof renderChatContactsList === 'function') renderChatContactsList();
        } catch (syncErr) {
          console.warn('[Login background sync]', syncErr);
        }
        if (window._pendingTargetAppId && window.SovraAndroidOS && typeof window.SovraAndroidOS.openApp === 'function') {
          const pendingApp = window._pendingTargetAppId;
          window._pendingTargetAppId = null;
          window.SovraAndroidOS.openApp(pendingApp);
        } else if (window.SovraAndroidOS && typeof window.SovraAndroidOS.openApp === 'function') {
          window.SovraAndroidOS.openApp('feed');
        } else if (typeof switchTab === 'function') {
          switchTab('feed');
        } else {
          routeByRespectedProfileRole(myProfile.role);
        }
        showAccountToast('🎉 Welcome back, ' + (myProfile.name || myProfile.handle) + '!');
      } catch (err) {
        if (errBox) {
          errBox.innerText = 'Network error: ' + (err?.message || err);
          errBox.style.display = 'block';
        }
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = '<span>Sign In ➔</span>';
        }
      }
    }

    function base64UrlToBuffer(base64url) {
      if (!base64url) return new ArrayBuffer(0);
      var b64 = String(base64url).split('-').join('+').split('_').join('/');
      while (b64.length % 4 !== 0) b64 += '=';
      var binary = atob(b64);
      var bytes = new Uint8Array(binary.length);
      for (var i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
      return bytes.buffer;
    }

    function bufferToBase64Url(buffer) {
      var bytes = new Uint8Array(buffer);
      var binary = '';
      for (var i = 0; i < bytes.byteLength; i++) binary += String.fromCharCode(bytes[i]);
      return btoa(binary).split('+').join('-').split('/').join('_').split('=').join('');
    }

    function completeLoginSuccess(user, sessionToken, isNewUser) {
      myProfile = user;
      if (sessionToken) myProfile.sessionToken = sessionToken;
      window.myProfile = myProfile;
      currentUserHandle = myProfile.handle;

      localStorage.removeItem('sovra_logged_out');
      localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
      if (sessionToken) {
        localStorage.setItem('sovra_auth_active', 'true');
        localStorage.setItem('sovra_session_token', sessionToken);
        try {
          document.cookie = 'sovra_session_token=' + encodeURIComponent(sessionToken) + '; Path=/; SameSite=Strict; max-age=2592000';
          document.cookie = 'sovra_session=' + encodeURIComponent(sessionToken) + '; Path=/; SameSite=Strict; max-age=2592000';
        } catch (_) {}
      }

      // Dismiss onboarding modal immediately
      var wom = document.getElementById('welcomeOnboardingModal');
      if (wom) {
        wom.classList.add('modal-dismissed');
        wom.style.setProperty('display', 'none', 'important');
      }
      try { document.documentElement.classList.remove('sovra-unauthenticated'); } catch(e) {}

      showAuthenticatedAppView();

      try {
        if (typeof initRealtimeLiveConnection === 'function') {
          initRealtimeLiveConnection();
        }
      } catch (_) {}

      if (isNewUser) {
        showAccountToast('🎉 Welcome to Sovra! Your ID is ' + myProfile.handle, 'success');
        checkAndShowClaimHandleBanner(myProfile.handle);
      } else {
        showAccountToast('🛡️ Welcome back, ' + (myProfile.displayName || myProfile.handle) + '!', 'success');
      }
    }
    window.completeLoginSuccess = completeLoginSuccess;

    async function triggerUniversalBiometricTouch() {
      var heroBtn = document.getElementById('womUniversalBiometricBtn');
      var origText = heroBtn ? heroBtn.innerHTML : '';
      if (heroBtn) {
        heroBtn.disabled = true;
        heroBtn.innerHTML = '<span>⚡ Entering Sovra... ⏳</span>';
      }

      // Check if Hardware WebAuthn is supported in this browser context (Requires HTTPS or localhost)
      var canTryHardwareWebAuthn = Boolean(
        window.isSecureContext &&
        window.PublicKeyCredential &&
        navigator.credentials &&
        typeof navigator.credentials.get === 'function' &&
        typeof navigator.credentials.create === 'function'
      );

      if (canTryHardwareWebAuthn) {
        try {
          var hasPasskeyOnDevice = localStorage.getItem('sovra_has_passkey') === 'true';

          // If device already registered a passkey before, do assertion (login)
          if (hasPasskeyOnDevice) {
            if (heroBtn) heroBtn.innerHTML = '<span>Scan Fingerprint to Sign In... ⏳</span>';
            var optRes = await fetch('/api/auth/webauthn/login-options', { headers: { 'bypass-tunnel-reminder': 'true' } });
            var optData = await optRes.json();
            if (optRes.ok && optData.ok && optData.options) {
              var opts = optData.options;
              opts.challenge = base64UrlToBuffer(opts.challenge);
              if (opts.allowCredentials && Array.isArray(opts.allowCredentials)) {
                opts.allowCredentials = opts.allowCredentials.map(function(c) {
                  return {
                    id: base64UrlToBuffer(c.id),
                    type: c.type || 'public-key',
                    transports: c.transports
                  };
                });
              }

              try {
                var assertion = await navigator.credentials.get({ publicKey: opts });
                if (assertion) {
                  var payload = {
                    id: assertion.id,
                    rawId: bufferToBase64Url(assertion.rawId),
                    type: assertion.type,
                    device: isMobileDevice ? 'Mobile Biometric' : 'Desktop Biometric',
                    response: {
                      clientDataJSON: bufferToBase64Url(assertion.response.clientDataJSON),
                      authenticatorData: bufferToBase64Url(assertion.response.authenticatorData),
                      signature: bufferToBase64Url(assertion.response.signature),
                      userHandle: assertion.response.userHandle ? bufferToBase64Url(assertion.response.userHandle) : undefined
                    }
                  };

                  var verRes = await fetch('/api/auth/webauthn/login-verify', {
                    method: 'POST',
                    headers: { 'Content-Type': 'application/json', 'bypass-tunnel-reminder': 'true' },
                    body: JSON.stringify(payload)
                  });
                  var verData = await verRes.json();
                  if (verRes.ok && verData.ok && verData.user) {
                    completeLoginSuccess(verData.user, verData.sessionToken, false);
                    return true;
                  }
                }
              } catch (assertionErr) {
                // Assertion failed -> might need re-registration
              }
            }
          }

          // Otherwise (New User or First Passkey on this device), invoke Native Biometric Registration
          if (heroBtn) heroBtn.innerHTML = '<span>Scan Fingerprint to Register... ⏳</span>';
          var regOptRes = await fetch('/api/auth/webauthn/register-options', { headers: { 'bypass-tunnel-reminder': 'true' } });
          var regOptData = await regOptRes.json();
          if (regOptRes.ok && regOptData.ok && regOptData.options) {
            var regOpts = regOptData.options;
            regOpts.challenge = base64UrlToBuffer(regOpts.challenge);
            regOpts.user.id = base64UrlToBuffer(regOpts.user.id);

            var credential = await navigator.credentials.create({ publicKey: regOpts });
            if (credential) {
              var regPayload = {
                id: credential.id,
                rawId: bufferToBase64Url(credential.rawId),
                type: credential.type,
                handle: regOptData.options.user ? regOptData.options.user.name : undefined,
                did: bufferToBase64Url(regOpts.user.id),
                device: isMobileDevice ? 'Mobile Biometric' : 'Desktop Biometric',
                response: {
                  clientDataJSON: bufferToBase64Url(credential.response.clientDataJSON),
                  attestationObject: bufferToBase64Url(credential.response.attestationObject),
                  transports: credential.response.getTransports ? credential.response.getTransports() : ['internal']
                }
              };

              var regVerRes = await fetch('/api/auth/webauthn/register-verify', {
                method: 'POST',
                headers: { 'Content-Type': 'application/json', 'bypass-tunnel-reminder': 'true' },
                body: JSON.stringify(regPayload)
              });
              var regVerData = await regVerRes.json();

              if (regVerRes.ok && regVerData.ok && regVerData.user) {
                localStorage.setItem('sovra_has_passkey', 'true');
                completeLoginSuccess(regVerData.user, regVerData.sessionToken, true);
                return true;
              }
            }
          }
        } catch (err) {
          console.warn('[WebAuthn] Hardware biometric error:', err);
          var isIpAddressHost = /^\d+\.\d+\.\d+\.\d+$/.test(window.location.hostname);
          if (err && err.name === 'NotAllowedError') {
            if (isIpAddressHost) {
              console.warn('[WebAuthn] Hardware passkeys are restricted on IP addresses by W3C spec. Proceeding with 1-Tap Device Touch...');
              // Fall through to Step 3 so device touch completes and signs user in!
            } else {
              showAccountToast('Biometric prompt was cancelled.', 'info');
              if (heroBtn) {
                heroBtn.disabled = false;
                heroBtn.innerHTML = origText;
              }
              return false;
            }
          }
        }
      }

      // Step 3: Universal 1-Tap Cryptographic Device Touch (Always succeeds on mobile Wi-Fi IP / HTTP / Non-WebAuthn)
      try {
        if (heroBtn) heroBtn.innerHTML = '<span>Connecting Sovereign Node... ⏳</span>';
        var devToken = localStorage.getItem('sovra_device_token') || '';
        var devRes = await fetch('/api/auth/universal-touch', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'bypass-tunnel-reminder': 'true' },
          body: JSON.stringify({
            deviceToken: devToken,
            device: isMobileDevice ? 'Mobile Touch' : 'Desktop Touch'
          })
        });
        var devData = await devRes.json();
        if (devRes.ok && devData.ok && devData.user) {
          if (devData.deviceToken) {
            localStorage.setItem('sovra_device_token', devData.deviceToken);
          }
          completeLoginSuccess(devData.user, devData.sessionToken, devData.isNewUser);
          return true;
        } else {
          showAccountToast('❌ Touch sign-in failed: ' + (devData.error || 'Server error'), 'error');
        }
      } catch (fallbackErr) {
        showAccountToast('❌ Touch sign-in error: ' + (fallbackErr?.message || fallbackErr), 'error');
      } finally {
        if (heroBtn) {
          heroBtn.disabled = false;
          heroBtn.innerHTML = origText;
        }
      }
      return false;
    }
    window.triggerUniversalBiometricTouch = triggerUniversalBiometricTouch;

