    var _claimHandleDebounce = null;
    function checkClaimHandleAvailability() {
      var input = document.getElementById('claimHandleInput');
      var feedback = document.getElementById('claimHandleFeedback');
      if (!input || !feedback) return;
      var raw = input.value.trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
      input.value = raw;
      if (!raw || raw.length < 3) {
        feedback.innerText = 'Minimum 3 characters (letters, numbers, underscores)';
        feedback.style.color = '#94a3b8';
        return;
      }
      if (_claimHandleDebounce) clearTimeout(_claimHandleDebounce);
      _claimHandleDebounce = setTimeout(async function() {
        try {
          var res = await fetch('/api/user/check-handle?handle=' + encodeURIComponent('@' + raw) + (myProfile?.did ? ('&excludeDid=' + encodeURIComponent(myProfile.did)) : ''));
          var data = await res.json();
          if (data.ok && data.isAvailable) {
            feedback.innerText = '✓ @' + raw + ' is available!';
            feedback.style.color = '#34d399';
          } else {
            feedback.innerText = '✕ @' + raw + ' is already taken';
            feedback.style.color = '#f87171';
          }
        } catch (_) {}
      }, 200);
    }
    window.checkClaimHandleAvailability = checkClaimHandleAvailability;

    async function executeClaimHandle() {
      var input = document.getElementById('claimHandleInput');
      var btn = document.getElementById('btnSubmitClaimHandle');
      var feedback = document.getElementById('claimHandleFeedback');
      if (!input || !input.value.trim()) return;
      var newHandle = '@' + input.value.trim().toLowerCase().replace(/[^a-z0-9_]/g, '');
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>Saving... ⏳</span>';
      }
      try {
        var token = (myProfile && myProfile.sessionToken) || (typeof getEffectiveSessionToken === 'function' ? getEffectiveSessionToken() : '');
        var res = await fetch('/api/user/update', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token,
            'bypass-tunnel-reminder': 'true'
          },
          body: JSON.stringify({ handle: newHandle })
        });
        var data = await res.json();
        if (res.ok && data.ok && data.user) {
          myProfile = Object.assign({}, myProfile, data.user);
          currentUserHandle = myProfile.handle;
          localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
          updateUserDisplayInUI();
          closeClaimHandleModal();
          var banner = document.getElementById('sovraClaimHandleBanner');
          if (banner) banner.style.display = 'none';
          showAccountToast('✨ Your permanent username is now ' + myProfile.handle + '!', 'success');
        } else {
          if (feedback) {
            feedback.innerText = '✕ ' + (data.error || 'Failed to claim username');
            feedback.style.color = '#f87171';
          }
        }
      } catch (err) {
        if (feedback) {
          feedback.innerText = '✕ Network error: ' + (err?.message || err);
          feedback.style.color = '#f87171';
        }
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = '<span>Save &amp; Claim Username</span>';
        }
      }
    }
    window.executeClaimHandle = executeClaimHandle;

    async function triggerWebAuthnBiometricLogin() {
      if (!window.isSecureContext || !window.PublicKeyCredential || !navigator.credentials) {
        return triggerUniversalBiometricTouch();
      }
      var btn = document.getElementById('womBiometricLoginBtn');
      var origText = btn ? btn.innerHTML : '';
      if (btn) {
        btn.disabled = true;
        btn.innerHTML = '<span>Scanning Fingerprint / Face ID... ⏳</span>';
      }

      try {
        var input = document.getElementById('womLoginHandleInput');
        var identifier = input ? input.value.trim() : '';
        var optUrl = '/api/auth/webauthn/login-options' + (identifier ? ('?identifier=' + encodeURIComponent(identifier)) : '');
        var optRes = await fetch(optUrl, { headers: { 'bypass-tunnel-reminder': 'true' } });
        var optData = await optRes.json();
        if (!optRes.ok || !optData.ok || !optData.options) {
          showAccountToast('⚠️ Could not initiate biometric challenge: ' + (optData.error || 'Server error'), 'error');
          return false;
        }

        var opts = optData.options;
        opts.challenge = base64UrlToBuffer(opts.challenge);
        if (opts.allowCredentials && Array.isArray(opts.allowCredentials)) {
          opts.allowCredentials = opts.allowCredentials.map(function(c) {
            return {
              id: base64UrlToBuffer(c.id),
              type: c.type || 'public-key',
              transports: c.transports
            };
          });
        }

        var assertion = await navigator.credentials.get({ publicKey: opts });
        if (!assertion) {
          showAccountToast('Biometric scan cancelled.', 'info');
          return false;
        }

        var payload = {
          id: assertion.id,
          rawId: bufferToBase64Url(assertion.rawId),
          type: assertion.type,
          identifier: identifier || undefined,
          device: isMobileDevice ? 'Mobile Biometric' : 'Desktop Biometric',
          response: {
            clientDataJSON: bufferToBase64Url(assertion.response.clientDataJSON),
            authenticatorData: bufferToBase64Url(assertion.response.authenticatorData),
            signature: bufferToBase64Url(assertion.response.signature),
            userHandle: assertion.response.userHandle ? bufferToBase64Url(assertion.response.userHandle) : undefined
          }
        };

        var verRes = await fetch('/api/auth/webauthn/login-verify', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'bypass-tunnel-reminder': 'true' },
          body: JSON.stringify(payload)
        });
        var verData = await verRes.json();

        if (!verRes.ok || !verData.ok || !verData.user) {
          showAccountToast('❌ Biometric verification failed: ' + (verData.error || 'Invalid credentials'), 'error');
          return false;
        }

        myProfile = verData.user;
        currentUserHandle = myProfile.handle;
        localStorage.removeItem('sovra_logged_out');
        localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
        if (verData.sessionToken) localStorage.setItem('sovra_auth_active', 'true');

        registerPeerOnLan(myProfile);

        showAuthenticatedAppView();
        showAccountToast('🛡️ Unlocked with Fingerprint / Face ID! Welcome ' + (myProfile.name || myProfile.handle), 'success');
        return true;
      } catch (err) {
        if (err && err.name === 'NotAllowedError') {
          showAccountToast('Biometric verification cancelled or timed out.', 'info');
        } else {
          showAccountToast('Biometric error: ' + (err?.message || err), 'error');
        }
        return false;
      } finally {
        if (btn) {
          btn.disabled = false;
          btn.innerHTML = origText;
        }
      }
    }

    async function triggerWebAuthnBiometricRegister() {
      if (!window.PublicKeyCredential || !navigator.credentials) {
        showAccountToast('⚠️ Hardware biometrics not supported on this browser context. Must use HTTPS.', 'error');
        return;
      }
      var token = (myProfile && myProfile.sessionToken) ? myProfile.sessionToken : localStorage.getItem('sovra_session_token');
      var handle = (myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;

      showAccountToast('👆 Touch your phone fingerprint or Face ID to link...', 'info');

      try {
        var optUrl = '/api/auth/webauthn/register-options?handle=' + encodeURIComponent(handle);
        var headers = { 'bypass-tunnel-reminder': 'true' };
        if (token) headers['Authorization'] = 'Bearer ' + token;

        var optRes = await fetch(optUrl, { headers: headers });
        var optData = await optRes.json();
        if (!optRes.ok || !optData.ok || !optData.options) {
          showAccountToast('⚠️ Failed to get registration challenge: ' + (optData.error || 'Server error'), 'error');
          return;
        }

        var opts = optData.options;
        opts.challenge = base64UrlToBuffer(opts.challenge);
        opts.user.id = base64UrlToBuffer(opts.user.id);

        var credential = await navigator.credentials.create({ publicKey: opts });
        if (!credential) {
          showAccountToast('Biometric registration cancelled.', 'info');
          return;
        }

        var payload = {
          id: credential.id,
          rawId: bufferToBase64Url(credential.rawId),
          type: credential.type,
          identifier: handle,
          sessionToken: token,
          response: {
            clientDataJSON: bufferToBase64Url(credential.response.clientDataJSON),
            attestationObject: bufferToBase64Url(credential.response.attestationObject),
            transports: credential.response.getTransports ? credential.response.getTransports() : ['internal']
          }
        };

        var verRes = await fetch('/api/auth/webauthn/register-verify', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json', 'bypass-tunnel-reminder': 'true' },
          body: JSON.stringify(payload)
        });
        var verData = await verRes.json();

        if (!verRes.ok || !verData.ok) {
          showAccountToast('❌ Failed to link biometric passkey: ' + (verData.error || 'Verification error'), 'error');
          return;
        }

        if (myProfile) myProfile.hasWebAuthn = true;
        try { localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile)); } catch(e) {}
        showAccountToast('🎉 Fingerprint & Face ID linked successfully to your phone!', 'success');
        if (typeof populateAlmUserData === 'function') populateAlmUserData();
      } catch (err) {
        if (err && err.name === 'NotAllowedError') {
          showAccountToast('Biometric prompt was cancelled.', 'info');
        } else {
          showAccountToast('Registration error: ' + (err?.message || err), 'error');
        }
      }
    }

    function openForgotPinModal() {
      var handleInput = document.getElementById('womLoginHandleInput');
      var curHandle = handleInput ? handleInput.value.trim() : '';
      var identifier = prompt('Enter your Sovereign Handle or DID to reset PIN:', curHandle || '@merajsharif');
      if (!identifier) return;
      var phrase = prompt('Enter your 12-Word Recovery Seed Phrase for ' + identifier + ':');
      if (!phrase) return;
      var newPin = prompt('Enter new Security PIN (4-8 digits):', '1234');
      if (!newPin) return;
      submitForgotPinResetDirect(identifier, phrase, newPin);
    }

    async function submitForgotPinResetDirect(identifier, phrase, newPin) {
      try {
        var res = await fetch('/api/auth/pin/recover', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ identifier: identifier.trim(), recoveryPhrase: phrase.trim(), newPin: newPin.trim() })
        });
        var data = await res.json();
        if (data && data.ok) {
          showAccountToast('✓ Security PIN reset to ' + newPin + '! Logging in...', 'success');
          var pinIn = document.getElementById('womLoginPinInput');
          if (pinIn) pinIn.value = newPin.trim();
          try { localStorage.setItem('sovra_lock_pin', newPin.trim()); } catch(e) {}
          triggerUserLogin();
        } else {
          showAccountToast('PIN reset failed: ' + ((data && data.error) ? data.error : 'Invalid recovery phrase'));
        }
      } catch (err) {
        showAccountToast('Network failure: ' + (err.message || err));
      }
    }

