    async function saveEditedProfile() {
      const nameInput = document.getElementById('editProfileNameInput');
      const handleInput = document.getElementById('editProfileHandleInput');
      const bioInput = document.getElementById('editProfileBioInput');
      const websiteInput = document.getElementById('editProfileWebsiteInput');

      const newName = (nameInput && nameInput.value.trim()) ? nameInput.value.trim() : (myProfile ? myProfile.name : 'Sovereign Node');
      let rawHandle = (handleInput && handleInput.value.trim()) ? handleInput.value.trim() : (myProfile ? myProfile.handle : '@user');
      if (!rawHandle.startsWith('@')) rawHandle = '@' + rawHandle;
      const newBio = bioInput ? bioInput.value.trim() : '';
      const newWebsite = (websiteInput && websiteInput.value.trim()) ? websiteInput.value.trim() : '';

      const token = localStorage.getItem('sovra_session_token') || (window.SOVRA_HOST_SESSION && window.SOVRA_HOST_SESSION.token) || (myProfile ? myProfile.sessionToken : '') || '';
      const updatedPayload = {
        did: myProfile ? myProfile.did : ('did:sovra:user_' + (window.sovraCSPRNG ? window.sovraCSPRNG(8) : Date.now().toString(36))),
        sessionToken: token,
        handle: rawHandle,
        name: newName,
        displayName: newName,
        avatar: newName.charAt(0).toUpperCase(),
        avatarDataUrl: selectedEditAvatarDataUrl !== null ? selectedEditAvatarDataUrl : (myProfile ? (myProfile.avatarDataUrl || '') : ''),
        avatarBg: selectedEditAvatarBg,
        bio: newBio,
        website: newWebsite,
        coverDataUrl: selectedEditCoverDataUrl !== null ? selectedEditCoverDataUrl : (myProfile ? (myProfile.coverDataUrl || '') : ''),
        device: isMobileDevice ? 'Mobile' : 'Desktop'
      };

      try {
        const fetchFn = (typeof window.authenticatedFetch === 'function') ? window.authenticatedFetch : fetch;
        const res = await fetchFn('/api/user/update', {
          method: 'POST',
          headers: { 
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token
          },
          body: JSON.stringify(updatedPayload)
        });
        const data = await res.json();
        if (!res.ok || !data.ok) {
          showAccountToast('Could not update profile: ' + (data.error || 'Server error'));
          return;
        }

        myProfile = data.user;
        currentUserHandle = myProfile.handle;
        try {
          localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
          if (myProfile.sessionToken) localStorage.setItem('sovra_auth_active', 'true');
        } catch (e) {}

        registerPeerOnLan(myProfile);

        updateUserDisplayInUI();
        closeEditProfileModal();
        showAccountToast('Profile saved to database and announced to peer mesh!');
      } catch (err) {
        showAccountToast('Network error while updating profile: ' + err);
      }
    }

    let womHandleCheckTimer = null;
    function validateWomHandleLive(rawHandle) {
      if (womHandleCheckTimer) clearTimeout(womHandleCheckTimer);
      const feedback = document.getElementById('womHandleFeedback');
      const errorBox = document.getElementById('womErrorMsg');
      if (errorBox) errorBox.style.display = 'none';
      if (!feedback) return;

      const trimmed = (rawHandle || '').trim().replace(/^@/, '');
      if (!trimmed) {
        feedback.innerText = 'Checked on P2P Mesh';
        feedback.style.color = '#94a3b8';
        return;
      }

      feedback.innerText = 'Checking...';
      feedback.style.color = '#38bdf8';

      womHandleCheckTimer = setTimeout(() => {
        fetch('/api/user/check-handle?handle=' + encodeURIComponent('@' + trimmed))
          .then(r => r.json())
          .then(data => {
            if (data.ok) {
              if (data.isAvailable) {
                feedback.innerText = '✓ Available';
                feedback.style.color = '#10b981';
              } else {
                feedback.innerText = '✕ Already Taken';
                feedback.style.color = '#f87171';
              }
            }
          })
          .catch(() => {
            feedback.innerText = 'Checked on P2P Mesh';
            feedback.style.color = '#94a3b8';
          });
      }, 250);
    }

    // Auto-check onboarding on first visit & restore session from server
    window.addEventListener('DOMContentLoaded', function() {
      if (!window.isSecureContext && window.location.protocol !== 'https:' && window.location.hostname !== 'localhost' && window.location.hostname !== '127.0.0.1') {
        var notice = document.getElementById('insecureContextNotice');
        if (notice) {
          notice.style.display = 'flex';
          var noticeLink = document.getElementById('insecureContextNoticeLink');
          if (noticeLink) {
            noticeLink.href = 'https://' + window.location.hostname + ':3443' + window.location.pathname;
          }
        }
        var womHint = document.getElementById('womSecureContextHint');
        if (womHint) {
          womHint.style.display = 'block';
          var womLink = document.getElementById('womHttpsSwitchLink');
          if (womLink) {
            womLink.href = 'https://' + window.location.hostname + ':3443' + window.location.pathname;
          }
        }
      }

      var isIpHost = /^\d+\.\d+\.\d+\.\d+$/.test(window.location.hostname);
      if (isIpHost) {
        fetch('/api/status').then(function(r) { return r.json(); }).then(function(d) {
          if (d && d.cloudflareUrl) {
            var womHint = document.getElementById('womSecureContextHint');
            if (womHint) {
              womHint.innerHTML = '✨ <strong>Real Hardware Fingerprint:</strong> Mobile biometrics require a trusted domain. <a href="' + d.cloudflareUrl + '" style="color: #67e8f9; text-decoration: underline; font-weight: 700;">Open on Live HTTPS Domain ➔</a>';
              womHint.style.display = 'block';
            }
          }
        }).catch(function() {});
      }

      const isExplicitlyLoggedOut = localStorage.getItem('sovra_logged_out') === 'true';
      let savedProfile = localStorage.getItem('sovra_user_profile');
      let sessionToken = (typeof window.getEffectiveSessionToken === 'function') ? window.getEffectiveSessionToken() : (localStorage.getItem('sovra_session_token') || '');

      const isLocalHostMachine = (window.location.hostname === 'localhost' || window.location.hostname === '127.0.0.1');

      // Remote device safety: If visiting from an external device/domain and cached profile is default host, wipe it
      if (!isLocalHostMachine && savedProfile) {
        try {
          const parsedProf = JSON.parse(savedProfile);
          if (parsedProf && (parsedProf.handle === '@laptop_host' || parsedProf.handle === 'laptop_host')) {
            localStorage.removeItem('sovra_user_profile');
            localStorage.removeItem('sovra_session_token');
            localStorage.setItem('sovra_logged_out', 'true');
            savedProfile = null;
            sessionToken = '';
          }
        } catch (_) {}
      }

      // Seamless Auto-Login: ONLY if directly accessing on localhost host machine (not remote clients/ngrok)
      if (isLocalHostMachine && !isExplicitlyLoggedOut && !savedProfile && window.__SOVRA_HYDRATED_STATE__ && window.__SOVRA_HYDRATED_STATE__.hostSession) {
        try {
          const _hs = window.__SOVRA_HYDRATED_STATE__.hostSession;
          const _autoProf = {
            did: _hs.did,
            handle: _hs.handle || '@laptop_host',
            displayName: 'Host Node',
            name: 'Host Node',
            avatar: '💻',
            avatarBg: '#6366f1',
            bio: 'Sovereign P2P Node Operator',
            deviceType: isMobileDevice ? 'Mobile' : 'Desktop',
            isOnline: true,
            sessionToken: _hs.token
          };
          localStorage.setItem('sovra_user_profile', JSON.stringify(_autoProf));
          localStorage.setItem('sovra_auth_active', 'true');
          if (_hs.token) localStorage.setItem('sovra_session_token', _hs.token);
          savedProfile = JSON.stringify(_autoProf);
          sessionToken = _hs.token || '';
        } catch(e) {}
      }

      if (isExplicitlyLoggedOut || !savedProfile) {
        myProfile = null;
        currentUserHandle = '@guest';
        updateUserDisplayInUI();
        showAuthLandingGate(true);
        if (window.SovraAndroidOS && typeof window.SovraAndroidOS.goHome === 'function') {
          window.SovraAndroidOS.goHome();
        }
        return;
      }

      // Restore active user profile immediately to eliminate any UI flicker
      try {
        myProfile = JSON.parse(savedProfile);
        if (sessionToken && !myProfile.sessionToken) {
          myProfile.sessionToken = sessionToken;
        }
        currentUserHandle = myProfile.handle || (myProfile.name ? ('@' + myProfile.name.toLowerCase().replace(/\s+/g, '_')) : '@guest');
        window.myProfile = myProfile;
        try { document.documentElement.classList.remove('sovra-unauthenticated'); } catch(e) {}
        showAuthenticatedAppView();
        updateUserDisplayInUI();
      } catch (e) {
        myProfile = null;
        currentUserHandle = '@guest';
        updateUserDisplayInUI();
        showAuthLandingGate(true);
        return;
      }

      const _meDidParam = (myProfile && myProfile.did) ? ('?did=' + encodeURIComponent(myProfile.did)) : '';
      const _meHandleParam = (myProfile && myProfile.handle) ? ((_meDidParam ? '&' : '?') + 'handle=' + encodeURIComponent(myProfile.handle)) : '';
      const meHeaders = {
        'bypass-tunnel-reminder': 'true',
        'ngrok-skip-browser-warning': 'true'
      };
      if (sessionToken) {
        meHeaders['Authorization'] = 'Bearer ' + sessionToken;
      }
      fetch('/api/user/me' + _meDidParam + _meHandleParam, {
        credentials: 'same-origin',
        headers: meHeaders
      })
        .then(r => r.json())
        .then(data => {
          if (data && data.ok && data.user) {
            myProfile = Object.assign({}, myProfile, data.user);
            if (sessionToken && !myProfile.sessionToken) {
              myProfile.sessionToken = sessionToken;
            }
            window.myProfile = myProfile;
            currentUserHandle = myProfile.handle;
            try {
              localStorage.setItem('sovra_user_profile', JSON.stringify(myProfile));
              localStorage.removeItem('sovra_logged_out');
              localStorage.setItem('sovra_auth_active', 'true');
              if (sessionToken) localStorage.setItem('sovra_session_token', sessionToken);
            } catch(e) {}
            try { document.documentElement.classList.remove('sovra-unauthenticated'); } catch(e) {}
            showAuthenticatedAppView();
            updateUserDisplayInUI();
            if (window.SovraAndroidOS && typeof window.SovraAndroidOS.openApp === 'function') {
              window.SovraAndroidOS.openApp('feed');
            } else if (typeof switchTab === 'function') {
              switchTab('feed');
            } else {
              routeByRespectedProfileRole(myProfile.role);
            }
            if (typeof fetchNotifications === 'function') fetchNotifications();
            if (typeof syncFriendsRelationships === 'function') syncFriendsRelationships();
            if (typeof syncPeersAndContacts === 'function') syncPeersAndContacts();
            if (typeof fetchAndRenderStories === 'function') fetchAndRenderStories();
            // Register heartbeat with server
            registerPeerOnLan(myProfile);
          } else {
            // Keep local offline/cached profile active, never unseat user on server glitch
            if (savedProfile && !isExplicitlyLoggedOut) {
              try {
                myProfile = JSON.parse(savedProfile);
                window.myProfile = myProfile;
                currentUserHandle = myProfile.handle;
                try { document.documentElement.classList.remove('sovra-unauthenticated'); } catch(e) {}
                showAuthenticatedAppView();
                updateUserDisplayInUI();
                if (window.SovraAndroidOS && typeof window.SovraAndroidOS.openApp === 'function') {
                  window.SovraAndroidOS.openApp('feed');
                } else if (typeof switchTab === 'function') {
                  switchTab('feed');
                } else {
                  routeByRespectedProfileRole(myProfile.role);
                }
              } catch(e) {}
            }
          }
        })
        .catch(() => {
          // Keep offline/cached session active on network timeout
          if (savedProfile && !isExplicitlyLoggedOut) {
            try {
              myProfile = JSON.parse(savedProfile);
              currentUserHandle = myProfile.handle;
              try { document.documentElement.classList.remove('sovra-unauthenticated'); } catch(e) {}
              showAuthenticatedAppView();
              updateUserDisplayInUI();
              if (window.SovraAndroidOS && typeof window.SovraAndroidOS.openApp === 'function') {
                window.SovraAndroidOS.openApp('feed');
              } else if (typeof switchTab === 'function') {
                switchTab('feed');
              } else {
                routeByRespectedProfileRole(myProfile.role);
              }
            } catch(e) {}
          }
        });

      if (!isSovraAppInstalled()) {
        setTimeout(function() {
          if (isSovraAppInstalled()) return;
          const banner = document.getElementById('pwaInstallBanner');
          if (banner) {
            banner.style.display = 'flex';
          }
          const topBtn = document.getElementById('pwaInstallBtn');
          if (topBtn) topBtn.style.display = 'none';
        }, 800);
      }
      setTimeout(function() {
        if (typeof syncFriendsRelationships === 'function') syncFriendsRelationships();
        if (typeof renderRightRailSuggestions === 'function') renderRightRailSuggestions();
        if (typeof renderFbContacts === 'function') renderFbContacts();
        if (typeof renderTrendingHashtags === 'function') renderTrendingHashtags();
        if (typeof updateProfileDynamicStats === 'function') updateProfileDynamicStats();
      }, 400);
      setInterval(function() {
        if (typeof updateProfileDynamicStats === 'function') updateProfileDynamicStats();
      }, 5000);
      setInterval(function() {
        if (typeof renderTrendingHashtags === 'function') renderTrendingHashtags();
      }, 30000);
    });

