    function switchTab(tab) {
      if (tab === 'explore') tab = 'hub';
      if (tab === 'vault' || tab === 'profile' || tab === 'you') tab = 'me';
      if (tab === 'watch') tab = 'youtube';

      if (typeof triggerHapticFeedback === 'function') triggerHapticFeedback([8]);

      // Pre-flight Auth Guard for protected private sections ONLY
      // Public media & exploration surfaces (watch/youtube, feed, reels, hub, dapps, friends) are freely accessible to guests & visitors!
      var isAuth = (typeof window.isUserAuthenticated === 'function')
        ? window.isUserAuthenticated()
        : (window.SovraAndroidOS && typeof window.SovraAndroidOS.isUserAuthenticated === 'function' ? window.SovraAndroidOS.isUserAuthenticated() : false);

      const protectedTabs = ['chat', 'chats', 'me', 'vault', 'studio', 'admin', 'calls'];
      if (!isAuth && protectedTabs.includes(tab)) {
        window._pendingTargetAppId = tab;
        if (typeof window.showAuthLandingModal === 'function') {
          window.showAuthLandingModal('login');
        } else if (typeof window.showAuthLandingGate === 'function') {
          window.showAuthLandingGate(true);
        }
        return;
      }

      if (tab === 'watch') tab = 'youtube';
      if (tab === 'home') tab = 'feed';
      if (tab === 'you') tab = 'me';
      if (tab === 'shorts') tab = 'reels';
      if (tab === 'chats') tab = 'chat';
      document.body.classList.remove('sovra-mode-home');
      document.body.classList.add('sovra-mode-app');
      if (tab === 'studio') {
        const p = (window.SovraState && window.SovraState.currentUser) || (typeof myProfile !== 'undefined' ? myProfile : null);
        const isCreator = Boolean(p && (
          p.isCreator === true ||
          p.role === 'CREATOR' ||
          p.role === 'ADMIN' ||
          p.role === 'SUPER_ADMIN' ||
          p.role === 'OPERATOR'
        ));
        // Universal access: never block users with a dead-end modal or toast!
        // If not yet a creator, route them smoothly into Onboarding Gateway
        var onboardingView = document.getElementById('studioChannelOnboardingView');
        var dashboardShell = document.getElementById('studioDashboardShell');
        if (!isCreator) {
          if (onboardingView) onboardingView.style.display = 'block';
          if (dashboardShell) dashboardShell.style.display = 'none';
        }
      }
      if (tab === 'saved') {
        switchTab('me');
        if (typeof switchProfileGridTab === 'function') {
          switchProfileGridTab('saved');
        }
        return;
      }
      if (tab === 'admin') {
        const p = (window.SovraState && window.SovraState.currentUser) || (typeof myProfile !== 'undefined' ? myProfile : null);
        const isAdminUser = Boolean(p && (
          p.role === 'SUPER_ADMIN' ||
          p.role === 'ADMIN' ||
          p.role === 'OPERATOR' ||
          p.role === 'SECURITY_ADMIN' ||
          p.isAdmin === true ||
          p.handle === '@laptop_host'
        ));
        if (!isAdminUser) {
          if (typeof showAccountToast === 'function') {
            showAccountToast('🔒 Operations Console is reserved for Node Operators and Admins.');
          }
          return;
        }
      }
      const views = {
        feed: document.getElementById('feed-view'),
        friends: document.getElementById('friends-view'),
        reels: document.getElementById('reels-view'),
        youtube: document.getElementById('youtube-view'),
        chat: document.getElementById('chat-view'),
        me: document.getElementById('profile-view'),
        admin: document.getElementById('admin-view'),
        'peer-profile': document.getElementById('peer-profile-view'),
        channel: document.getElementById('channel-hub-view'),
        hub: document.getElementById('hub-view'),
        studio: document.getElementById('studio-view'),
        calls: document.getElementById('calls-view'),
        live: document.getElementById('live-view'),
        communities: document.getElementById('communities-view'),
        search: document.getElementById('search-view'),
        notifications: document.getElementById('notifications-view'),
        settings: document.getElementById('settings-view'),
        dapps: document.getElementById('dapps-view'),
        player: document.getElementById('player-view'),
      };
      const tabs = {
        feed: document.getElementById('tab-feed'),
        friends: document.getElementById('tab-friends'),
        reels: document.getElementById('tab-reels'),
        youtube: document.getElementById('tab-youtube'),
        chat: document.getElementById('tab-chat'),
        me: document.getElementById('tab-me'),
        admin: document.getElementById('tab-admin'),
        hub: document.getElementById('tab-hub'),
        studio: document.getElementById('tab-studio'),
        calls: document.getElementById('tab-calls'),
        live: document.getElementById('tab-live'),
        communities: document.getElementById('tab-communities'),
        notifications: document.getElementById('tab-notifications'),
        settings: document.getElementById('tab-settings'),
        dapps: document.getElementById('navTabDApps'),
        player: document.getElementById('tab-player'),
      };
      const bnavs = {
        feed: document.getElementById('bnav-feed'),
        friends: document.getElementById('bnav-friends'),
        reels: document.getElementById('bnav-reels'),
        youtube: document.getElementById('bnav-youtube'),
        chat: document.getElementById('bnav-chat'),
        me: document.getElementById('bnav-me'),
        admin: document.getElementById('bnav-admin'),
        hub: document.getElementById('bnav-hub'),
        studio: document.getElementById('bnav-studio'),
      };

      // Floating Mini-Player coordination
      if (tab === 'player') {
        const mini = document.getElementById('sovraFloatingMiniPlayer');
        if (mini) mini.style.display = 'none';
      } else {
        const vid = document.getElementById('sovraActiveVideoElement');
        if (vid && !vid.paused && !vid.ended && vid.currentTime > 0) {
          if (typeof showSovraMiniPlayer === 'function') showSovraMiniPlayer();
        }
      }

      // ❄️ Freeze Previous Tab (Scroll & Media Playback)
      const prevTab = document.body.dataset.activeTab || window._currentActiveTab || 'feed';
      if (prevTab && prevTab !== tab) {
        if (prevTab === 'feed' || prevTab === 'friends') {
          tabFreezeState[prevTab] = { scrollY: window.scrollY };
        } else if (prevTab === 'reels') {
          const reelVid = document.querySelector('#reels-view video');
          const bgAudioOn = Boolean(window.SovraBackgroundAudioEngine && window.SovraBackgroundAudioEngine.enabled);
          const wasPlaying = reelVid ? !reelVid.paused : Boolean(typeof isReelPlaying !== 'undefined' && isReelPlaying);
          tabFreezeState.reels = {
            reelIndex: typeof currentReelIndex === 'number' ? currentReelIndex : 0,
            currentTime: reelVid ? reelVid.currentTime : 0,
            isPlaying: wasPlaying
          };
          if (bgAudioOn && wasPlaying) {
            if (window.SovraBackgroundAudioEngine && typeof window.SovraBackgroundAudioEngine.activateMiniBar === 'function') {
              window.SovraBackgroundAudioEngine.activateMiniBar('reels');
            }
          } else {
            if (reelVid) reelVid.pause();
          }
        } else if (prevTab === 'youtube') {
          const ytVid = document.querySelector('#youtube-view video');
          const bgAudioOn = Boolean(window.SovraBackgroundAudioEngine && window.SovraBackgroundAudioEngine.enabled);
          const wasPlaying = ytVid ? !ytVid.paused : Boolean(typeof ytIsPlaying !== 'undefined' && ytIsPlaying);
          tabFreezeState.youtube = {
            videoIndex: typeof activeYtVideoIndex === 'number' ? activeYtVideoIndex : 0,
            currentTime: ytVid ? ytVid.currentTime : (typeof ytCurrentTimeSec === 'number' ? ytCurrentTimeSec : 0),
            isPlaying: wasPlaying
          };
          if (wasPlaying && typeof window.activatePersistentPiP === 'function') {
            const v = (typeof ytVideosCatalog !== 'undefined' && ytVideosCatalog[activeYtVideoIndex]) ? ytVideosCatalog[activeYtVideoIndex] : null;
            window.activatePersistentPiP({
              title: v ? v.title : 'Watch Stream',
              creator: v ? v.channelName : '@creator',
              videoUrl: (v && v.videoUrl) || (ytVid ? ytVid.src : ''),
              currentTime: ytVid ? ytVid.currentTime : (typeof ytCurrentTimeSec === 'number' ? ytCurrentTimeSec : 0),
              isPlaying: true
            });
            if (ytVid) ytVid.pause();
          } else if (bgAudioOn && wasPlaying) {
            if (window.SovraBackgroundAudioEngine && typeof window.SovraBackgroundAudioEngine.activateMiniBar === 'function') {
              window.SovraBackgroundAudioEngine.activateMiniBar('youtube');
            }
          } else {
            if (ytVid) ytVid.pause();
          }
        }

        // Show 1-Click floating return pill if leaving media to chat/profile
        if (['feed', 'reels', 'youtube'].includes(prevTab) && !['feed', 'reels', 'youtube'].includes(tab)) {
          showFloatingReturnPill(prevTab);
        } else if (['feed', 'reels', 'youtube'].includes(tab)) {
          hideFloatingReturnPill();
        }
      }
      if (tab === 'youtube') {
        const pipOverlay = document.getElementById('persistentPiPOverlay');
        if (pipOverlay && pipOverlay.style.display !== 'none') {
          const pipVid = document.getElementById('persistentPiPVideo');
          const curTime = pipVid ? pipVid.currentTime : 0;
          const wasPaused = pipVid ? pipVid.paused : false;
          if (typeof window.closePersistentPiP === 'function') {
            window.closePersistentPiP();
          }
          const mainVid = document.getElementById('ytMainVideoElement');
          if (mainVid) {
            try { mainVid.currentTime = curTime; } catch(e) {}
            if (!wasPaused) {
              mainVid.play().catch(function() {});
              ytIsPlaying = true;
              const box = document.getElementById('ytPlayerBox');
              if (box) box.classList.add('is-playing');
            }
          }
        } else if (window.SovraPipEngine && typeof window.SovraPipEngine.closePip === 'function') {
          window.SovraPipEngine.closePip();
        }
      }
      if ((tab === 'reels' || tab === 'youtube') && window.SovraBackgroundAudioEngine && typeof window.SovraBackgroundAudioEngine.hideMiniBar === 'function') {
        window.SovraBackgroundAudioEngine.hideMiniBar();
      }
      window._currentActiveTab = tab;
      if (tab !== 'feed' && !window._isHistoryPopping) {
        if (typeof history !== 'undefined' && history.pushState) {
          try {
            history.pushState({ sovraTab: tab }, '', window.location.href);
          } catch (_) {}
        }
      }
      document.body.style.overflow = '';
      document.documentElement.style.overflow = '';

      if (tab !== 'chat') {
        document.body.classList.remove('chat-open');
        const wCont = document.querySelector('.whatsapp-container');
        if (wCont) wCont.classList.remove('show-chat');
      }

      for (const key of Object.keys(views)) {
        if (views[key]) views[key].style.display = key === tab ? 'flex' : 'none';
        if (tabs[key]) {
          const isAct = (key === tab) || (tab === 'reels' && key === 'youtube');
          if (isAct) tabs[key].classList.add('active');
          else tabs[key].classList.remove('active');
        }
      }
      const watchSec = document.getElementById('watchSectionContainer');
      if (watchSec) watchSec.style.display = (tab === 'youtube') ? 'contents' : (watchSec.style.display === 'none' ? 'contents' : watchSec.style.display);
      const tabContentWatch = document.getElementById('tabContentWatch');
      if (tabContentWatch) tabContentWatch.style.display = 'contents';
      if (tab === 'settings' && typeof loadUserSettingsIntoForm === 'function') { loadUserSettingsIntoForm(); }

      for (const key of Object.keys(bnavs)) {
        if (bnavs[key]) {
          const isAct = (key === tab) || (tab === 'reels' && key === 'youtube');
          if (isAct) bnavs[key].classList.add('active');
          else bnavs[key].classList.remove('active');
        }
      }

      // Sync Desktop Top Header Navigation Buttons
      const hnavs = {
        feed: document.getElementById('hnav-feed'),
        youtube: document.getElementById('hnav-youtube'),
        reels: document.getElementById('hnav-reels'),
        chat: document.getElementById('hnav-chat'),
        calls: document.getElementById('hnav-calls'),
        live: document.getElementById('hnav-live'),
        communities: document.getElementById('hnav-communities'),
        hub: document.getElementById('hnav-hub'),
        me: document.getElementById('hnav-me'),
      };
      for (const key of Object.keys(hnavs)) {
        if (hnavs[key]) {
          if (key === tab) hnavs[key].classList.add('active');
          else hnavs[key].classList.remove('active');
        }
      }

      // Sync Sovra Super App Desktop Navigation Buttons (Rule of Simplicity)
      const coreNavs = {
        navTabHome: tab === 'feed',
        navTabWatch: tab === 'youtube' || tab === 'reels',
        navTabFriends: tab === 'friends',
        navTabStudio: tab === 'studio',
        navTabDApps: tab === 'dapps',
        navTabChats: tab === 'chat',
        navTabYou: tab === 'me',
      };
      for (const [id, isActive] of Object.entries(coreNavs)) {
        const el = document.getElementById(id);
        if (el) {
          if (isActive) el.classList.add('active');
          else el.classList.remove('active');
        }
      }
      const navCreate = document.getElementById('navTabCreate');
      if (navCreate) navCreate.classList.remove('active');

      // Sync Watch Hub Segmented Switcher Pills (Shorts | Videos | Live)
      const watchPills = {
        shorts: ['watchSegShorts', 'watchSegShortsReel'],
        videos: ['watchSegVideos', 'watchSegVideosReel'],
        live: ['watchSegLive', 'watchSegLiveReel'],
      };
      const activeWatchSub = (tab === 'reels' ? 'shorts' : (tab === 'live' ? 'live' : (tab === 'youtube' ? 'videos' : null)));
      if (activeWatchSub) {
        Object.keys(watchPills).forEach(sub => {
          const isCurrent = sub === activeWatchSub;
          watchPills[sub].forEach(id => {
            const pill = document.getElementById(id);
            if (pill) {
              if (isCurrent) {
                pill.classList.add('active');
                pill.style.background = 'linear-gradient(135deg, #0284c7, #38bdf8)';
                pill.style.color = '#fff';
                pill.style.boxShadow = '0 2px 8px rgba(56, 189, 248, 0.35)';
              } else {
                pill.classList.remove('active');
                pill.style.background = 'transparent';
                pill.style.color = '#94a3b8';
                pill.style.boxShadow = 'none';
              }
            }
          });
        });
      }

      // Highlight active node in holographic central navigation
      const nodeKeys = { feed: 'holo-node-feed', reels: 'holo-node-reels', youtube: 'holo-node-watch', chat: 'holo-node-chat', me: 'holo-node-profile' };
      document.querySelectorAll('.holo-node-item').forEach(function(n) { n.classList.remove('is-current'); });
      if (nodeKeys[tab]) {
        const cur = document.getElementById(nodeKeys[tab]);
        if (cur) cur.classList.add('is-current');
      }

      // Update body active tab classes
      const allTabNames = ['feed', 'friends', 'reels', 'youtube', 'chat', 'me', 'admin', 'peer-profile', 'channel', 'hub', 'studio', 'calls', 'live', 'communities', 'search', 'notifications', 'settings'];
      allTabNames.forEach(t => document.body.classList.remove('tab-active-' + t));
      document.body.classList.add('tab-active-' + tab);
      document.body.dataset.activeTab = tab;

      // Studio Pro Header Switcher visibility
      const studioHeaderPill = document.getElementById('studioHeaderChanSwitcher');
      if (studioHeaderPill) {
        if (tab === 'studio') {
          studioHeaderPill.style.setProperty('display', 'inline-flex', 'important');
        } else {
          studioHeaderPill.style.setProperty('display', 'none', 'important');
        }
      }
      if (typeof updateSearchScopeForActiveTab === 'function') {
        updateSearchScopeForActiveTab(tab);
      }

      // 🔄 Restore Frozen Tab State (Scroll & Media Playback)
      if (tab === 'feed' || tab === 'friends') {
        const savedY = (tabFreezeState[tab] && tabFreezeState[tab].scrollY) || 0;
        setTimeout(function() {
          window.scrollTo({ top: savedY, behavior: 'instant' });
        }, 15);
      } else if (tab === 'reels') {
        window.scrollTo({ top: 0, behavior: 'instant' });
        setTimeout(function() {
          const reelVid = document.querySelector('#reels-view video');
          if (reelVid && reelVid.paused && tabFreezeState.reels && tabFreezeState.reels.currentTime > 0) {
            try {
              reelVid.currentTime = tabFreezeState.reels.currentTime;
              if (tabFreezeState.reels.isPlaying) reelVid.play().catch(function(){});
            } catch(e) {}
          }
        }, 60);
      } else if (tab === 'youtube') {
        window.scrollTo({ top: 0, behavior: 'instant' });
        if (typeof refreshYtVideosCatalog === 'function') {
          refreshYtVideosCatalog();
        }
        setTimeout(function() {
          const ytVid = document.querySelector('#youtube-view video');
          if (ytVid && ytVid.paused && tabFreezeState.youtube && tabFreezeState.youtube.currentTime > 0) {
            try {
              ytVid.currentTime = tabFreezeState.youtube.currentTime;
              if (ytVid && tabFreezeState.youtube.isPlaying) ytVid.play().catch(function(){});
            } catch(e) {}
          }
        }, 60);
      } else {
        window.scrollTo({ top: 0, behavior: 'instant' });
      }

      // Dynamic layout adjustments for wide views (Watch, Chat, Admin, Studio, Hub, Calls, Live, Communities, Search, Notifications, Settings)
      const rightRail = document.querySelector('.app-right-rail');
      const centerStage = document.querySelector('.app-center-stage');
      const isWideModule = ['youtube', 'chat', 'admin', 'studio', 'hub', 'calls', 'live', 'communities', 'search', 'notifications', 'settings'].includes(tab);
      if (isWideModule) {
        if (rightRail) rightRail.style.display = 'none';
        if (centerStage) {
          centerStage.style.maxWidth = (tab === 'youtube' || tab === 'studio' || tab === 'live' || tab === 'calls') ? '1400px' : (tab === 'hub' ? '1200px' : (tab === 'chat' || tab === 'communities' ? '1300px' : '1080px'));
          centerStage.style.width = '100%';
        }
      } else {
        if (rightRail) {
          rightRail.style.display = window.innerWidth > 1250 ? 'flex' : 'none';
        }
        if (centerStage) {
          centerStage.style.maxWidth = (tab === 'me' || tab === 'peer-profile') ? '920px' : '820px';
          centerStage.style.width = '';
        }
      }

      const stageFooter = document.getElementById('appStageFooter');
      if (stageFooter) {
        stageFooter.style.display = (tab === 'chat' || tab === 'reels' || tab === 'studio' || tab === 'calls' || tab === 'live') ? 'none' : 'block';
      }

      if (tab === 'chat') {
        try {
          localStorage.setItem('sovra_explored_chat', 'true');
          if (typeof updateOnboardingChecklistUI === 'function') updateOnboardingChecklistUI();
        } catch (_) {}
        const wCont = document.querySelector('.whatsapp-container');
        if (wCont && window.innerWidth <= 860) {
          wCont.classList.remove('show-chat');
        }
        if (typeof syncPeersAndContacts === 'function') syncPeersAndContacts();
        if (typeof syncChatMessages === 'function') syncChatMessages();
        renderChatContactsList();
        renderChatBubbles();
      } else if (tab === 'feed') {
        if (typeof updateOnboardingChecklistUI === 'function') updateOnboardingChecklistUI();
      } else if (tab === 'reels') {
        renderCurrentReel();
        fetch('/api/reels/list')
          .then(r => r.json())
          .then(data => {
            if (data.ok && Array.isArray(data.reels)) {
              reelsData = data.reels;
              renderCurrentReel();
            }
          })
          .catch(() => {});
      } else if (tab === 'youtube') {
        renderYtVideo(activeYtVideoIndex, false);
        const ytBal = document.getElementById('ytWalletBalanceDisplay');
        if (ytBal && typeof walletBalanceSov === 'number') {
          ytBal.innerText = walletBalanceSov.toFixed(2) + ' SOV';
        }
      } else if (tab === 'me') {
        renderProfileGrid(currentProfileGridTab || 'posts');
        if (typeof updateProfileDynamicStats === 'function') updateProfileDynamicStats();
        if (typeof renderCreatorHubEntities === 'function') renderCreatorHubEntities();
        if (typeof loadProfileHighlights === 'function') loadProfileHighlights();
        updateDevServerUiModeVisuals();
      } else if (tab === 'friends') {
        if (typeof syncFriendsRelationships === 'function') syncFriendsRelationships();
        renderFriendsDiscoveryView();
        if (window.SovraBleMeshRadar && typeof window.SovraBleMeshRadar.refreshScan === 'function') {
          window.SovraBleMeshRadar.refreshScan();
        }
      } else if (tab === 'studio') {
        var sm = document.getElementById('sovraCreatorStudioModal');
        if (sm) sm.style.display = 'none';
        var wom = document.getElementById('welcomeOnboardingModal');
        if (wom) wom.style.display = 'none';
        if (window.SovraCreatorStudioEngine && typeof window.SovraCreatorStudioEngine.init === 'function') {
          window.SovraCreatorStudioEngine.init();
        }
      } else if (tab === 'hub') {
        if (typeof window.refreshSuperAppHub === 'function') {
          window.refreshSuperAppHub();
        }
      } else if (tab === 'calls') {
        if (typeof initCallsDashboard === 'function') initCallsDashboard();
      } else if (tab === 'live') {
        if (typeof initLiveHeartsStream === 'function') initLiveHeartsStream();
      } else if (tab === 'search') {
        const sInput = document.getElementById('unifiedSearchPageInput');
        if (sInput) setTimeout(() => sInput.focus(), 60);
        if (typeof loadExploreMosaicGrid === 'function') loadExploreMosaicGrid('all');
      } else if (tab === 'notifications') {
        if (typeof syncDedicatedNotificationsFeed === 'function') syncDedicatedNotificationsFeed();
      } else if (tab === 'communities') {
        if (typeof syncCommunitiesFeed === 'function') syncCommunitiesFeed();
      }
    }

    function switchWatchSubTab(subTab) {
      if (subTab === 'shorts') {
        switchTab('reels');
      } else if (subTab === 'live') {
        switchTab('live');
      } else {
        switchTab('youtube');
      }
    }

    // ==========================================
    // 🌐 SOVRA ECOSYSTEM SPECIALIZED MODULE ENGINES
    // ==========================================

    function escapeHtmlClient(str) {
      if (!str) return '';
      return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;').replace(/'/g, '&#039;');
    }

    // --- Module 5: SOVRA Calls Engine ---
    let _callTimerInterval = null;
    let _callDurationSec = 24;
    let _callAudioMuted = false;
    let _callVideoOff = false;
    let _callSpeakerOn = true;

    function initCallsTimer() {
      if (_callTimerInterval) clearInterval(_callTimerInterval);
      _callTimerInterval = setInterval(() => {
        _callDurationSec++;
        const mins = String(Math.floor(_callDurationSec / 60)).padStart(2, '0');
        const secs = String(_callDurationSec % 60).padStart(2, '0');
        const el = document.getElementById('callsTimerPill');
        if (el) el.innerText = mins + ':' + secs;
      }, 1000);
    }

    function startCallQuickAction(peerName) {
      if (typeof switchTab === 'function') switchTab('calls');
      if (peerName) {
        const nEl = document.getElementById('activeCallPeerName');
        const lEl = document.getElementById('remoteCallPeerLabel');
        if (nEl) nEl.innerText = peerName;
        if (lEl) lEl.innerText = peerName;
      }
      _callDurationSec = 0;
      initCallsTimer();
      if (typeof startE2eeCall === 'function') {
        try { startE2eeCall('audio'); } catch (_) {}
      }
      if (typeof showAccountToast === 'function') {
        showAccountToast('📞 Connected to encrypted P2P WebRTC call with ' + (peerName || 'peer') + '!');
      }
    }

    function toggleCallAudio() {
      _callAudioMuted = !_callAudioMuted;
      const btn = document.getElementById('callMicBtn');
      const icon = document.getElementById('callMicIcon');
      if (btn) {
        if (_callAudioMuted) {
          btn.classList.remove('active');
          btn.style.background = 'rgba(239, 68, 68, 0.25)';
          btn.style.borderColor = 'rgba(239, 68, 68, 0.5)';
          if (icon) icon.innerText = '🔇';
          if (typeof showAccountToast === 'function') showAccountToast('Microphone Muted');
        } else {
          btn.classList.add('active');
          btn.style.background = '';
          btn.style.borderColor = '';
          if (icon) icon.innerText = '🎙️';
          if (typeof showAccountToast === 'function') showAccountToast('Microphone Active');
        }
      }
    }

    function toggleCallVideo() {
      _callVideoOff = !_callVideoOff;
      const btn = document.getElementById('callCamBtn');
      const icon = document.getElementById('callCamIcon');
      const pip = document.getElementById('pipSelfFeed');
      if (btn) {
        if (_callVideoOff) {
          btn.classList.remove('active');
          btn.style.background = 'rgba(239, 68, 68, 0.25)';
          btn.style.borderColor = 'rgba(239, 68, 68, 0.5)';
          if (icon) icon.innerText = '📷⃠';
          if (pip) pip.style.opacity = '0.3';
          if (typeof showAccountToast === 'function') showAccountToast('Camera Stopped');
        } else {
          btn.classList.add('active');
          btn.style.background = '';
          btn.style.borderColor = '';
          if (icon) icon.innerText = '📹';
          if (pip) pip.style.opacity = '1';
          if (typeof showAccountToast === 'function') showAccountToast('Camera Active');
        }
      }
    }

    function toggleCallSpeaker() {
      _callSpeakerOn = !_callSpeakerOn;
      const btn = document.getElementById('callSpeakerBtn');
      if (btn) {
        if (_callSpeakerOn) {
          btn.classList.add('active');
          if (typeof showAccountToast === 'function') showAccountToast('Speaker Output: High Fidelity');
        } else {
          btn.classList.remove('active');
          if (typeof showAccountToast === 'function') showAccountToast('Audio routed to Earpiece / Headset');
        }
      }
    }

    function toggleCallScreenShare() {
      const btn = document.getElementById('callShareBtn');
      if (btn) {
        const isSharing = btn.classList.toggle('active');
        if (typeof showAccountToast === 'function') {
          showAccountToast(isSharing ? '🖥️ Screen Sharing WebRTC Session Active' : 'Screen Share Stopped');
        }
      }
    }

    function terminateActiveCall() {
      if (_callTimerInterval) clearInterval(_callTimerInterval);
      if (typeof showAccountToast === 'function') {
        showAccountToast('Call ended • Duration: ' + (document.getElementById('callsTimerPill') ? document.getElementById('callsTimerPill').innerText : '00:24'));
      }
      setTimeout(() => {
        if (typeof switchTab === 'function') switchTab('feed');
      }, 400);
    }

    // --- Module 6: SOVRA Live Stream Engine ---
    let _liveHeartsInterval = null;
    function initLiveHeartsStream() {
      if (_liveHeartsInterval) clearInterval(_liveHeartsInterval);
      _liveHeartsInterval = setInterval(() => {
        if (document.body.dataset.activeTab === 'live' && Math.random() > 0.4) {
          spawnFloatingHeart();
        }
      }, 1600);
    }

    function spawnFloatingHeart(emoji) {
      const layer = document.getElementById('liveFloatingHeartsLayer');
      if (!layer) return;
      const heart = document.createElement('div');
      heart.innerText = emoji || (Math.random() > 0.5 ? '❤️' : (Math.random() > 0.5 ? '🔥' : '✨'));
      heart.style.position = 'absolute';
      heart.style.bottom = '0';
      heart.style.left = Math.floor(Math.random() * 50) + 'px';
      heart.style.fontSize = (1.2 + Math.random() * 0.8) + 'rem';
      heart.style.opacity = '1';
      heart.style.transition = 'all 2.4s cubic-bezier(0.25, 1, 0.5, 1)';
      heart.style.pointerEvents = 'none';
      layer.appendChild(heart);
      setTimeout(() => {
        heart.style.transform = 'translateY(-260px) scale(1.4)';
        heart.style.opacity = '0';
      }, 50);
      setTimeout(() => {
        if (heart.parentNode) heart.parentNode.removeChild(heart);
      }, 2500);
    }

    function sendLiveHeartReaction() {
      for (let i = 0; i < 4; i++) {
        setTimeout(() => spawnFloatingHeart('❤️'), i * 120);
      }
      if (typeof showAccountToast === 'function') showAccountToast('Sent reaction! ❤️');
    }

    function sendLiveComment(e) {
      if (e) e.preventDefault();
      const input = document.getElementById('liveChatInput');
      if (!input || !input.value.trim()) return;
      const text = input.value.trim();
      input.value = '';
      const list = document.getElementById('liveChatMessagesList');
      if (list) {
        const msg = document.createElement('div');
        msg.className = 'live-chat-msg';
        msg.innerHTML = '<span class="chat-author" style="color: #38bdf8;">You:</span> <span class="chat-text">' + escapeHtmlClient(text) + '</span>';
        list.appendChild(msg);
        list.scrollTop = list.scrollHeight;
      }
      spawnFloatingHeart('💬');
    }

    function openLiveGiftModal(giftName, amount) {
      if (typeof walletBalanceSov === 'number' && walletBalanceSov < amount) {
        if (typeof showAccountToast === 'function') showAccountToast('Insufficient SOV balance (' + walletBalanceSov.toFixed(2) + ' SOV). Top up your wallet in Profile.');
        return;
      }
      if (typeof walletBalanceSov === 'number') {
        walletBalanceSov -= amount;
      }
      spawnFloatingHeart('🎁');
      spawnFloatingHeart('🪙');
      const list = document.getElementById('liveChatMessagesList');
      if (list) {
        const msg = document.createElement('div');
        msg.className = 'live-chat-msg';
        msg.style.background = 'rgba(245, 158, 11, 0.15)';
        msg.style.border = '1px solid rgba(245, 158, 11, 0.3)';
        msg.style.borderRadius = '8px';
        msg.style.padding = '4px 8px';
        msg.innerHTML = '<span class="chat-author" style="color: #facc15;">You:</span> <span class="chat-text">Tipped <strong>' + giftName + ' (' + amount + ' SOV)</strong>! 🪙</span>';
        list.appendChild(msg);
        list.scrollTop = list.scrollHeight;
      }
      if (typeof showAccountToast === 'function') {
        showAccountToast('🎁 Successfully sent ' + giftName + ' (' + amount + ' SOV) to streamer!');
      }
    }

    function toggleLiveHostFollow() {
      const btn = document.getElementById('btnLiveFollowHost');
      if (!btn) return;
      if (btn.classList.contains('following')) {
        btn.classList.remove('following');
        btn.innerText = '+ Follow';
        btn.style.background = 'rgba(56, 189, 248, 0.15)';
        btn.style.color = '#38bdf8';
        if (typeof showAccountToast === 'function') showAccountToast('Unfollowed @rohit_live');
      } else {
        btn.classList.add('following');
        btn.innerText = 'Following ✓';
        btn.style.background = 'rgba(34, 197, 94, 0.15)';
        btn.style.color = '#4ade80';
        if (typeof showAccountToast === 'function') showAccountToast('Following @rohit_live! You will receive live alerts.');
      }
    }

    let _activeLiveMediaStream = null;

    async function toggleSovereignLiveBroadcast() {
      if (_activeLiveMediaStream) {
        stopSovereignLiveBroadcast();
      } else {
        await startSovereignLiveBroadcast();
      }
    }
    window.toggleSovereignLiveBroadcast = toggleSovereignLiveBroadcast;

    async function startSovereignLiveBroadcast() {
      const btn = document.getElementById('btnSovereignLiveToggle');
      const inner = document.getElementById('liveVideoPlayerInner');
      if (!navigator.mediaDevices || !navigator.mediaDevices.getUserMedia) {
        if (typeof showAccountToast === 'function') {
          showAccountToast('⚠️ WebRTC MediaStream is not supported by this browser environment');
        }
        return;
      }

      if (typeof showAccountToast === 'function') {
        showAccountToast('🎥 Initializing camera & microphone for WebRTC broadcast...');
      }

      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { width: { ideal: 1280 }, height: { ideal: 720 }, facingMode: 'user' },
          audio: true,
        });
        _activeLiveMediaStream = stream;

        if (inner) {
          let videoEl = document.getElementById('sovraLiveBroadcastVideo');
          if (!videoEl) {
            videoEl = document.createElement('video');
            videoEl.id = 'sovraLiveBroadcastVideo';
            videoEl.autoplay = true;
            videoEl.playsInline = true;
            videoEl.muted = true;
            videoEl.style.cssText = 'width: 100%; height: 100%; object-fit: cover; display: block; position: absolute; top: 0; left: 0; z-index: 10; border-radius: 16px;';
            inner.appendChild(videoEl);
          }
          videoEl.srcObject = stream;
          videoEl.style.display = 'block';
        }

        if (btn) {
          btn.innerText = '🔴 End Stream';
          btn.style.background = 'linear-gradient(135deg, #ef4444, #991b1b)';
          btn.style.boxShadow = '0 0 15px rgba(239, 68, 68, 0.6)';
        }

        if (typeof showAccountToast === 'function') {
          showAccountToast('🔴 LIVE: Sovereign WebRTC Broadcast Active! Streaming to mesh peers.');
        }
      } catch (err) {
        if (typeof showAccountToast === 'function') {
          showAccountToast('⚠️ Media access error: ' + (err.message || 'Permission denied'));
        }
      }
    }
    window.startSovereignLiveBroadcast = startSovereignLiveBroadcast;

    function stopSovereignLiveBroadcast() {
      if (_activeLiveMediaStream) {
        _activeLiveMediaStream.getTracks().forEach(track => {
          try { track.stop(); } catch (_) {}
        });
        _activeLiveMediaStream = null;
      }

      const videoEl = document.getElementById('sovraLiveBroadcastVideo');
      if (videoEl) {
        videoEl.srcObject = null;
        videoEl.style.display = 'none';
      }

      const btn = document.getElementById('btnSovereignLiveToggle');
      if (btn) {
        btn.innerText = 'Go Live';
        btn.style.background = 'linear-gradient(135deg, #ef4444, #dc2626)';
        btn.style.boxShadow = 'none';
      }

      if (typeof showAccountToast === 'function') {
        showAccountToast('⏹️ Live stream terminated. Broadcast stats recorded to ledger.');
      }
    }
    window.stopSovereignLiveBroadcast = stopSovereignLiveBroadcast;

