    window.renderFilteredFeedByAlgoMode = function(mode) {
      const container = document.getElementById('feedPostsStream');
      if (!container || !Array.isArray(feedPostsData)) return;

      var posts = feedPostsData.slice();
      if (mode === 'friends') {
        var friendDids = new Set((typeof contactsData !== 'undefined' ? contactsData : []).map(function(c) { return c.did || c.id; }));
        if (myProfile && myProfile.did) friendDids.add(myProfile.did);
        posts = posts.filter(function(p) { return friendDids.has(p.authorDid) || (p.authorHandle && friendDids.has(p.authorHandle)); });
      } else if (mode === 'chrono') {
        posts.sort(function(a, b) { return (b.timestamp || b.createdAt || 0) - (a.timestamp || a.createdAt || 0); });
      } else {
        posts.sort(function(a, b) {
          var scoreA = ((a.tipsCount || a.tip_amount || 0) * 2) + (a.likesCount || 0) + ((a.comments || []).length * 1.5) - (a.reportsCount || 0);
          var scoreB = ((b.tipsCount || b.tip_amount || 0) * 2) + (b.likesCount || 0) + ((b.comments || []).length * 1.5) - (b.reportsCount || 0);
          return scoreB - scoreA;
        });
      }

      container.querySelectorAll('.insta-post-card').forEach(function(c) { c.remove(); });
      posts.forEach(function(p) { renderDynamicPostCard(p, false); });
      showAccountToast('⚖️ Filter applied: ' + (mode === 'friends' ? '👥 Friends Only' : (mode === 'chrono' ? '⏱ Chronological' : '⚡ Viral Consensus')));
    };

    function syncFeedPosts() {
      // 💾 Browser Local-First CRDT Hydration: Load instantly from IndexedDB before network fetch
      if (window.SovraClientStore && (!feedPostsData || feedPostsData.length === 0)) {
        window.SovraClientStore.getAll('feed_posts_cache').then(function(cachedPosts) {
          if (Array.isArray(cachedPosts) && cachedPosts.length > 0 && (!feedPostsData || feedPostsData.length === 0)) {
            cachedPosts.sort(function(a, b) { return (b.timestamp || 0) - (a.timestamp || 0); });
            cachedPosts.forEach(function(cp) {
              if (!feedPostsData.find(function(ex) { return ex.id === cp.id; })) {
                feedPostsData.push(cp);
                renderDynamicPostCard(cp, false);
              }
            });
          }
        }).catch(function() {});
      }

      const sessionToken = (myProfile && myProfile.sessionToken) ? myProfile.sessionToken : (localStorage.getItem('sovra_session_token') || '');
      const reqHeaders = {};
      if (sessionToken) reqHeaders['Authorization'] = 'Bearer ' + sessionToken;

      fetch('/api/feed/list', { headers: reqHeaders })
        .then(function(r) { return r.json(); })
        .then(function(data) {
          if (data && data.ok && Array.isArray(data.posts)) {
            let hasNew = false;
            const myDid = myProfile ? myProfile.did : 'did:sovra:self';

            for (let i = data.posts.length - 1; i >= 0; i--) {
              const p = data.posts[i];
              // 💾 Persist to local-first IndexedDB
              if (window.SovraClientStore) {
                window.SovraClientStore.put('feed_posts_cache', p).catch(function() {});
              }
              const existing = feedPostsData.find(function(ex) { return ex.id === p.id; });
              if (!existing) {
                feedPostsData.unshift(p);
                renderDynamicPostCard(p, true);
                hasNew = true;
              } else {
                if (existing.likesCount !== p.likesCount || JSON.stringify(existing.likedByDids) !== JSON.stringify(p.likedByDids) || JSON.stringify(existing.reactions) !== JSON.stringify(p.reactions)) {
                  existing.likesCount = p.likesCount;
                  existing.likedByDids = p.likedByDids || [];
                  existing.reactions = p.reactions || {};

                  const rowEl = document.getElementById('likes-row-' + p.id);
                  if (rowEl) {
                    rowEl.outerHTML = renderReactionsSummaryHtml(p);
                  }

                  const myReaction = p.reactions ? p.reactions[myDid] : null;
                  const isLikedByMe = myReaction ? true : (Array.isArray(p.likedByDids) ? p.likedByDids.includes(myDid) : Boolean(p.isLiked));
                  const btnLike = document.getElementById('btn-like-' + p.id);
                  if (btnLike) {
                    btnLike.innerHTML = getPostLikeSvg(isLikedByMe, myReaction);
                    if (isLikedByMe) btnLike.classList.add('active-like');
                    else btnLike.classList.remove('active-like');
                  }
                }
                if (Array.isArray(p.comments)) {
                  existing.comments = p.comments;
                  const commentsBox = document.getElementById('comments-box-' + p.id);
                  if (commentsBox) {
                    let cHtml = '';
                    if (p.comments && p.comments.length > 0) {
                      cHtml = '<div style="color: #94a3b8; font-size: 0.8rem; font-weight: 500; cursor: pointer; margin-bottom: 4px;" onclick="focusFeedComment(&quot;' + p.id + '&quot;)">View all ' + p.comments.length + ' comments</div>';
                    }
                    p.comments.forEach(function(c) {
                      const isMe = (c.authorDid && c.authorDid === myDid) || c.author === (myProfile ? myProfile.name : 'You (Me)');
                      cHtml += renderCommentItemHtml(p.id, c, isMe, p.authorDid);
                    });
                    commentsBox.innerHTML = cHtml;
                  }
                }
                if (JSON.stringify(existing.surveyData) !== JSON.stringify(p.surveyData) ||
                    JSON.stringify(existing.pollData) !== JSON.stringify(p.pollData) ||
                    JSON.stringify(existing.qaData) !== JSON.stringify(p.qaData)) {
                  existing.surveyData = p.surveyData;
                  existing.pollData = p.pollData;
                  existing.qaData = p.qaData;
                  const oldCard = document.getElementById('card-' + p.id);
                  if (oldCard) {
                    const nextSib = oldCard.nextSibling;
                    const parent = oldCard.parentNode;
                    oldCard.remove();
                    renderDynamicPostCard(p, false);
                    const newCard = document.getElementById('card-' + p.id);
                    if (newCard && nextSib && parent) {
                      parent.insertBefore(newCard, nextSib);
                    }
                  }
                }
              }
            }
            if (hasNew) {
              updateProfileDynamicStats();
              if (typeof initPostImpressionObserver === 'function') initPostImpressionObserver();
            }
          }
          hideFeedSkeleton();
        })
        .catch(function() {
          hideFeedSkeleton();
        });
    }
    setInterval(function() {
      if (!document.hidden) syncFeedPosts();
    }, 5000);

