    function switchPublicChannelTab(tab) {
      ['videos', 'shorts', 'playlists', 'about'].forEach(function(t) {
        const btn = document.getElementById('publicChannelTab' + t.charAt(0).toUpperCase() + t.slice(1)) ||
                    document.getElementById('chTab' + t.charAt(0).toUpperCase() + t.slice(1));
        if (btn) {
          if (t === tab) {
            btn.classList.add('active');
            btn.style.color = '#38bdf8';
          } else {
            btn.classList.remove('active');
            btn.style.color = '#94a3b8';
          }
        }
      });
      switchChannelModalTab(tab);
      const mainContent = document.getElementById('chTabContent');
      const publicContent = document.getElementById('publicChannelTabContent');
      if (mainContent && publicContent && mainContent !== publicContent) {
        publicContent.innerHTML = mainContent.innerHTML;
      }
    }
    window.switchPublicChannelTab = switchPublicChannelTab;

    function switchChannelModalTab(tab) {
      const tabs = ['videos', 'playlists', 'community', 'about'];
      tabs.forEach(function(t) {
        const btn = document.getElementById('chTab' + t.charAt(0).toUpperCase() + t.slice(1));
        if (btn) {
          if (t === tab) btn.classList.add('active');
          else btn.classList.remove('active');
        }
      });

      const container = document.getElementById('chTabContent');
      if (!container) return;
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const chHandle = (v.channelHandle || '').replace('@', '').toLowerCase();
      const chName = v.channelName || 'Verified Channel';

      const chVideos = ytVideosCatalog.filter(vid => {
        const vh = (vid.channelHandle || '').replace('@', '').toLowerCase();
        return vh === chHandle || vid.channelName === chName;
      });
      const displayVideos = chVideos.length > 0 ? chVideos : ytVideosCatalog;

      if (tab === 'videos') {
        let sortMode = window.__chSortMode || 'latest';
        let sortedVideos = [...displayVideos];
        if (sortMode === 'popular') {
          sortedVideos.sort((a, b) => (b.views || 0) - (a.views || 0));
        }

        let html = '<div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 0.65rem;">' +
          '<span style="font-weight: 700; color: #fff; font-size: 0.88rem;">Channel Broadcasts (' + sortedVideos.length + ')</span>' +
          '<div style="display: flex; gap: 0.4rem;">' +
            '<button class="btn btn-secondary" style="font-size: 0.72rem; padding: 3px 8px;' + (sortMode === 'latest' ? ' background: rgba(56,189,248,0.25); color: #38bdf8;' : '') + '" onclick="window.__chSortMode=&quot;latest&quot;; switchChannelModalTab(&quot;videos&quot;)">Latest</button>' +
            '<button class="btn btn-secondary" style="font-size: 0.72rem; padding: 3px 8px;' + (sortMode === 'popular' ? ' background: rgba(56,189,248,0.25); color: #38bdf8;' : '') + '" onclick="window.__chSortMode=&quot;popular&quot;; switchChannelModalTab(&quot;videos&quot;)">Popular</button>' +
          '</div>' +
        '</div>' +
        '<div style="display: flex; flex-direction: column; gap: 0.5rem; max-height: 280px; overflow-y: auto;">';

        html += sortedVideos.map(vid => {
          const globalIdx = ytVideosCatalog.findIndex(item => item.id === vid.id);
          const viewsFmt = (vid.views || 0).toLocaleString() + ' views';
          const dur = vid.duration || '0:30';
          const res = (vid.variants && vid.variants[0]) ? vid.variants[0].resolution : '4K UHD';
          return '<div style="background: rgba(0,0,0,0.35); border: 1px solid rgba(255,255,255,0.08); padding: 0.55rem 0.75rem; border-radius: 8px; display: flex; justify-content: space-between; align-items: center; cursor: pointer; transition: all 0.2s;" onmouseover="this.style.background=&quot;rgba(56,189,248,0.1)&quot;" onmouseout="this.style.background=&quot;rgba(0,0,0,0.35)&quot;" onclick="closeYtModal(&quot;channelProfileModal&quot;); renderYtVideo(' + (globalIdx >= 0 ? globalIdx : 0) + ', true);">' +
            '<div style="display: flex; align-items: center; gap: 0.6rem; min-width: 0;">' +
              '<span style="font-size: 1.1rem;">🎬</span>' +
              '<div style="min-width: 0;">' +
                '<div style="font-weight: 600; font-size: 0.82rem; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 260px;">' + vid.title + '</div>' +
                '<div style="font-size: 0.72rem; color: #94a3b8;">' + (vid.publishedAt || 'Uploaded') + ' &bull; ' + dur + '</div>' +
              '</div>' +
            '</div>' +
            '<div style="text-align: right; flex-shrink: 0;">' +
              '<div style="color: #34d399; font-size: 0.74rem; font-weight: 600;">' + viewsFmt + '</div>' +
              '<span style="font-size: 0.68rem; color: #818cf8; background: rgba(99,102,241,0.15); padding: 1px 6px; border-radius: 4px;">' + res + '</span>' +
            '</div>' +
          '</div>';
        }).join('');

        html += '</div>';
        container.innerHTML = html;
      } else if (tab === 'playlists') {
        fetch('/api/playlists?channelId=' + encodeURIComponent(v.channelHandle || ''))
          .then(r => r.json())
          .then(data => {
            const pls = (data.ok && Array.isArray(data.playlists) && data.playlists.length > 0) ? data.playlists : [
              { title: '📑 ' + (v.channelName || 'Channel') + ' Master Series', count: displayVideos.length, updated: 'Active Swarm' },
              { title: '📑 High-Bitrate P2P DAG Streams', count: Math.max(1, Math.floor(displayVideos.length / 2)), updated: 'RFC 8216 HLS' }
            ];
            container.innerHTML = '<div style="display: flex; flex-direction: column; gap: 0.5rem;">' +
              pls.map(p =>
                '<div style="background: rgba(0,0,0,0.35); border: 1px solid rgba(255,255,255,0.08); padding: 0.7rem; border-radius: 8px; cursor: pointer;" onclick="if (typeof showAccountToast === &quot;function&quot;) showAccountToast(&quot;📁 Playlist opened: ' + (p.title || p.name).replace(/"/g, '') + '&quot;);">' +
                  '<div style="font-weight: 700; color: #fff; font-size: 0.85rem;">' + (p.title || p.name) + ' (' + (p.count || (p.videoIds ? p.videoIds.length : 1)) + ' videos)</div>' +
                  '<div style="font-size: 0.74rem; color: #94a3b8; margin-top: 3px;">' + (p.description || ('Curated by @' + chHandle + ' &bull; ' + (p.updated || 'Dynamic Swarm'))) + '</div>' +
                '</div>'
              ).join('') +
            '</div>';
          })
          .catch(() => {
            container.innerHTML = '<div style="color: #94a3b8; font-size: 0.82rem; padding: 1rem 0;">No playlists available for this channel.</div>';
          });
      } else if (tab === 'community') {
        const pollVoted = window.__sovraCommunityPollVoted;
        container.innerHTML = '<div style="display: flex; flex-direction: column; gap: 0.6rem;">' +
          '<div style="background: rgba(0,0,0,0.35); border: 1px solid rgba(255,255,255,0.08); padding: 0.75rem; border-radius: 8px;">' +
            '<div style="display: flex; justify-content: space-between; align-items: center;">' +
              '<div style="font-size: 0.75rem; color: #38bdf8; font-weight: 700;">Pinned Community Poll &bull; Active Swarm</div>' +
              '<span style="font-size: 0.7rem; color: #34d399; background: rgba(16,185,129,0.15); padding: 2px 6px; border-radius: 4px;">Live</span>' +
            '</div>' +
            '<div style="margin-top: 6px; color: #fff; font-size: 0.84rem; font-weight: 600;">Which audio codec standard should we deploy for upcoming 8K spatial streams?</div>' +
            '<div style="margin-top: 8px; display: flex; flex-direction: column; gap: 4px;">' +
              '<button class="btn btn-secondary" style="text-align: left; font-size: 0.78rem; padding: 6px 10px; display: flex; justify-content: space-between;' + (pollVoted === 1 ? ' border-color: #38bdf8; color: #38bdf8;' : '') + '" onclick="window.__sovraCommunityPollVoted = 1; switchChannelModalTab(&quot;community&quot;);">' +
                '<span>1. Opus Multi-Channel (Spatial 5.1/7.1)</span>' +
                '<span style="color: #34d399; font-weight: 700;">' + (pollVoted ? '76%' : 'Vote') + '</span>' +
              '</button>' +
              '<button class="btn btn-secondary" style="text-align: left; font-size: 0.78rem; padding: 6px 10px; display: flex; justify-content: space-between;' + (pollVoted === 2 ? ' border-color: #38bdf8; color: #38bdf8;' : '') + '" onclick="window.__sovraCommunityPollVoted = 2; switchChannelModalTab(&quot;community&quot;);">' +
                '<span>2. FLAC 24-bit Lossless Studio Master</span>' +
                '<span style="color: #34d399; font-weight: 700;">' + (pollVoted ? '24%' : 'Vote') + '</span>' +
              '</button>' +
            '</div>' +
          '</div>' +
        '</div>';
      } else if (tab === 'about') {
        const totalViews = displayVideos.reduce((acc, curr) => acc + (curr.views || 0), 0);
        const subCount = v.channelSubscribers ? v.channelSubscribers.toLocaleString() : (v.channelSubscribersText || '142K');
        container.innerHTML = '<div style="display: flex; flex-direction: column; gap: 0.6rem; font-size: 0.82rem; line-height: 1.6; color: #cbd5e1;">' +
          '<div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.08); padding-bottom: 4px;">' +
            '<span style="color: #94a3b8;">Channel Handle:</span>' +
            '<span style="font-weight: 600; color: #38bdf8;">@' + chHandle + '</span>' +
          '</div>' +
          '<div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.08); padding-bottom: 4px;">' +
            '<span style="color: #94a3b8;">Subscribers:</span>' +
            '<span style="font-weight: 600; color: #fff;">' + subCount + '</span>' +
          '</div>' +
          '<div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.08); padding-bottom: 4px;">' +
            '<span style="color: #94a3b8;">Total Views:</span>' +
            '<span style="font-weight: 600; color: #34d399;">' + totalViews.toLocaleString() + ' views</span>' +
          '</div>' +
          '<div style="display: flex; justify-content: space-between; border-bottom: 1px solid rgba(255,255,255,0.08); padding-bottom: 4px;">' +
            '<span style="color: #94a3b8;">Public Videos:</span>' +
            '<span style="font-weight: 600; color: #fff;">' + displayVideos.length + ' broadcasts</span>' +
          '</div>' +
          '<div style="margin-top: 4px; padding: 6px 10px; background: rgba(99,102,241,0.1); border: 1px solid rgba(99,102,241,0.25); border-radius: 6px;">' +
            '<div style="font-size: 0.72rem; color: #818cf8; font-weight: 700; text-transform: uppercase;">Cryptographic Identity DID</div>' +
            '<code style="font-size: 0.73rem; color: #cbd5e1; word-break: break-all;">did:sovra:channel:' + chHandle + '</code>' +
          '</div>' +
        '</div>';
      }
    }

    function openMembershipModal() {
      openYtModal('membershipModal');
    }

    function selectMembershipTier(cardEl, tierName, price) {
      document.querySelectorAll('.membership-tier-card').forEach(c => c.classList.remove('selected'));
      if (cardEl) cardEl.classList.add('selected');
      selectedMembershipTier = { name: tierName, price: price };
    }

    function confirmMembership() {
      closeYtModal('membershipModal');
      spawnConfetti();
      const v = ytVideosCatalog[activeYtVideoIndex];
      showAccountToast('Channel Membership Activated: Joined ' + (v ? v.channelName : 'Channel') + ' as ' + selectedMembershipTier.name + ' (₹' + selectedMembershipTier.price + '/mo)! Signed with Ed25519 identity key.');
    }

    function openSuperThanksModal() {
      const balEl = document.getElementById('superThanksAvailableBalance');
      if (balEl && typeof walletBalanceSov === 'number') {
        balEl.innerText = walletBalanceSov.toFixed(2) + ' SOV';
      }
      openYtModal('superThanksModal');
      updateSuperThanksSplitPreview(100);
    }

    function selectSuperThanksAmount(amt) {
      const input = document.getElementById('superThanksAmountInput');
      if (input) input.value = amt;
      updateSuperThanksSplitPreview(amt);
    }

    function updateSuperThanksSplitPreview(amt) {
      const val = parseFloat(amt) || 0;
      const creator = (val * 0.95).toFixed(2);
      const seeders = (val * 0.05).toFixed(2);
      const preview = document.getElementById('superThanksSplitPreview');
      if (preview) {
        preview.innerHTML = 'Split breakdown: <b>₹' + creator + ' (95%)</b> to Creator, <b>₹' + seeders + ' (5%)</b> to Seeders, <b>₹0.00 (0%)</b> to Platform.';
      }
    }

    function submitSuperThanks() {
      const amtInput = document.getElementById('superThanksAmountInput');
      const msgInput = document.getElementById('superThanksMessageInput');
      const amt = parseFloat(amtInput ? amtInput.value : '100') || 100;
      const msg = msgInput ? msgInput.value.trim() : 'Super Thanks for the sovereign streaming architecture!';
      closeYtModal('superThanksModal');
      sendCreatorTip(amt, msg);
    }

    async function sendCreatorTip(amount, customMessage) {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;

      const creatorAmt = (amount * 0.95).toFixed(2);
      const seederAmt = (amount * 0.05).toFixed(2);

      // ⚡ Pillar 5: Generate P2P Signed Off-Chain Micropayment Voucher
      let signedVoucher = null;
      if (window.SovraPaymentVoucher) {
        try {
          const myDid = (window.SovraCryptoVault ? window.SovraCryptoVault.getDid() : null) || (myProfile ? myProfile.did : 'did:sovra:self');
          signedVoucher = await window.SovraPaymentVoucher.createSignedVoucher({
            amount: amount,
            creatorDid: 'did:sovra:' + v.channelHandle,
            senderDid: myDid,
            asset: 'SOV'
          });
          if (signedVoucher && typeof renderWalletVouchers === 'function') {
            renderWalletVouchers([signedVoucher]);
          }
        } catch (e) { console.warn('[PaymentVoucher] Creation error:', e); }
      }

      const notice = document.getElementById('tipStatusNotice');
      if (notice) {
        const rootHashStr = signedVoucher ? (' Root: <code>' + signedVoucher.rootHash + '…</code>') : '';
        notice.innerHTML = '⚡ <b>P2P State Channel Voucher Signed' + rootHashStr + '</b>: <b style="color:#fbbf24;">₹' + creatorAmt + ' (95%)</b> to ' + v.channelName + ', <b style="color:#34d399;">₹' + seederAmt + ' (5%)</b> to BitSwap Seeders, <b style="color:#38bdf8;">0% Gas Fees</b> (Instant Netting).';
      }

      spawnConfetti();

      if (customMessage) {
        if (!ytCommentsDatabase[v.id]) ytCommentsDatabase[v.id] = [];
        ytCommentsDatabase[v.id].unshift({
          id: 'yt-st-' + Date.now(),
          videoId: v.id,
          authorName: 'You (Super Supporter)',
          authorAvatar: 'Y',
          authorHandle: 'you_peer',
          text: customMessage,
          timestamp: Date.now(),
          likes: 5,
          isSuperThanks: true,
          superThanksAmount: '₹' + amount,
          creatorHeart: true,
          replies: []
        });
        renderYtComments('top');
      }

      try {
        const myDid = (window.SovraCryptoVault ? window.SovraCryptoVault.getDid() : null) || (myProfile ? myProfile.did : undefined);
        const resp = await fetch('/api/youtube/tip', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            amount: amount,
            videoId: v.id,
            creatorDid: 'did:sovra:' + v.channelHandle,
            message: customMessage,
            authorName: myProfile ? myProfile.name : 'You (Super Supporter)',
            fromDid: myDid,
            senderDid: myDid,
            voucher: signedVoucher || undefined,
            signature: signedVoucher ? signedVoucher.signatureHex : undefined,
            nonce: signedVoucher ? signedVoucher.nonce : ('tip_nc_' + Date.now()),
            timestamp: signedVoucher ? signedVoucher.timestamp : Date.now(),
          }),
        });
        const data = await resp.json();
        if (data.ok) {
          if (typeof data.newBalance === 'number') {
            walletBalanceSov = data.newBalance;
            const sovEl = document.getElementById('walletBalanceSovDisplay');
            if (sovEl) sovEl.innerText = walletBalanceSov.toFixed(2) + ' SOV';
            const fiatEl = document.getElementById('walletBalanceFiatDisplay');
            if (fiatEl) fiatEl.innerText = '≈ $' + (walletBalanceSov * 3.0).toFixed(2) + ' USD';
            const ytBalEl = document.getElementById('ytWalletBalanceDisplay');
            if (ytBalEl) ytBalEl.innerText = walletBalanceSov.toFixed(2) + ' SOV';
            const stBalEl = document.getElementById('superThanksAvailableBalance');
            if (stBalEl) stBalEl.innerText = walletBalanceSov.toFixed(2) + ' SOV';
          }
        } else if (data.error) {
          showAccountToast('Tip failed: ' + data.error);
        }
      } catch (err) {}
    }

    let currentYtCategoryFilter = 'all';

    function filterYtCategory(cat, el) {
      currentYtCategoryFilter = cat;
      const chips = document.querySelectorAll('.yt-cat-chip');
      chips.forEach(c => {
        c.classList.remove('active');
        c.style.background = 'rgba(255,255,255,0.06)';
        c.style.color = '#cbd5e1';
      });
      if (el) {
        el.classList.add('active');
        el.style.background = '#38bdf8';
        el.style.color = '#000';
      }
      renderYtRecommendations();
    }
    window.filterYtCategory = filterYtCategory;

    function toggleLiveSwarmChat() {
      const body = document.getElementById('ytLiveSwarmChatBody');
      const btn = document.getElementById('ytLiveSwarmChatToggleBtn');
      if (!body) return;
      if (body.style.display === 'none') {
        body.style.display = 'flex';
        if (btn) btn.innerText = 'Hide';
      } else {
        body.style.display = 'none';
        if (btn) btn.innerText = 'Show';
      }
    }
    window.toggleLiveSwarmChat = toggleLiveSwarmChat;

    function sendLiveSwarmChatMessage() {
      const input = document.getElementById('ytLiveSwarmChatInput');
      if (!input) return;
      const val = input.value.trim();
      if (!val) return;
      input.value = '';
      const list = document.getElementById('ytLiveSwarmChatMessages');
      if (list) {
        const item = document.createElement('div');
        item.style.color = '#cbd5e1';
        item.innerHTML = '<span style="color: #38bdf8; font-weight: 700;">You:</span> ' + val.replace(/</g, '&lt;').replace(/>/g, '&gt;');
        list.appendChild(item);
        list.scrollTop = list.scrollHeight;
      }
    }
    window.sendLiveSwarmChatMessage = sendLiveSwarmChatMessage;

    function renderYtRecommendations() {
      const container = document.getElementById('ytRecommendationsList');
      if (!container) return;
      let list = ytVideosCatalog.map((vid, idx) => ({ vid, idx }));
      if (currentYtCategoryFilter === 'protocol') {
        list = list.filter(item => (item.idx % 2 === 0) || (item.vid.tags && item.vid.tags.some(t => t.toLowerCase().includes('p2p') || t.toLowerCase().includes('protocol'))));
      } else if (currentYtCategoryFilter === '4k') {
        list = list.filter(item => (item.idx % 2 === 1) || (item.vid.title && item.vid.title.includes('4K')));
      } else if (currentYtCategoryFilter === 'cyber') {
        list = list.filter(item => (item.vid.title && (item.vid.title.includes('Cyber') || item.vid.title.includes('Security') || item.vid.title.includes('Identity'))) || item.idx === 1);
      } else if (currentYtCategoryFilter === 'seeders') {
        list = list.filter(item => (item.vid.title && (item.vid.title.includes('BitSwap') || item.vid.title.includes('Swarm'))) || item.idx === 0);
      }
      if (list.length === 0) {
        list = ytVideosCatalog.map((vid, idx) => ({ vid, idx }));
      }
      container.innerHTML = list.map(({ vid, idx }) => {
        const isActive = idx === activeYtVideoIndex;
        const activeClass = isActive ? ' active-video' : '';
        const badge = isActive ? '<span class="yt-p2p-badge" style="background:#6366f1; color:#fff;">▶ PLAYING</span>' : '<span class="yt-p2p-badge">P2P 4K</span>';
        const icons = ['🌐', '📡', '🔐', '⚡'];
        return '<div class="yt-sidebar-card' + activeClass + '" onclick="switchYtVideo(' + idx + ')">' +
          '<div class="yt-thumbnail" style="background: ' + vid.gradient + ';">' +
            badge +
            '<span>' + icons[idx % icons.length] + '</span>' +
            '<span class="yt-duration-badge">' + vid.duration + '</span>' +
          '</div>' +
          '<div style="flex: 1; min-width: 0;">' +
            '<div style="font-size: 0.82rem; font-weight: 600; color: #f1f5f9; line-height: 1.35; display: -webkit-box; -webkit-line-clamp: 2; -webkit-box-orient: vertical; overflow: hidden;">' +
              vid.title +
            '</div>' +
            '<div style="font-size: 0.72rem; color: var(--text-muted); margin-top: 0.25rem; cursor: pointer;" data-channel-id-or-handle="' + (vid.channelHandle || vid.channelId || vid.channelName || 'sovralab') + '" onclick="event.stopPropagation(); window.openChannelHub(this.dataset.channelIdOrHandle);">' + vid.channelName + ' ✓</div>' +
            '<div style="font-size: 0.7rem; color: #94a3b8;">' + vid.viewsText + ' &bull; ' + vid.publishedAt + '</div>' +
          '</div>' +
        '</div>';
      }).join('');
    }

    function renderYtComments(sort = 'top') {
      const v = ytVideosCatalog[activeYtVideoIndex];
      if (!v) return;
      const list = ytCommentsDatabase[v.id] || [];

      const sorted = [...list];
      if (sort === 'top') {
        sorted.sort((a, b) => (b.isPinned ? 1 : 0) - (a.isPinned ? 1 : 0) || b.likes - a.likes);
      } else if (sort === 'newest') {
        sorted.sort((a, b) => (b.isPinned ? 1 : 0) - (a.isPinned ? 1 : 0) || b.timestamp - a.timestamp);
      }

      let totalComments = sorted.length;
      for (const c of sorted) {
        if (c.replies) totalComments += c.replies.length;
      }
      const countEl = document.getElementById('ytCommentsCount');
      if (countEl) countEl.innerText = totalComments + ' Comments';

      const container = document.getElementById('ytCommentsList');
      if (!container) return;

      container.innerHTML = sorted.map(c => {
        const isSuper = Boolean(c.isSuperThanks);
        const cardClass = isSuper ? 'yt-comment-thread super-thanks-comment-card' : 'yt-comment-thread';
        
        let headerBadges = '';
        if (c.isPinned) {
          headerBadges += '<span style="color:#f59e0b; font-size:0.75rem; font-weight:700; margin-right:8px;">📌 Pinned by creator</span>';
        }
        if (isSuper) {
          headerBadges += '<span class="super-thanks-badge" style="margin-right:8px;">💰 ' + c.superThanksAmount + ' Super Thanks</span>';
        }

        let creatorHeart = '';
        if (c.creatorHeart) {
          creatorHeart = '<span class="creator-heart-badge">❤️ ' + v.channelName + '</span>';
        }

        const timeStr = new Date(c.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });

        let repliesHtml = '';
        if (c.replies && c.replies.length > 0) {
          const repItems = c.replies.map(r => 
            '<div style="display: flex; gap: 0.65rem; align-items: flex-start;">' +
              '<div style="width: 28px; height: 28px; border-radius: 50%; background: #4338ca; color: #fff; font-weight: bold; font-size: 0.75rem; display: flex; align-items: center; justify-content: center; flex-shrink: 0;">' + r.authorAvatar + '</div>' +
              '<div style="flex: 1;">' +
                '<div style="display: flex; align-items: center; gap: 0.4rem;">' +
                  '<span style="font-size: 0.8rem; font-weight: 700; color: #e2e8f0;">' + r.authorName + '</span>' +
                  (r.isCreator ? '<span style="color: #60a5fa; font-size: 0.72rem;">✓ Creator</span>' : '') +
                  '<span style="font-size: 0.68rem; color: var(--text-muted);">' + new Date(r.timestamp).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' }) + '</span>' +
                '</div>' +
                '<div style="font-size: 0.82rem; color: #cbd5e1; line-height: 1.35; margin-top: 0.15rem;">' + parseTimestampsToLinks(r.text) + '</div>' +
                '<div style="display: flex; align-items: center; gap: 0.65rem; font-size: 0.72rem; color: var(--text-muted); margin-top: 0.2rem;">' +
                  '<span style="cursor: pointer;" onclick="likeNestedReply(&quot;' + c.id + '&quot;, &quot;' + r.id + '&quot;)">👍 ' + r.likes + '</span>' +
                  '<span style="color: #38bdf8; font-size: 0.72rem; font-weight: 700;" title="Verified Sovereign Identity">✓ Verified</span>' +
                '</div>' +
              '</div>' +
            '</div>'
          ).join('');

          repliesHtml = '<button class="btn-toggle-replies" onclick="toggleRepliesThread(&quot;' + c.id + '&quot;)" id="btn-toggle-' + c.id + '">' +
            '▾ ' + c.replies.length + (c.replies.length === 1 ? ' reply' : ' replies') +
            '</button>' +
            '<div class="yt-replies-list" id="replies-list-' + c.id + '" style="display: block;">' +
              repItems +
            '</div>';
        }

        return '<div class="' + cardClass + '" id="comment-' + c.id + '">' +
          '<div style="display: flex; gap: 0.75rem; align-items: flex-start;">' +
            '<div style="width: 36px; height: 36px; border-radius: 50%; background: #334155; color: #fff; font-weight: bold; font-size: 0.9rem; display: flex; align-items: center; justify-content: center; flex-shrink: 0;">' + c.authorAvatar + '</div>' +
            '<div style="flex: 1;">' +
              '<div>' + headerBadges + '<span style="font-size: 0.82rem; font-weight: 700; color: #e2e8f0;">@' + c.authorHandle + '</span> ' +
              '<span style="font-size: 0.7rem; color: var(--text-muted); margin-left: 4px;">' + timeStr + '</span>' +
              creatorHeart +
              '<span style="color: #38bdf8; font-size: 0.72rem; font-weight: 700; margin-left: 8px;" title="Verified Sovereign Identity">✓ Verified</span>' +
              '</div>' +
              '<div style="font-size: 0.85rem; color: #cbd5e1; line-height: 1.4; margin-top: 0.25rem;">' + parseTimestampsToLinks(c.text) + '</div>' +
              '<div style="display: flex; align-items: center; gap: 0.85rem; font-size: 0.75rem; color: var(--text-muted); margin-top: 0.35rem;">' +
                '<span style="cursor: pointer;" onclick="likeYtComment(&quot;' + c.id + '&quot;)">👍 <span id="like-cnt-' + c.id + '">' + c.likes + '</span></span>' +
                '<span style="cursor: pointer;">👎</span>' +
                '<span style="cursor: pointer; font-weight: 700; color: #38bdf8;" onclick="toggleReplyBox(&quot;' + c.id + '&quot;)">Reply</span>' +
                '<span style="cursor: pointer; color: ' + (c.creatorHeart ? '#ef4444' : 'var(--text-muted)') + ';" onclick="toggleHeartComment(&quot;' + c.id + '&quot;)" title="Creator Heart">' + (c.creatorHeart ? '❤️' : '🤍') + '</span>' +
                '<span style="cursor: pointer; color: ' + (c.isPinned ? '#f59e0b' : 'var(--text-muted)') + ';" onclick="togglePinComment(&quot;' + c.id + '&quot;)" title="Pin Comment">' + (c.isPinned ? '📌' : '📍') + '</span>' +
              '</div>' +
            '</div>' +
          '</div>' +
          '<div class="reply-composer-box" id="reply-box-' + c.id + '">' +
            '<div style="display: flex; gap: 0.5rem; align-items: center;">' +
              '<input type="text" id="reply-input-' + c.id + '" class="chat-text-input" placeholder="Add a public reply..." style="flex: 1;" onkeydown="if(event.key===&quot;Enter&quot;) submitNestedReply(&quot;' + c.id + '&quot;)">' +
              '<button class="btn btn-secondary" style="padding: 0.35rem 0.65rem; font-size: 0.75rem;" onclick="toggleReplyBox(&quot;' + c.id + '&quot;)">Cancel</button>' +
              '<button class="btn btn-primary" style="padding: 0.35rem 0.85rem; font-size: 0.75rem;" onclick="submitNestedReply(&quot;' + c.id + '&quot;)">Reply</button>' +
            '</div>' +
          '</div>' +
          repliesHtml +
        '</div>';
      }).join('');
    }

