    window.updateStudioHeaderChanSwitcher = function(activeChan, myChannels) {
      var avEl = document.getElementById('studioHeaderChanSwitcherAvatar');
      var nmEl = document.getElementById('studioHeaderChanSwitcherName');
      var popEl = document.getElementById('studioHeaderChanPopover');
      if (activeChan) {
        if (avEl) avEl.textContent = activeChan.avatar || '🎬';
        if (nmEl) nmEl.textContent = activeChan.name || activeChan.handle || 'Channel';
      }
      if (popEl && Array.isArray(myChannels)) {
        var itemsHtml = '<div style="font-size: 0.72rem; font-weight: 800; color: #94a3b8; text-transform: uppercase; padding: 4px 8px 6px;">Your Channels</div>';
        myChannels.forEach(function(c) {
          var isCur = activeChan && (c.id === activeChan.id);
          itemsHtml += '<div class="studio-header-chan-item" data-cid="' + c.id + '" onclick="event.stopPropagation(); window.selectStudioHeaderChan(this.dataset.cid);" style="display: flex; align-items: center; gap: 8px; padding: 7px 10px; border-radius: 8px; cursor: pointer; background: ' + (isCur ? 'rgba(56,189,248,0.18)' : 'transparent') + '; color: #fff; font-size: 0.82rem; font-weight: 600;">' +
            '<span>' + (c.avatar || '🎬') + '</span>' +
            '<span style="flex: 1; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">' + (c.name || c.handle) + '</span>' +
            (isCur ? '<span style="color: #38bdf8; font-weight: 800;">✓</span>' : '') +
          '</div>';
        });
        itemsHtml += '<div data-cid="__create_channel__" onclick="event.stopPropagation(); window.selectStudioHeaderChan(this.dataset.cid);" style="display: flex; align-items: center; gap: 8px; padding: 7px 10px; border-radius: 8px; cursor: pointer; color: #38bdf8; font-size: 0.8rem; font-weight: 700; border-top: 1px solid rgba(255,255,255,0.08); margin-top: 4px;">' +
          '<span>➕</span> <span>Create Video Channel</span>' +
        '</div>';
        popEl.innerHTML = itemsHtml;
      }
    };

    // Close header channel switcher popover when clicking outside
    document.addEventListener('click', function(e) {
      var pop = document.getElementById('studioHeaderChanPopover');
      var btn = document.getElementById('studioHeaderChanSwitcher');
      if (pop && btn && !pop.contains(e.target) && !btn.contains(e.target)) {
        pop.style.display = 'none';
      }
    });

    // Browser address bar deep-linking: popstate navigation support
    window.addEventListener('popstate', function(e) {
      if (e.state && e.state.sovraTab === 'channel' && e.state.channel) {
        window.openChannelHub(e.state.channel, true);
      } else if (window.location.pathname.startsWith('/@') || window.location.pathname.startsWith('/channel/')) {
        var pHandle = window.location.pathname.startsWith('/@')
          ? ('@' + window.location.pathname.slice(2))
          : window.location.pathname.substring(9);
        window.openChannelHub(pHandle, true);
      } else if (e.state && e.state.sovraTab && typeof switchTab === 'function') {
        switchTab(e.state.sovraTab);
      }
    });

    // Browser address bar deep-linking: Auto-boot upon direct page load
    window.addEventListener('DOMContentLoaded', function() {
      if (window.location.pathname.startsWith('/@') || window.location.pathname.startsWith('/channel/')) {
        var target = window.location.pathname.startsWith('/@')
          ? ('@' + window.location.pathname.slice(2))
          : window.location.pathname.substring(9);
        if (target && target !== '@') {
          setTimeout(function() {
            if (typeof window.openChannelHub === 'function') {
              window.openChannelHub(target, true);
            }
          }, 180);
        }
      }
    });

    function openChannelStudioPro() {
      if (window._currentChannelHubData && window._currentChannelHubData.channel) {
        const ch = window._currentChannelHubData.channel;
        if (window.SovraCreatorStudioEngine) {
          window.SovraCreatorStudioEngine.activeChannelId = ch.id;
        }
      }
      if (typeof switchTab === 'function') {
        switchTab('studio');
      }
    }
    window.openChannelStudioPro = openChannelStudioPro;

    function shareCurrentChannel(e) {
      if (e) e.stopPropagation();
      const ch = window._currentChannelHubData && window._currentChannelHubData.channel;
      const url = window.location.origin + '/@' + ((ch && ch.handle) ? ch.handle.replace(/^@/, '') : 'channel');
      if (navigator.clipboard && navigator.clipboard.writeText) {
        navigator.clipboard.writeText(url).then(function() {
          if (typeof showAccountToast === 'function') showAccountToast('🔗 Channel link copied to clipboard: ' + url);
        });
      } else {
        prompt('Channel URL:', url);
      }
    }
    window.shareCurrentChannel = shareCurrentChannel;

    function openChannelSuperTipModal() {
      const ch = window._currentChannelHubData && window._currentChannelHubData.channel;
      const name = ch ? ch.name : 'Creator';
      const amount = prompt('Enter amount of SOV to super-tip ' + name + ':', '10');
      if (!amount || isNaN(Number(amount))) return;
      if (typeof showAccountToast === 'function') {
        showAccountToast('⚡ Sent ' + amount + ' SOV Super-Tip to ' + name + '! Tx confirmed on sovereign ledger.');
      }
    }
    window.openChannelSuperTipModal = openChannelSuperTipModal;

    function playWatchVideoDirect(videoId) {
      if (!videoId) return;
      if (typeof switchTab === 'function') {
        switchTab('youtube');
      }
      if (typeof playVideoById === 'function') {
        playVideoById(videoId);
      }
    }
    window.playWatchVideoDirect = playWatchVideoDirect;

    // --- Page Creation Handlers ---
    function openCreatePageModal() {
      if (typeof checkGuestWriteAction === 'function' && checkGuestWriteAction('launch organization pages')) return;
      const m = document.getElementById('createPageModal');
      if (m) m.style.display = 'flex';
    }
    function closeCreatePageModal() {
      const m = document.getElementById('createPageModal');
      if (m) m.style.display = 'none';
    }
    function submitCreatePage() {
      const name = document.getElementById('pageNameInput').value.trim();
      let handle = document.getElementById('pageHandleInput').value.trim();
      const cat = document.getElementById('pageCategoryInput').value;
      const ctaType = document.getElementById('pageCtaInput').value;
      const bio = document.getElementById('pageBioInput').value.trim();
      if (!name || !handle) {
        showAccountToast('Please provide a page name and handle.');
        return;
      }
      if (!handle.startsWith('@')) handle = '@' + handle;

      fetch('/api/social/pages', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: name,
          handle: handle,
          category: cat,
          ctaType: ctaType,
          bio: bio
        })
      })
      .then(function(res) { return res.json(); })
      .then(function(data) {
        if (data.ok && data.page) {
          socialOmniCatalog.pages = socialOmniCatalog.pages || [];
          const catIdx = socialOmniCatalog.pages.findIndex(function(p) { return p.id === data.page.id; });
          if (catIdx >= 0) socialOmniCatalog.pages[catIdx] = data.page;
          else socialOmniCatalog.pages.unshift(data.page);

          if (typeof allPagesData !== 'undefined') {
            const pgIdx = allPagesData.findIndex(function(p) { return p.id === data.page.id; });
            if (pgIdx >= 0) allPagesData[pgIdx] = data.page;
            else allPagesData.unshift(data.page);
          }
          closeCreatePageModal();
          if (typeof refreshComposerAuthorSelect === 'function') refreshComposerAuthorSelect();
          if (typeof renderCreatorHubEntities === 'function') renderCreatorHubEntities();
          showAccountToast('🎉 Sovereign Page ' + handle + ' created in Creator Hub!');
        } else {
          showAccountToast('Failed to create page: ' + (data.error || 'Unknown error'));
        }
      })
      .catch(function(err) {
        showAccountToast('Page creation error: ' + err.message);
      });
    }

    // --- Multi-Format Video & Shorts Upload Handlers (Watch & Reels Platform) ---
    // --- Multi-Format Video & Shorts Upload Handlers (Sovereign Studio Wizard 3.0) ---
    let currentVideoWizardStep = 1;
    let activeUploadVideoElement = null;
    let selectedVideoUploadFile = null;

    function setVideoUploadStep(step) {
      currentVideoWizardStep = step;
      const s1 = document.getElementById('videoUploadStep1');
      const s2 = document.getElementById('videoUploadStep2');
      const s3 = document.getElementById('videoUploadStep3');
      if (s1) s1.style.display = (step === 1 ? 'flex' : 'none');
      if (s2) s2.style.display = (step === 2 ? 'flex' : 'none');
      if (s3) s3.style.display = (step === 3 ? 'flex' : 'none');

      const t1 = document.getElementById('videoWizardTab1');
      const t2 = document.getElementById('videoWizardTab2');
      const t3 = document.getElementById('videoWizardTab3');
      const activeStyle = 'flex: 1; text-align: center; padding: 10px 4px; font-size: 0.76rem; font-weight: 700; color: #38bdf8; border-bottom: 2px solid #38bdf8; cursor: pointer; transition: all 0.2s;';
      const inactiveStyle = 'flex: 1; text-align: center; padding: 10px 4px; font-size: 0.76rem; font-weight: 600; color: #94a3b8; border-bottom: 2px solid transparent; cursor: pointer; transition: all 0.2s;';
      if (t1) t1.style.cssText = (step === 1 ? activeStyle : inactiveStyle);
      if (t2) t2.style.cssText = (step === 2 ? activeStyle : inactiveStyle);
      if (t3) t3.style.cssText = (step === 3 ? activeStyle : inactiveStyle);

      const btnBack = document.getElementById('btnVideoWizardBack');
      const btnNext = document.getElementById('btnVideoWizardNext');
      const btnSubmit = document.getElementById('btnSubmitVideoUpload');
      if (btnBack) btnBack.style.display = (step > 1 ? 'inline-flex' : 'none');
      if (btnNext) btnNext.style.display = (step < 3 ? 'inline-flex' : 'none');
      if (btnSubmit) btnSubmit.style.display = (step === 3 ? 'inline-flex' : 'none');
    }

    function handleVideoWizardNext() {
      if (currentVideoWizardStep === 1) {
        if (!selectedVideoUploadFile && !window._selectedVideoThumbnail) {
          showAccountToast('Please select a video file first to continue.');
          return;
        }
        setVideoUploadStep(2);
      } else if (currentVideoWizardStep === 2) {
        const title = document.getElementById('videoUploadTitleInput');
        if (!title || !title.value.trim()) {
          showAccountToast('Please enter a Video Title / Headline before continuing.');
          if (title) title.focus();
          return;
        }
        setVideoUploadStep(3);
      }
    }

    function handleVideoWizardBack() {
      if (currentVideoWizardStep > 1) {
        setVideoUploadStep(currentVideoWizardStep - 1);
      }
    }

    function handleVideoThumbnailScrub(val) {
      const pct = parseFloat(val) || 0;
      if (activeUploadVideoElement && activeUploadVideoElement.duration) {
        const seekTime = (pct / 100) * activeUploadVideoElement.duration;
        const label = document.getElementById('videoThumbScrubLabel');
        if (label) label.innerText = 'Frame at ' + seekTime.toFixed(1) + 's';
        activeUploadVideoElement.currentTime = seekTime;
      }
    }

    function updateVideoUploadTargetPill() {
      const sel = document.getElementById('videoUploadChannelSelect');
      const pillLabel = document.getElementById('videoUploadTargetPillLabel');
      if (!sel || !pillLabel) return;
      const val = sel.value || 'personal:self';
      if (val.startsWith('channel:')) {
        const cId = val.replace('channel:', '');
        const ch = (typeof allChannelsData !== 'undefined' ? allChannelsData : []).find(function(c) { return c.id === cId; });
        pillLabel.innerText = '📢 Channel: ' + (ch ? ch.name : cId);
      } else if (val.startsWith('page:')) {
        const pId = val.replace('page:', '');
        const pg = (typeof allPagesData !== 'undefined' ? allPagesData : []).find(function(p) { return p.id === pId; });
        pillLabel.innerText = '🏢 Page: ' + (pg ? pg.name : pId);
      } else {
        const myName = (myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Personal Profile';
        pillLabel.innerText = '👤 Personal Profile: ' + myName;
      }
    }

