    function handleVideoFileSelected(event) {
      const file = event.target.files && event.target.files[0];
      if (!file) return;
      selectedVideoUploadFile = file;

      const prompt = document.getElementById('videoUploadFilePrompt');
      if (prompt) prompt.innerText = '✓ Selected: ' + file.name + ' (' + (file.size / (1024 * 1024)).toFixed(1) + ' MB)';

      // Auto-inspect aspect ratio and capture live thumbnail frame via HTML5 video element
      try {
        const tempVideo = document.createElement('video');
        tempVideo.preload = 'metadata';
        tempVideo.muted = true;
        tempVideo.playsInline = true;
        const objectUrl = URL.createObjectURL(file);
        tempVideo.src = objectUrl;
        activeUploadVideoElement = tempVideo;

        tempVideo.onloadedmetadata = function() {
          const w = tempVideo.videoWidth || 0;
          const h = tempVideo.videoHeight || 0;
          const dur = tempVideo.duration || 0;
          window._selectedVideoDuration = Math.round(dur);

          // 9:16 vertical detection or short duration check
          const isVertical = (h > w) || (dur > 0 && dur <= 90 && h >= w);
          const badge = document.getElementById('videoUploadFormatBadge');
          if (badge) {
            if (isVertical) {
              badge.innerHTML = '📱 <b>9:16 Vertical Short Detected</b> (' + w + 'x' + h + ', ' + Math.round(dur) + 's) &bull; Auto-routed to Reels Feed';
              badge.style.color = '#38bdf8';
            } else {
              badge.innerHTML = '🎬 <b>16:9 Landscape Video Detected</b> (' + w + 'x' + h + ', ' + Math.round(dur) + 's) &bull; Auto-routed to Watch Feed';
              badge.style.color = '#fda4af';
            }
          }
          selectVideoUploadTargetFormat(isVertical ? 'short' : 'watch');

          const scrubberContainer = document.getElementById('videoThumbScrubberContainer');
          if (scrubberContainer) scrubberContainer.style.display = 'block';

          // Seek to initial frame preview
          tempVideo.currentTime = Math.min(1.0, dur > 1 ? 1.0 : (dur > 0 ? dur / 2 : 0.1));
        };

        tempVideo.onseeked = function() {
          try {
            const canvas = document.createElement('canvas');
            const targetW = Math.min(tempVideo.videoWidth || 480, 480);
            canvas.width = targetW;
            canvas.height = Math.round(targetW * ((tempVideo.videoHeight || 270) / (tempVideo.videoWidth || 480)));
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(tempVideo, 0, 0, canvas.width, canvas.height);
              const thumbData = canvas.toDataURL('image/jpeg', 0.85);
              window._selectedVideoThumbnail = thumbData;
              const thumbImg = document.getElementById('videoUploadThumbPreview');
              if (thumbImg) {
                thumbImg.src = thumbData;
                thumbImg.style.display = 'block';
              }
            }
          } catch (e) {
            console.warn('[Upload] Frame capture fallback:', e);
          }
        };
      } catch (err) {
        console.warn('[Upload] Video inspection error:', err);
      }
    }

    async function submitVideoUpload() {
      const title = (document.getElementById('videoUploadTitleInput')?.value || '').trim();
      const shortHeader = (document.getElementById('videoUploadShortHeaderInput')?.value || '').trim();
      const s1 = (document.getElementById('videoUploadSummary1')?.value || '').trim();
      const s2 = (document.getElementById('videoUploadSummary2')?.value || '').trim();
      const s3 = (document.getElementById('videoUploadSummary3')?.value || '').trim();
      const summaryBullets = [s1, s2, s3].filter(Boolean);
      const summary = summaryBullets.length ? ('• ' + summaryBullets.join(String.fromCharCode(10) + '• ')) : '';
      const description = (document.getElementById('videoUploadDescInput')?.value || '').trim();
      const category = document.getElementById('videoUploadCategorySelect')?.value || 'Technology';
      const tagsStr = (document.getElementById('videoUploadTagsInput')?.value || '').trim();
      const relatedVideoId = document.getElementById('videoUploadRelatedVideoSelect')?.value || '';
      const targetFmt = document.getElementById('videoUploadTargetFormat') ? document.getElementById('videoUploadTargetFormat').value : 'watch';
      const tippingEl = document.getElementById('videoUploadTippingToggle');
      const isTippingEnabled = tippingEl ? tippingEl.checked : true;
      const paywallFee = parseFloat(document.getElementById('videoUploadPaywallFeeInput')?.value) || 0;
      const visEl = document.getElementById('videoUploadVisibilitySelect');
      const visibility = visEl ? visEl.value : 'public';
      const audioTrack = (document.getElementById('videoUploadAudioTrackInput')?.value || '').trim();

      if (!title) {
        showAccountToast('Please enter a video title or headline.');
        setVideoUploadStep(2);
        return;
      }
      const tags = tagsStr.split(',').map(function(t) { return t.trim(); }).filter(Boolean);
      const publishBtn = document.getElementById('btnSubmitVideoUpload');
      if (publishBtn) {
        publishBtn.disabled = true;
        publishBtn.innerText = 'Publishing to P2P Mesh... ⏳';
      }

      // Resolve author name, handle, entityType, and entityId
      const chanSelect = document.getElementById('videoUploadChannelSelect');
      const chanVal = chanSelect ? chanSelect.value : 'personal:self';
      let authorName = (myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Sovereign Creator';
      let authorHandle = (myProfile && myProfile.handle) ? myProfile.handle : '@creator';
      let entityType = 'personal';
      let entityId = undefined;

      if (chanVal.startsWith('channel:')) {
        entityType = 'channel';
        entityId = chanVal.replace('channel:', '');
        if (typeof allChannelsData !== 'undefined') {
          const matched = allChannelsData.find(function(c) { return c.id === entityId; });
          if (matched) {
            authorName = matched.name;
            authorHandle = matched.handle;
          }
        }
      } else if (chanVal.startsWith('page:')) {
        entityType = 'page';
        entityId = chanVal.replace('page:', '');
        if (typeof allPagesData !== 'undefined') {
          const matchedPg = allPagesData.find(function(p) { return p.id === entityId; });
          if (matchedPg) {
            authorName = matchedPg.name;
            authorHandle = matchedPg.handle;
          }
        }
      } else if (chanVal !== 'personal' && chanVal !== 'personal:self' && typeof allChannelsData !== 'undefined') {
        const matched = allChannelsData.find(function(c) { return c.id === chanVal; });
        if (matched) {
          entityType = 'channel';
          entityId = matched.id;
          authorName = matched.name;
          authorHandle = matched.handle;
        }
      }

      let videoData = null;
      let mimeType = 'video/mp4';
      if (selectedVideoUploadFile) {
        mimeType = selectedVideoUploadFile.type || 'video/mp4';
        try {
          videoData = await new Promise(function(resolve, reject) {
            const reader = new FileReader();
            reader.onload = function(e) { resolve(e.target.result); };
            reader.onerror = reject;
            reader.readAsDataURL(selectedVideoUploadFile);
          });
        } catch (readErr) {
          console.warn('Error reading video file:', readErr);
        }
      }

      try {
        if (targetFmt === 'short') {
          // Route 1: 9:16 Vertical Short / Reel Ingestion
          const payload = {
            caption: title,
            shortHeader: shortHeader,
            summary: summary,
            description: description,
            tags: tags.length ? tags : ['#Shorts', '#Sovra', '#P2P'],
            creatorHandle: authorHandle,
            creatorName: authorName,
            videoData: videoData,
            thumbnailData: window._selectedVideoThumbnail,
            mimeType: mimeType,
            relatedVideoId: relatedVideoId,
            paywallFee: paywallFee,
            tippingEnabled: isTippingEnabled,
            audioTrack: audioTrack || ('Original Audio - ' + authorHandle),
            entityType: entityType,
            entityId: entityId,
            isShort: true
          };

          const res = await fetch('/api/reels/create', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          const result = await res.json();
          if (result.ok && result.reel) {
            const newReel = result.reel;
            if (typeof reelsStore !== 'undefined') {
              reelsStore.unshift(newReel);
              const counterEl = document.getElementById('reelCounterDisplay');
              if (counterEl) counterEl.innerText = '1 / ' + reelsStore.length;
            }
            closeVideoUploadModal();
            showAccountToast('🎉 Short "' + title + '" published to 60fps Sovereign Reels feed!');
          } else {
            showAccountToast('Short publication failed: ' + (result.error || 'Unknown error'));
          }
        } else {
          // Route 2: 16:9 Landscape Long-Form Watch Ingestion
          if (selectedVideoUploadFile) {
            // Route 2A: Sovereign Resumable Chunked Ingestion (Multi-GB Zero-RAM)
            if (publishBtn) publishBtn.innerText = 'Initializing P2P Ingestion... ⏳';

            const initRes = await fetch('/api/videos/upload/init', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({
                title: title,
                fileSize: selectedVideoUploadFile.size,
                mimeType: mimeType,
                shortHeader: shortHeader,
                summary: summary,
                description: description || title,
                category: category,
                tags: tags.length ? tags : ['#Sovereign', '#P2P'],
                channelName: authorName,
                channelHandle: authorHandle,
                entityType: entityType,
                entityId: entityId,
                durationSeconds: window._selectedVideoDuration || 600,
                visibility: visibility,
                relatedVideoId: relatedVideoId,
                paywallFee: paywallFee,
                tippingEnabled: isTippingEnabled
              })
            });
            const initData = await initRes.json();
            if (!initData.ok || !initData.uploadId) {
              throw new Error(initData.error || 'Failed to initialize upload session');
            }

            const uploadId = initData.uploadId;
            const chunkSize = initData.chunkSize || (8 * 1024 * 1024);
            const totalBytes = selectedVideoUploadFile.size;
            let offset = 0;
            let chunkIdx = 0;
            const totalChunks = Math.ceil(totalBytes / chunkSize);
            const uploadStartTime = Date.now();

            while (offset < totalBytes) {
              const sliceEnd = Math.min(offset + chunkSize, totalBytes);
              const chunkBlob = selectedVideoUploadFile.slice(offset, sliceEnd);

              if (publishBtn) {
                const currentPct = Math.round((offset / totalBytes) * 100);
                const elapsed = (Date.now() - uploadStartTime) / 1000;
                const mbps = elapsed > 0 ? ((offset / (1024 * 1024)) / elapsed).toFixed(1) : '0.0';
                publishBtn.innerText = 'Streaming Chunk ' + (chunkIdx + 1) + '/' + totalChunks + ' (' + currentPct + '% @ ' + mbps + ' MB/s)...';
              }

              const chunkRes = await fetch('/api/videos/upload/chunk?uploadId=' + encodeURIComponent(uploadId), {
                method: 'PATCH',
                headers: {
                  'Content-Type': 'application/octet-stream',
                  'Content-Range': 'bytes ' + offset + '-' + (sliceEnd - 1) + '/' + totalBytes
                },
                body: chunkBlob
              });
              const chunkData = await chunkRes.json();
              if (!chunkData.ok) {
                throw new Error(chunkData.error || 'Failed streaming chunk ' + (chunkIdx + 1));
              }

              offset = sliceEnd;
              chunkIdx++;
            }

            if (publishBtn) publishBtn.innerText = 'Finalizing CID & Transcoding... ⚡';

            const compRes = await fetch('/api/videos/upload/complete', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ uploadId: uploadId })
            });
            const compData = await compRes.json();
            if (compData.ok && compData.video) {
              const newVideo = compData.video;
              if (typeof ytVideosCatalog !== 'undefined') {
                ytVideosCatalog.unshift(newVideo);
                activeYtVideoIndex = 0;
                if (typeof renderYtCurrentVideo === 'function') {
                  renderYtCurrentVideo();
                }
              }
              if (typeof longFormVideosCatalog !== 'undefined') {
                longFormVideosCatalog.unshift(newVideo);
              }
              const titleEl = document.getElementById('ytVideoTitle');
              if (titleEl) titleEl.innerText = newVideo.title;
              const cidEl = document.getElementById('ytCidDisplay');
              if (cidEl) cidEl.innerText = 'CID: ' + newVideo.cid;
              const chanEl = document.getElementById('ytChannelName');
              if (chanEl) chanEl.innerText = newVideo.channelName;
              closeVideoUploadModal();
              showAccountToast('🎉 Video "' + title + '" published! Multi-resolution ABR HLS transcoding running in background.');
              return;
            } else {
              throw new Error(compData.error || 'Failed finalizing video upload');
            }
          }

          // Route 2B: Legacy Single-Shot Fallback (URL or non-file)
          const payload = {
            title: title,
            shortHeader: shortHeader,
            summary: summary,
            description: description || title,
            category: category,
            tags: tags.length ? tags : ['#Sovereign', '#P2P'],
            channelName: authorName,
            channelHandle: authorHandle,
            videoData: videoData,
            thumbnailData: window._selectedVideoThumbnail,
            durationSeconds: window._selectedVideoDuration || 600,
            mimeType: mimeType,
            visibility: visibility,
            relatedVideoId: relatedVideoId,
            paywallFee: paywallFee,
            entityType: entityType,
            entityId: entityId,
            monetization: { tippingEnabled: isTippingEnabled, creatorSplitPercent: 95 }
          };

          const res = await fetch('/api/youtube/upload', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(payload)
          });
          const result = await res.json();
          if (result.ok && result.video) {
            const newVideo = result.video;
            if (typeof ytVideosCatalog !== 'undefined') {
              ytVideosCatalog.unshift(newVideo);
              activeYtVideoIndex = 0;
              if (typeof renderYtCurrentVideo === 'function') {
                renderYtCurrentVideo();
              }
            }
            if (typeof longFormVideosCatalog !== 'undefined') {
              longFormVideosCatalog.unshift(newVideo);
            }
            const titleEl = document.getElementById('ytVideoTitle');
            if (titleEl) titleEl.innerText = newVideo.title;
            const cidEl = document.getElementById('ytCidDisplay');
            if (cidEl) cidEl.innerText = 'CID: ' + newVideo.cid;
            const chanEl = document.getElementById('ytChannelName');
            if (chanEl) chanEl.innerText = newVideo.channelName;
            closeVideoUploadModal();
            showAccountToast('🎉 Video "' + title + '" published to Sovereign Watch over P2P!');
          } else {
            showAccountToast('Video upload failed: ' + (result.error || 'Unknown error'));
          }
        }
      } catch (err) {
        console.error('Video upload network error:', err);
        showAccountToast('Failed to publish video: ' + (err.message || 'Network error'));
      } finally {
        if (publishBtn) {
          publishBtn.disabled = false;
          selectVideoUploadTargetFormat(targetFmt);
        }
      }
    }

    // --- Profile Creator Hub Dynamic Entities Renderer (Sensible, Relatable & Clean) ---
    window.creatorHubActiveFilter = 'all';
    window.setCreatorHubFilter = function(filter, btnEl) {
      window.creatorHubActiveFilter = filter;
      const parent = btnEl ? btnEl.parentElement : null;
      if (parent) {
        const tabs = parent.querySelectorAll('.creator-hub-tab');
        tabs.forEach(function(t) {
          t.style.background = 'rgba(255, 255, 255, 0.04)';
          t.style.borderColor = 'rgba(255, 255, 255, 0.1)';
          t.style.color = '#94a3b8';
        });
        if (btnEl) {
          const isPage = filter === 'pages';
          btnEl.style.background = isPage ? 'rgba(192, 132, 252, 0.2)' : 'rgba(56, 189, 248, 0.2)';
          btnEl.style.borderColor = isPage ? 'rgba(192, 132, 252, 0.55)' : 'rgba(56, 189, 248, 0.55)';
          btnEl.style.color = isPage ? '#c084fc' : '#38bdf8';
        }
      }
      const container = document.getElementById('spatialChannelsPagesContainer') || document.getElementById('creatorHubEntitiesContainer');
      if (container) {
        const chCards = container.querySelectorAll('.hub-item-channel');
        const pgCards = container.querySelectorAll('.hub-item-page');
        chCards.forEach(function(c) {
          c.style.display = (filter === 'all' || filter === 'channels') ? 'flex' : 'none';
        });
        pgCards.forEach(function(p) {
          p.style.display = (filter === 'all' || filter === 'pages') ? 'flex' : 'none';
        });
      }
    };

    function renderCreatorHubEntities(targetEl) {
      const container = (targetEl && targetEl.nodeType ? targetEl : (typeof targetEl === 'string' ? document.getElementById(targetEl) : null)) || document.getElementById('creatorHubEntitiesContainer');
      if (!container) return;
      const currentDid = (typeof myProfile !== 'undefined' && myProfile && myProfile.did) 
        ? myProfile.did 
        : (window.SOVRA_HOST_SESSION && window.SOVRA_HOST_SESSION.did ? window.SOVRA_HOST_SESSION.did : null);

      const allCh = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const allPg = (typeof allPagesData !== 'undefined' ? allPagesData : []);

      // 1. Get entities strictly created/owned by the active logged-in user (Zero fake fallbacks)
      let channels = allCh.filter(function(c) {
        return Boolean(currentDid && (c.ownerDid === currentDid || c.creatorDid === currentDid));
      });
      let pages = allPg.filter(function(p) {
        return Boolean(currentDid && (p.ownerDid === currentDid || p.creatorDid === currentDid));
      });

      const totalAudience = channels.reduce(function(acc, c) { return acc + (c.count || 0); }, 0) +
                            pages.reduce(function(acc, p) { return acc + (p.count || 0); }, 0);

      const ribbonAudienceEl = document.getElementById('creatorHubAudienceRibbon');
      if (ribbonAudienceEl) {
        ribbonAudienceEl.innerText = (totalAudience >= 1000 ? (totalAudience / 1000).toFixed(1) + 'K+' : totalAudience.toLocaleString()) + ' Audience';
      }

      const bannerChEl = document.getElementById('bannerChannelsPill');
      if (bannerChEl) bannerChEl.innerText = '📢 ' + channels.length + (channels.length === 1 ? ' Channel' : ' Channels');
      const bannerPgEl = document.getElementById('bannerPagesPill');
      if (bannerPgEl) bannerPgEl.innerText = '🏢 ' + pages.length + (pages.length === 1 ? ' Page' : ' Pages');
      const bannerAudEl = document.getElementById('bannerAudiencePill');
      if (bannerAudEl) {
        const audText = totalAudience >= 1000 ? (totalAudience / 1000).toFixed(1) + 'K+' : totalAudience.toLocaleString();
        bannerAudEl.innerText = '👥 ' + audText + ' Reach';
      }

      if (channels.length === 0 && pages.length === 0) {
        let emptyHtml = '<div style="background: rgba(15, 23, 42, 0.55); border: 1px dashed rgba(255, 255, 255, 0.12); border-radius: 14px; padding: 2rem 1.5rem; text-align: center; margin-top: 0.5rem;">' +
          '<div style="font-size: 2rem; margin-bottom: 0.5rem;">📢</div>' +
          '<div style="font-weight: 700; color: #f8fafc; font-size: 1rem; margin-bottom: 0.35rem;">No Channels or Pages Yet</div>' +
          '<div style="color: #94a3b8; font-size: 0.82rem; line-height: 1.5; max-width: 440px; margin: 0 auto 1.25rem;">' +
            'Create a Broadcast Channel to send newsletters, polls &amp; audio notes to subscribers, or create a Public Page for your company, shop, or community.' +
          '</div>' +
          '<div style="display: flex; gap: 10px; justify-content: center; flex-wrap: wrap;">' +
            '<button type="button" class="btn btn-primary" onclick="openCreateChannelModal()" style="padding: 8px 16px; font-size: 0.82rem; border-radius: 9px; background: rgba(56, 189, 248, 0.2); border: 1px solid rgba(56, 189, 248, 0.45); color: #38bdf8; font-weight: 700; cursor: pointer;">+ Create Channel</button>' +
            '<button type="button" class="btn btn-primary" onclick="openCreatePageModal()" style="padding: 8px 16px; font-size: 0.82rem; border-radius: 9px; background: rgba(192, 132, 252, 0.2); border: 1px solid rgba(192, 132, 252, 0.45); color: #c084fc; font-weight: 700; cursor: pointer;">+ Create Page</button>' +
          '</div>' +
        '</div>';
        container.innerHTML = emptyHtml;
        if (typeof refreshComposerAuthorSelect === 'function') refreshComposerAuthorSelect();
        return;
      }

      // Filter Tabs & Stats Bar
      const curFilter = window.creatorHubActiveFilter || 'all';
      let html = '<div style="display: flex; flex-direction: column; gap: 12px;">';
      html += '<div style="display: flex; align-items: center; justify-content: space-between; flex-wrap: wrap; gap: 8px; border-bottom: 1px solid rgba(255, 255, 255, 0.08); padding-bottom: 8px;">' +
        '<div style="display: flex; gap: 6px; align-items: center;">' +
          '<button type="button" class="creator-hub-tab" onclick="window.setCreatorHubFilter(&quot;all&quot;, this)" style="padding: 5px 12px; font-size: 0.76rem; font-weight: 700; border-radius: 18px; border: 1px solid ' + (curFilter === 'all' ? 'rgba(56, 189, 248, 0.55)' : 'rgba(255,255,255,0.1)') + '; background: ' + (curFilter === 'all' ? 'rgba(56, 189, 248, 0.2)' : 'rgba(255,255,255,0.04)') + '; color: ' + (curFilter === 'all' ? '#38bdf8' : '#94a3b8') + '; cursor: pointer;">All (' + (channels.length + pages.length) + ')</button>' +
          '<button type="button" class="creator-hub-tab" onclick="window.setCreatorHubFilter(&quot;channels&quot;, this)" style="padding: 5px 12px; font-size: 0.76rem; font-weight: 700; border-radius: 18px; border: 1px solid ' + (curFilter === 'channels' ? 'rgba(56, 189, 248, 0.55)' : 'rgba(255,255,255,0.1)') + '; background: ' + (curFilter === 'channels' ? 'rgba(56, 189, 248, 0.2)' : 'rgba(255,255,255,0.04)') + '; color: ' + (curFilter === 'channels' ? '#38bdf8' : '#94a3b8') + '; cursor: pointer;">📢 Channels (' + channels.length + ')</button>' +
          '<button type="button" class="creator-hub-tab" onclick="window.setCreatorHubFilter(&quot;pages&quot;, this)" style="padding: 5px 12px; font-size: 0.76rem; font-weight: 700; border-radius: 18px; border: 1px solid ' + (curFilter === 'pages' ? 'rgba(192, 132, 252, 0.55)' : 'rgba(255,255,255,0.1)') + '; background: ' + (curFilter === 'pages' ? 'rgba(192, 132, 252, 0.2)' : 'rgba(255,255,255,0.04)') + '; color: ' + (curFilter === 'pages' ? '#c084fc' : '#94a3b8') + '; cursor: pointer;">🏢 Pages (' + pages.length + ')</button>' +
        '</div>' +
        '<div style="font-size: 0.75rem; color: #94a3b8; font-weight: 600;">' +
          '👥 ' + totalAudience.toLocaleString() + ' Total Subscribers' +
        '</div>' +
      '</div>';

      // Entities List Container
      html += '<div style="display: flex; flex-direction: column; gap: 10px;">';

      // 1. Channel Cards
      for (let i = 0; i < channels.length; i++) {
        const c = channels[i];
        const isShown = curFilter === 'all' || curFilter === 'channels';
        html += '<div class="hub-item-channel" style="display: ' + (isShown ? 'flex' : 'none') + '; flex-direction: column; gap: 10px; background: rgba(30, 41, 59, 0.55); border: 1px solid rgba(56, 189, 248, 0.25); border-left: 3px solid #38bdf8; border-radius: 14px; padding: 12px 14px;">' +
          '<div style="display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap;">' +
            '<div style="display: flex; align-items: center; gap: 10px; cursor: pointer; flex: 1; min-width: 200px;" data-channel-id="' + c.id + '" onclick="openChannelRoom(this.dataset.channelId)">' +
              '<div style="width: 42px; height: 42px; border-radius: 12px; background: ' + (c.bg || '#38bdf8') + '; display: flex; align-items: center; justify-content: center; font-size: 1.3rem; color: #fff; flex-shrink: 0; box-shadow: 0 4px 10px rgba(56, 189, 248, 0.2);">' + (c.avatar || '📢') + '</div>' +
              '<div>' +
                '<div style="font-weight: 700; color: #f8fafc; font-size: 0.92rem; display: flex; align-items: center; gap: 6px;">' +
                  '<span>' + c.name + '</span>' +
                  '<span style="color: #38bdf8; font-size: 0.75rem;">✓</span>' +
                  '<span style="font-size: 0.72rem; color: #38bdf8; font-weight: 600; background: rgba(56, 189, 248, 0.12); padding: 1px 6px; border-radius: 6px;">' + c.handle + '</span>' +
                  '<span class="badge" style="background: rgba(56, 189, 248, 0.15); color: #38bdf8; font-size: 0.65rem; padding: 1px 6px; border-radius: 6px;">Channel</span>' +
                '</div>' +
                '<div style="font-size: 0.76rem; color: #94a3b8; margin-top: 2px;">' + (c.desc || 'Broadcast channel for updates and announcements.') + '</div>' +
              '</div>' +
            '</div>' +
            '<div style="display: flex; align-items: center; gap: 8px;">' +
              '<span style="font-size: 0.75rem; color: #94a3b8; font-weight: 600;">👥 ' + (c.count ? c.count.toLocaleString() : '1') + ' subscribers</span>' +
            '</div>' +
          '</div>' +
          '<div style="display: flex; justify-content: flex-end; align-items: center; gap: 8px; border-top: 1px solid rgba(255,255,255,0.06); padding-top: 8px;">' +
            '<button type="button" class="btn btn-primary" style="padding: 6px 14px; font-size: 0.78rem; border-radius: 8px; background: rgba(56, 189, 248, 0.2); border: 1px solid rgba(56, 189, 248, 0.45); color: #38bdf8; font-weight: 700; cursor: pointer; display: inline-flex; align-items: center; gap: 6px;" data-channel-id="' + c.id + '" onclick="openChannelRoom(this.dataset.channelId)">📢 Open Channel</button>' +
            '<button type="button" class="btn btn-secondary" style="padding: 6px 12px; font-size: 0.78rem; border-radius: 8px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.15); color: #cbd5e1; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;" data-channel-id="' + c.id + '" onclick="openSpatialChannelManageSurface(this.dataset.channelId, this)">⚙️ Settings</button>' +
            '<button type="button" class="btn btn-danger" style="padding: 6px 9px; font-size: 0.78rem; border-radius: 8px; background: rgba(239, 68, 68, 0.1); border: 1px solid rgba(239, 68, 68, 0.25); color: #f87171; cursor: pointer;" title="Delete this channel" data-type="channel" data-id="' + c.id + '" data-name="' + (c.name || '').replace(/"/g, '&quot;') + '" onclick="deleteEntityPrompt(this.dataset.type, this.dataset.id, this.dataset.name)">🗑️</button>' +
          '</div>' +
        '</div>';
      }

      // 2. Page Cards
      for (let j = 0; j < pages.length; j++) {
        const p = pages[j];
        const isShown = curFilter === 'all' || curFilter === 'pages';
        const isCurrentActive = (typeof currentActivePersona !== 'undefined' && currentActivePersona.type === 'page' && currentActivePersona.id === p.id);
        html += '<div class="hub-item-page" style="display: ' + (isShown ? 'flex' : 'none') + '; flex-direction: column; gap: 10px; background: rgba(30, 41, 59, 0.55); border: 1px solid rgba(192, 132, 252, 0.25); border-left: 3px solid #c084fc; border-radius: 14px; padding: 12px 14px;">' +
          '<div style="display: flex; justify-content: space-between; align-items: center; gap: 10px; flex-wrap: wrap;">' +
            '<div style="display: flex; align-items: center; gap: 10px; cursor: pointer; flex: 1; min-width: 200px;" data-page-id="' + p.id + '" onclick="openPublicPageShowcase(this.dataset.pageId)">' +
              '<div style="width: 42px; height: 42px; border-radius: 12px; background: ' + (p.bg || '#c084fc') + '; display: flex; align-items: center; justify-content: center; font-size: 1.3rem; color: #fff; flex-shrink: 0; box-shadow: 0 4px 10px rgba(192, 132, 252, 0.2);">' + (p.avatar || '🏢') + '</div>' +
              '<div>' +
                '<div style="font-weight: 700; color: #f8fafc; font-size: 0.92rem; display: flex; align-items: center; gap: 6px;">' +
                  '<span>' + p.name + '</span>' +
                  '<span style="color: #c084fc; font-size: 0.75rem;">✓</span>' +
                  '<span style="font-size: 0.72rem; color: #c084fc; font-weight: 600; background: rgba(192, 132, 252, 0.12); padding: 1px 6px; border-radius: 6px;">' + p.handle + '</span>' +
                  '<span class="badge" style="background: rgba(192, 132, 252, 0.15); color: #c084fc; font-size: 0.65rem; padding: 1px 6px; border-radius: 6px;">Public Page</span>' +
                '</div>' +
                '<div style="font-size: 0.76rem; color: #94a3b8; margin-top: 2px;">' + (p.bio || 'Public brand profile and community page.') + '</div>' +
              '</div>' +
            '</div>' +
            '<div style="display: flex; align-items: center; gap: 8px;">' +
              '<span style="font-size: 0.75rem; color: #94a3b8; font-weight: 600;">👥 ' + (p.count ? p.count.toLocaleString() : '1') + ' followers</span>' +
              '<span style="font-size: 0.72rem; color: #c084fc; background: rgba(192, 132, 252, 0.1); border: 1px solid rgba(192, 132, 252, 0.25); border-radius: 8px; padding: 2px 7px; font-weight: 600;">' + (p.category || 'Business') + '</span>' +
            '</div>' +
          '</div>' +
          '<div style="display: flex; justify-content: flex-end; align-items: center; gap: 8px; border-top: 1px solid rgba(255,255,255,0.06); padding-top: 8px;">' +
            '<button type="button" class="btn btn-primary" style="padding: 6px 14px; font-size: 0.78rem; border-radius: 8px; background: rgba(192, 132, 252, 0.2); border: 1px solid rgba(192, 132, 252, 0.45); color: #c084fc; font-weight: 700; cursor: pointer; display: inline-flex; align-items: center; gap: 6px;" data-page-id="' + p.id + '" onclick="openPublicPageShowcase(this.dataset.pageId)">🌐 View Page</button>' +
            (isCurrentActive
              ? '<button type="button" class="btn btn-primary" style="padding: 6px 12px; font-size: 0.78rem; border-radius: 8px; background: rgba(34, 197, 94, 0.2); border: 1px solid rgba(34, 197, 94, 0.45); color: #4ade80; cursor: pointer;" data-persona="personal" onclick="switchToPersona(this.dataset.persona)">✓ Active Persona</button>'
              : '<button type="button" class="btn btn-secondary" style="padding: 6px 12px; font-size: 0.78rem; border-radius: 8px; border: 1px solid rgba(192, 132, 252, 0.35); color: #c084fc; background: rgba(192, 132, 252, 0.12); cursor: pointer;" data-persona="page:' + p.id + '" onclick="switchToPersona(this.dataset.persona)">🔄 Switch Persona</button>'
            ) +
            '<button type="button" class="btn btn-secondary" style="padding: 6px 12px; font-size: 0.78rem; border-radius: 8px; background: rgba(255, 255, 255, 0.06); border: 1px solid rgba(255, 255, 255, 0.15); color: #cbd5e1; cursor: pointer; display: inline-flex; align-items: center; gap: 5px;" data-page-id="' + p.id + '" onclick="openSpatialPageManageSurface(this.dataset.pageId, this)">⚙️ Settings</button>' +
            '<button type="button" class="btn btn-danger" style="padding: 6px 9px; font-size: 0.78rem; border-radius: 8px; background: rgba(239, 68, 68, 0.1); border: 1px solid rgba(239, 68, 68, 0.25); color: #f87171; cursor: pointer;" title="Delete this page" data-type="page" data-id="' + p.id + '" data-name="' + (p.name || '').replace(/"/g, '&quot;') + '" onclick="deleteEntityPrompt(this.dataset.type, this.dataset.id, this.dataset.name)">🗑️</button>' +
          '</div>' +
        '</div>';
      }

      html += '</div></div>';

      container.innerHTML = html;
      if (typeof refreshComposerAuthorSelect === 'function') refreshComposerAuthorSelect();
    }
    window.renderCreatorHubEntities = renderCreatorHubEntities;

    function deleteEntityPrompt(type, id, name) {
      const typeLabel = type === 'channel' ? 'Broadcast Channel' : 'Sovereign Page';
      if (!confirm('Are you sure you want to delete ' + typeLabel + ' "' + name + '"? This will remove it from the sovereign network.')) return;
      const endpoint = type === 'channel' ? '/api/social/channels/delete' : '/api/social/pages/delete';
      const payload = type === 'channel' ? { channelId: id } : { pageId: id };

      fetch(endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(payload)
      })
      .then(function(res) { return res.json(); })
      .then(function(data) {
        if (data.ok) {
          if (type === 'channel' && typeof allChannelsData !== 'undefined') {
            allChannelsData = allChannelsData.filter(function(c) { return c.id !== id; });
          } else if (type === 'page' && typeof allPagesData !== 'undefined') {
            allPagesData = allPagesData.filter(function(p) { return p.id !== id; });
          }
          if (typeof renderCreatorHubEntities === 'function') renderCreatorHubEntities();
          if (typeof refreshComposerAuthorSelect === 'function') refreshComposerAuthorSelect();
          showAccountToast('✓ ' + typeLabel + ' deleted.');
        } else {
          showAccountToast('Failed to delete entity: ' + (data.error || 'Unknown error'));
        }
      })
      .catch(function(err) {
        showAccountToast('Delete error: ' + err.message);
      });
    }

    // --- Instagram / Facebook Page Persona Switcher ---
    let currentActivePersona = {
      type: 'personal',
      id: 'personal',
      name: (typeof myProfile !== 'undefined' && myProfile ? (myProfile.displayName || myProfile.name || 'Personal Profile') : 'Personal Profile'),
      handle: (typeof myProfile !== 'undefined' && myProfile ? (myProfile.handle || '@you') : '@you'),
      avatar: (typeof myProfile !== 'undefined' && myProfile ? (myProfile.avatar || 'S') : 'S'),
      bg: '#6366f1'
    };

    function openSwitchPersonaModal(e) {
      if (e && e.stopPropagation) e.stopPropagation();
      const m = document.getElementById('switchPersonaModal');
      if (m) {
        renderSwitchPersonaList();
        m.style.display = 'flex';
      }
    }

    function closeSwitchPersonaModal() {
      const m = document.getElementById('switchPersonaModal');
      if (m) m.style.display = 'none';
    }

    function renderSwitchPersonaList() {
      const container = document.getElementById('switchPersonaListContainer');
      if (!container) return;
      const currentDid = (typeof myProfile !== 'undefined' && myProfile && myProfile.did) 
        ? myProfile.did 
        : (window.SOVRA_HOST_SESSION && window.SOVRA_HOST_SESSION.did ? window.SOVRA_HOST_SESSION.did : null);
      const myName = (typeof myProfile !== 'undefined' && myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Personal Profile';
      const myHandle = (typeof myProfile !== 'undefined' && myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
      const myAvatar = (typeof myProfile !== 'undefined' && myProfile && myProfile.avatar) ? myProfile.avatar : 'S';
      const myAvatarDataUrl = (typeof myProfile !== 'undefined' && myProfile && myProfile.avatarDataUrl) ? myProfile.avatarDataUrl : null;
      const isPersonalActive = (!currentActivePersona || currentActivePersona.type === 'personal');
      
      const allPg = (typeof allPagesData !== 'undefined' ? allPagesData : []);
      // Strictly filter to Pages created by the active user
      const pages = allPg.filter(function(p) {
        return currentDid && p.ownerDid && p.ownerDid === currentDid;
      });

      let html = '<div style="margin-bottom: 1rem;">' +
        '<div style="font-size: 0.72rem; font-weight: 700; text-transform: uppercase; color: #94a3b8; letter-spacing: 0.05em; margin-bottom: 0.5rem;">Personal Identity</div>' +
        '<div style="background: rgba(255,255,255,0.04); border: 1px solid ' + (isPersonalActive ? 'rgba(99, 102, 241, 0.6)' : 'rgba(255,255,255,0.08)') + '; border-radius: 12px; padding: 10px 14px; display: flex; justify-content: space-between; align-items: center; gap: 10px;">' +
          '<div style="display: flex; align-items: center; gap: 10px;">' +
            '<div style="width: 36px; height: 36px; border-radius: 50%; background: #6366f1; display: flex; align-items: center; justify-content: center; font-weight: 700; font-size: 1rem; color: #fff; overflow: hidden;">' +
              (myAvatarDataUrl ? '<img src="' + myAvatarDataUrl + '" style="width:100%;height:100%;object-fit:cover;" />' : myAvatar) +
            '</div>' +
            '<div>' +
              '<div style="font-weight: 700; font-size: 0.9rem; color: #f8fafc;">' + myName + '</div>' +
              '<div style="font-size: 0.74rem; color: #94a3b8;">' + myHandle + ' &bull; Personal Account</div>' +
            '</div>' +
          '</div>' +
          '<div>' +
            (isPersonalActive 
              ? '<span class="badge" style="background: rgba(34, 197, 94, 0.2); color: #4ade80; border: 1px solid rgba(34, 197, 94, 0.4); padding: 4px 10px; border-radius: 20px; font-size: 0.74rem;">✓ Active</span>'
              : '<button type="button" class="btn btn-secondary" style="padding: 4px 12px; font-size: 0.76rem; border-radius: 8px;" data-persona="personal" onclick="switchToPersona(this.dataset.persona)">Switch</button>') +
          '</div>' +
        '</div>' +
      '</div>';

      html += '<div>' +
        '<div style="font-size: 0.72rem; font-weight: 700; text-transform: uppercase; color: #94a3b8; letter-spacing: 0.05em; margin-bottom: 0.5rem;">Sovereign Pages You Manage (' + pages.length + ')</div>';

      if (pages.length === 0) {
        html += '<div style="text-align: center; color: #64748b; font-size: 0.8rem; padding: 14px; background: rgba(255,255,255,0.02); border-radius: 10px;">No Sovereign Pages created yet. You can create a Page for your organization, business, or project!</div>';
      } else {
        html += '<div style="display: flex; flex-direction: column; gap: 0.5rem;">';
        for (let j = 0; j < pages.length; j++) {
          const p = pages[j];
          const isPageActive = (currentActivePersona && currentActivePersona.type === 'page' && currentActivePersona.id === p.id);
          html += '<div style="background: rgba(255,255,255,0.04); border: 1px solid ' + (isPageActive ? 'rgba(192, 132, 252, 0.6)' : 'rgba(255,255,255,0.08)') + '; border-radius: 12px; padding: 10px 14px; display: flex; justify-content: space-between; align-items: center; gap: 10px;">' +
            '<div style="display: flex; align-items: center; gap: 10px;">' +
              '<div style="width: 36px; height: 36px; border-radius: 10px; background: ' + (p.bg || '#c084fc') + '; display: flex; align-items: center; justify-content: center; font-size: 1.1rem; color: #fff;">' +
                (p.avatar || '🏢') +
              '</div>' +
              '<div>' +
                '<div style="font-weight: 700; font-size: 0.9rem; color: #f8fafc;">' + p.name + '</div>' +
                '<div style="font-size: 0.74rem; color: #c084fc;">' + p.handle + ' &bull; ' + (p.category || 'Page') + '</div>' +
              '</div>' +
            '</div>' +
            '<div>' +
              (isPageActive 
                ? '<span class="badge" style="background: rgba(34, 197, 94, 0.2); color: #4ade80; border: 1px solid rgba(34, 197, 94, 0.4); padding: 4px 10px; border-radius: 20px; font-size: 0.74rem;">✓ Active</span>'
                : '<button type="button" class="btn btn-secondary" style="padding: 4px 12px; font-size: 0.76rem; border-radius: 8px; border: 1px solid rgba(192, 132, 252, 0.35); color: #c084fc; background: rgba(192, 132, 252, 0.12);" data-persona="page:' + p.id + '" onclick="switchToPersona(this.dataset.persona)">Switch to Page</button>') +
            '</div>' +
          '</div>';
        }
        html += '</div>';
      }
      html += '</div>';

      container.innerHTML = html;
    }

    // Dynamic Author Persona Options Synchronizer
    function refreshComposerAuthorSelect() {
      const authorSelect = document.getElementById('composerAuthorSelect');
      if (!authorSelect) return;
      const currentDid = (typeof myProfile !== 'undefined' && myProfile && myProfile.did) 
        ? myProfile.did 
        : (window.SOVRA_HOST_SESSION && window.SOVRA_HOST_SESSION.did ? window.SOVRA_HOST_SESSION.did : null);
      const myName = (typeof myProfile !== 'undefined' && myProfile && (myProfile.displayName || myProfile.name)) 
        ? (myProfile.displayName || myProfile.name) 
        : 'Personal Profile';

      // 1. Personal Account optgroup
      let selfGroup = authorSelect.querySelector('optgroup[label*="Personal"]');
      if (!selfGroup) {
        selfGroup = document.createElement('optgroup');
        selfGroup.label = '👤 Personal Account';
        authorSelect.insertBefore(selfGroup, authorSelect.firstChild);
      }
      let selfOpt = selfGroup.querySelector('option[value="personal:self"]');
      if (!selfOpt) {
        selfOpt = document.createElement('option');
        selfOpt.value = 'personal:self';
        selfGroup.appendChild(selfOpt);
      }
      selfOpt.textContent = '👤 ' + myName;

      // 2. Sovereign Pages optgroup - strictly user-owned pages
      let pgGroup = authorSelect.querySelector('optgroup[label*="Pages"]');
      if (!pgGroup) {
        pgGroup = document.createElement('optgroup');
        pgGroup.label = '📄 Sovereign Pages';
        authorSelect.appendChild(pgGroup);
      }
      const allPg = (typeof allPagesData !== 'undefined' ? allPagesData : []);
      const myPages = allPg.filter(function(p) {
        return currentDid && p.ownerDid && p.ownerDid === currentDid;
      });
      pgGroup.innerHTML = '';
      for (let i = 0; i < myPages.length; i++) {
        const opt = document.createElement('option');
        opt.value = 'page:' + myPages[i].id;
        opt.textContent = '📄 ' + myPages[i].name;
        pgGroup.appendChild(opt);
      }

      // 3. Broadcast Channels optgroup - strictly user-owned channels
      let chGroup = authorSelect.querySelector('optgroup[label*="Channels"]');
      if (!chGroup) {
        chGroup = document.createElement('optgroup');
        chGroup.label = '📢 Broadcast Channels';
        authorSelect.appendChild(chGroup);
      }
      const allCh = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const myChannels = allCh.filter(function(c) {
        return currentDid && c.ownerDid && c.ownerDid === currentDid;
      });
      chGroup.innerHTML = '';
      for (let j = 0; j < myChannels.length; j++) {
        const opt = document.createElement('option');
        opt.value = 'channel:' + myChannels[j].id;
        opt.textContent = '📢 ' + myChannels[j].name;
        chGroup.appendChild(opt);
      }
    }

    function switchToPersona(val) {
      const authorSelect = document.getElementById('composerAuthorSelect');
      const personaBar = document.getElementById('composerActivePersonaBar');
      const personaName = document.getElementById('composerActivePersonaName');
      const personaHandle = document.getElementById('composerActivePersonaHandle');
      const mainAvatar = document.getElementById('mainComposerUserAvatar');
      const composerInput = document.getElementById('dynamicPostCaption');

      if (!val || val === 'personal' || val === 'personal:self') {
        const myName = (typeof myProfile !== 'undefined' && myProfile && (myProfile.displayName || myProfile.name)) ? (myProfile.displayName || myProfile.name) : 'Personal Profile';
        const myHandle = (typeof myProfile !== 'undefined' && myProfile && myProfile.handle) ? myProfile.handle : currentUserHandle;
        const myAvatar = (typeof myProfile !== 'undefined' && myProfile && myProfile.avatar) ? myProfile.avatar : 'S';
        const myAvatarDataUrl = (typeof myProfile !== 'undefined' && myProfile && myProfile.avatarDataUrl) ? myProfile.avatarDataUrl : null;
        currentActivePersona = {
          type: 'personal',
          id: 'personal',
          name: myName,
          handle: myHandle,
          avatar: myAvatar,
          bg: '#6366f1'
        };

        if (authorSelect) {
          authorSelect.value = 'personal:self';
          handleComposerAuthorChange('personal:self');
        }
        if (personaBar) personaBar.style.display = 'none';
        if (mainAvatar) {
          mainAvatar.style.background = '#6366f1';
          mainAvatar.innerHTML = myAvatarDataUrl ? '<img src="' + myAvatarDataUrl + '" style="width:100%;height:100%;border-radius:50%;object-fit:cover;display:block;" />' : myAvatar;
        }
        if (composerInput) {
          composerInput.placeholder = "What's on your mind?";
        }
        showAccountToast('👤 Switched to Personal Profile (' + myHandle + ')');
      } else if (val.startsWith('page:')) {
        const pageId = val.replace('page:', '');
        const pages = (typeof allPagesData !== 'undefined' ? allPagesData : []);
        const page = pages.find(function(p) { return p.id === pageId; });
        if (page) {
          currentActivePersona = {
            type: 'page',
            id: page.id,
            name: page.name,
            handle: page.handle,
            avatar: page.avatar || '🏢',
            bg: page.bg || '#c084fc'
          };

          if (authorSelect) {
            authorSelect.value = val;
            handleComposerAuthorChange(val);
          }
          if (personaBar) {
            personaBar.style.display = 'flex';
            if (personaName) personaName.innerText = page.name;
            if (personaHandle) personaHandle.innerText = page.handle;
          }
          if (mainAvatar) {
            mainAvatar.style.background = page.bg || '#c084fc';
            mainAvatar.innerHTML = page.avatar || '🏢';
          }
          if (composerInput) {
            composerInput.placeholder = 'Post an update as ' + page.name + '...';
          }
          showAccountToast('🏢 Switched to Page: ' + page.name + ' (' + page.handle + ')');
        }
      }

      closeSwitchPersonaModal();
      if (typeof renderCreatorHubEntities === 'function') renderCreatorHubEntities();
    }

    // --- Telegram / WhatsApp Broadcast Channel Room & Engine ---
    let activeChannelRoomId = null;
    let activeChannelPinnedText = {};
    let activeChannelVoiceDataUrl = null;
    let activeChannelVoiceDuration = '0:45';
    let channelRecordTimer = null;
    let channelRecordSeconds = 0;

    function openChannelRoom(channelId) {
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === channelId || c.handle === channelId; });
      if (!ch) {
        showAccountToast('Channel not found');
        return;
      }
      activeChannelRoomId = ch.id;

      const avatarEl = document.getElementById('channelRoomAvatar');
      if (avatarEl) {
        avatarEl.innerText = ch.avatar || '📢';
        avatarEl.style.background = ch.bg || '#0284c7';
      }
      const nameEl = document.getElementById('channelRoomName');
      if (nameEl) nameEl.innerText = ch.name;
      const handleEl = document.getElementById('channelRoomHandle');
      if (handleEl) handleEl.innerText = ch.handle;
      const subsEl = document.getElementById('channelRoomSubs');
      if (subsEl) subsEl.innerText = (ch.count ? ch.count.toLocaleString() : '1') + ' subscribers';
      const bioEl = document.getElementById('channelRoomBioBanner');
      if (bioEl) bioEl.innerText = ch.desc || 'Decentralized broadcast channel for P2P updates.';

      const subBtn = document.getElementById('channelRoomSubBtn');
      if (subBtn) {
        subBtn.innerText = ch.isSubbed ? 'Subscribed ✓' : 'Subscribe';
        subBtn.className = ch.isSubbed ? 'action-pill-btn action-pill-secondary' : 'action-pill-btn action-pill-primary';
      }

      // Restore pinned message if present
      const pinnedWrap = document.getElementById('channelRoomPinnedWrap');
      const pinnedTextEl = document.getElementById('channelRoomPinnedText');
      if (pinnedWrap && pinnedTextEl) {
        if (activeChannelPinnedText[ch.id]) {
          pinnedTextEl.innerText = activeChannelPinnedText[ch.id];
          pinnedWrap.style.display = 'flex';
        } else {
          pinnedWrap.style.display = 'none';
        }
      }

      renderChannelRoomStream(ch);

      const modal = document.getElementById('channelRoomModal');
      if (modal) modal.style.display = 'flex';

      const input = document.getElementById('channelBroadcastInput');
      if (input) {
        input.value = '';
        setTimeout(function() { input.focus(); }, 200);
      }
    }

    function closeChannelRoom() {
      const modal = document.getElementById('channelRoomModal');
      if (modal) modal.style.display = 'none';
      activeChannelRoomId = null;
      clearChannelPhotoUpload();
      clearChannelVoiceUpload();
      clearChannelPollCreator();
    }

    function toggleChannelRoomSubscribe() {
      if (!activeChannelRoomId) return;
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === activeChannelRoomId; });
      if (!ch) return;
      ch.isSubbed = !ch.isSubbed;
      ch.count += ch.isSubbed ? 1 : -1;
      const subBtn = document.getElementById('channelRoomSubBtn');
      if (subBtn) {
        subBtn.innerText = ch.isSubbed ? 'Subscribed ✓' : 'Subscribe';
        subBtn.className = ch.isSubbed ? 'action-pill-btn action-pill-secondary' : 'action-pill-btn action-pill-primary';
      }
      const subsEl = document.getElementById('channelRoomSubs');
      if (subsEl) subsEl.innerText = (ch.count ? ch.count.toLocaleString() : '1') + ' subscribers';
      fetch('/api/social/channels/subscribe', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ channelId: ch.id })
      }).catch(function(err) { console.warn('[Channel] Subscribe error:', err); });
      showAccountToast(ch.isSubbed ? '🔔 Subscribed to ' + ch.name : '🔕 Unsubscribed from ' + ch.name);
    }

    function renderChannelRoomStream(ch) {
      const container = document.getElementById('channelRoomStream');
      if (!container) return;
      const posts = (typeof feedPostsData !== 'undefined' ? feedPostsData : []).filter(function(p) {
        return (p.authorType === 'channel' && (p.authorEntityId === ch.id || p.authorEntityHandle === ch.handle));
      });

      if (posts.length === 0) {
        container.innerHTML = '<div style="text-align: center; padding: 2.5rem 1rem; color: #94a3b8; display: flex; flex-direction: column; align-items: center; gap: 0.75rem;">' +
          '<div style="width: 52px; height: 52px; border-radius: 16px; background: rgba(56, 189, 248, 0.15); color: #38bdf8; display: align-items: center; justify-content: center; font-size: 1.6rem; display: flex;">📢</div>' +
          '<div style="font-weight: 700; color: #f8fafc; font-size: 1.05rem;">' + ch.name + ' Broadcast Feed</div>' +
          '<div style="font-size: 0.82rem; max-width: 360px; line-height: 1.4;">This is a decentralized Telegram-style broadcast channel. Subscribers receive real-time updates directly over the peer-to-peer mesh.</div>' +
          '<div style="font-size: 0.76rem; color: #38bdf8; font-weight: 600; margin-top: 0.25rem;">Broadcast an announcement below to get started!</div>' +
        '</div>';
        return;
      }

      let html = '';
      for (let i = posts.length - 1; i >= 0; i--) {
        const p = posts[i];
        const timeStr = new Date(p.timestamp || Date.now()).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
        const reactions = p.reactions || { '❤️': (p.likesCount || 0), '🔥': 0, '🚀': 0, '👏': 0, '💡': 0 };
        const isPinned = (activeChannelPinnedText[ch.id] && activeChannelPinnedText[ch.id] === (p.caption || ''));

        html += '<div id="broadcast-msg-' + p.id + '" style="background: rgba(15, 23, 42, 0.85); border: 1px solid ' + (isPinned ? '#f59e0b' : 'rgba(56, 189, 248, 0.2)') + '; border-radius: 16px; padding: 14px 16px; display: flex; flex-direction: column; gap: 8px; box-shadow: 0 4px 14px rgba(0,0,0,0.3);">' +
          '<div style="display: flex; justify-content: space-between; align-items: center;">' +
            '<div style="display: flex; align-items: center; gap: 6px;">' +
              (isPinned ? '<span class="badge" style="background: rgba(245, 158, 11, 0.2); color: #fbbf24; border: 1px solid rgba(245, 158, 11, 0.4); font-size: 0.68rem; font-weight: 700;">📌 PINNED</span>' : '<span class="badge" style="background: rgba(56, 189, 248, 0.15); color: #38bdf8; border: 1px solid rgba(56, 189, 248, 0.3); font-size: 0.68rem; font-weight: 700;">📢 BROADCAST</span>') +
              '<span style="font-size: 0.74rem; color: #94a3b8; font-family: monospace;">' + (p.mediaCid ? p.mediaCid.slice(0, 12) + '...' : 'Ed25519 Signed') + '</span>' +
            '</div>' +
            '<div style="display: flex; align-items: center; gap: 8px;">' +
              '<button type="button" data-post-id="' + p.id + '" data-post-caption="' + (p.caption || '').replace(/"/g, '&quot;') + '" onclick="pinChannelAnnouncement(this.dataset.postId, this.dataset.postCaption)" style="background: none; border: none; color: #94a3b8; font-size: 0.75rem; cursor: pointer; padding: 0;" title="Pin to channel top">📌 Pin</button>' +
              '<span style="font-size: 0.72rem; color: #64748b;">' + timeStr + '</span>' +
            '</div>' +
          '</div>' +

          (p.mediaImage ? '<div style="border-radius: 10px; overflow: hidden; max-height: 280px; background: #000;"><img src="' + p.mediaImage + '" style="width: 100%; max-height: 280px; object-fit: contain; display: block;" /></div>' : '') +

          (p.isVoiceNote ? 
            '<div style="background: rgba(56, 189, 248, 0.08); border: 1px solid rgba(56, 189, 248, 0.25); border-radius: 12px; padding: 10px 14px; display: flex; align-items: center; gap: 12px; margin: 4px 0;">' +
              '<button type="button" class="action-pill-btn action-pill-primary" style="width: 36px; height: 36px; border-radius: 50%; padding: 0; display: flex; align-items: center; justify-content: center; font-size: 0.9rem;" data-msg="▶ Playing P2P Opus voice dispatch..." onclick="showAccountToast(this.dataset.msg)">▶</button>' +
              '<div style="flex: 1;">' +
                '<div style="display: flex; align-items: center; gap: 3px; height: 20px;">' +
                  '<span style="height: 60%; width: 3px; background: #38bdf8; border-radius: 2px;"></span>' +
                  '<span style="height: 100%; width: 3px; background: #38bdf8; border-radius: 2px;"></span>' +
                  '<span style="height: 40%; width: 3px; background: #38bdf8; border-radius: 2px;"></span>' +
                  '<span style="height: 80%; width: 3px; background: #38bdf8; border-radius: 2px;"></span>' +
                  '<span style="height: 50%; width: 3px; background: #38bdf8; border-radius: 2px;"></span>' +
                  '<span style="height: 90%; width: 3px; background: #38bdf8; border-radius: 2px;"></span>' +
                  '<span style="height: 70%; width: 3px; background: #38bdf8; border-radius: 2px;"></span>' +
                  '<span style="height: 30%; width: 3px; background: #38bdf8; border-radius: 2px;"></span>' +
                '</div>' +
                '<div style="font-size: 0.72rem; color: #38bdf8; margin-top: 2px;">🎙️ Voice Dispatch &bull; ' + (p.audioDuration || '0:45') + ' &bull; Opus P2P Stream</div>' +
              '</div>' +
            '</div>' : '') +

          (p.pollData ? 
            '<div style="background: rgba(168, 85, 247, 0.08); border: 1px solid rgba(168, 85, 247, 0.25); border-radius: 12px; padding: 12px 14px; margin: 4px 0;">' +
              '<div style="font-weight: 700; color: #f8fafc; font-size: 0.88rem; margin-bottom: 8px;">📊 ' + (p.pollData.question || 'Community Poll') + '</div>' +
              '<div style="display: flex; flex-direction: column; gap: 6px;">' +
                (p.pollData.options || []).map(function(opt, optIdx) {
                  const pct = p.pollData.totalVotes ? Math.round((opt.votes / p.pollData.totalVotes) * 100) : 0;
                  return '<div data-post-id="' + p.id + '" data-opt-idx="' + optIdx + '" onclick="voteOnChannelPoll(this.dataset.postId, parseInt(this.dataset.optIdx))" style="background: rgba(0,0,0,0.3); border: 1px solid rgba(255,255,255,0.1); border-radius: 8px; padding: 6px 10px; cursor: pointer; position: relative; overflow: hidden;">' +
                    '<div style="position: absolute; top: 0; left: 0; bottom: 0; width: ' + pct + '%; background: rgba(168, 85, 247, 0.25); z-index: 1;"></div>' +
                    '<div style="position: relative; z-index: 2; display: flex; justify-content: space-between; font-size: 0.78rem;">' +
                      '<span style="color: #f1f5f9; font-weight: 600;">' + opt.text + '</span>' +
                      '<span style="color: #c084fc; font-weight: 700;">' + pct + '% (' + (opt.votes || 0) + ')</span>' +
                    '</div>' +
                  '</div>';
                }).join('') +
              '</div>' +
              '<div style="font-size: 0.7rem; color: #94a3b8; margin-top: 6px; text-align: right;">' + (p.pollData.totalVotes || 0) + ' peer votes &bull; Tap option to vote</div>' +
            '</div>' : '') +

          '<div style="color: #f8fafc; font-size: 0.95rem; line-height: 1.5; white-space: pre-wrap; word-break: break-word;">' + (p.caption || '') + '</div>' +

          '<div style="display: flex; justify-content: space-between; align-items: center; border-top: 1px solid rgba(255,255,255,0.06); padding-top: 8px; margin-top: 4px; flex-wrap: wrap; gap: 6px;">' +
            '<div style="display: flex; gap: 5px; flex-wrap: wrap;">' +
              '<button type="button" class="action-pill-btn action-pill-secondary" style="padding: 2px 7px; font-size: 0.72rem; border-radius: 12px;" data-post-id="' + p.id + '" data-emoji="❤️" onclick="reactToBroadcast(this.dataset.postId, this.dataset.emoji)">❤️ ' + (reactions['❤️'] || 0) + '</button>' +
              '<button type="button" class="action-pill-btn action-pill-secondary" style="padding: 2px 7px; font-size: 0.72rem; border-radius: 12px;" data-post-id="' + p.id + '" data-emoji="🔥" onclick="reactToBroadcast(this.dataset.postId, this.dataset.emoji)">🔥 ' + (reactions['🔥'] || 0) + '</button>' +
              '<button type="button" class="action-pill-btn action-pill-secondary" style="padding: 2px 7px; font-size: 0.72rem; border-radius: 12px;" data-post-id="' + p.id + '" data-emoji="🚀" onclick="reactToBroadcast(this.dataset.postId, this.dataset.emoji)">🚀 ' + (reactions['🚀'] || 0) + '</button>' +
              '<button type="button" class="action-pill-btn action-pill-secondary" style="padding: 2px 7px; font-size: 0.72rem; border-radius: 12px;" data-post-id="' + p.id + '" data-emoji="👏" onclick="reactToBroadcast(this.dataset.postId, this.dataset.emoji)">👏 ' + (reactions['👏'] || 0) + '</button>' +
              '<button type="button" class="action-pill-btn action-pill-secondary" style="padding: 2px 7px; font-size: 0.72rem; border-radius: 12px;" data-post-id="' + p.id + '" data-emoji="💡" onclick="reactToBroadcast(this.dataset.postId, this.dataset.emoji)">💡 ' + (reactions['💡'] || 0) + '</button>' +
            '</div>' +
            '<div style="display: flex; align-items: center; gap: 8px;">' +
              '<button type="button" class="action-pill-btn action-pill-secondary" style="padding: 2px 8px; font-size: 0.72rem; border-radius: 12px;" data-msg="🚀 Boosted to local peers!" onclick="showAccountToast(this.dataset.msg)">🚀 Boost</button>' +
              '<span style="font-size: 0.7rem; color: #38bdf8;">✓ P2P Relayed</span>' +
            '</div>' +
          '</div>' +
        '</div>';
      }
      container.innerHTML = html;
      container.scrollTop = container.scrollHeight;
    }

    let channelPhotoDataUrl = null;
    function triggerChannelPhotoUpload() {
      const fileInput = document.getElementById('channelPhotoFileInput');
      if (fileInput) fileInput.click();
    }
    function handleChannelPhotoFile(e) {
      const file = e.target.files && e.target.files[0];
      if (!file) return;
      const reader = new FileReader();
      reader.onload = function(evt) {
        channelPhotoDataUrl = evt.target.result;
        const previewWrap = document.getElementById('channelPhotoPreviewWrap');
        const previewImg = document.getElementById('channelPhotoPreviewImg');
        if (previewWrap && previewImg) {
          previewImg.src = channelPhotoDataUrl;
          previewWrap.style.display = 'flex';
        }
      };
      reader.readAsDataURL(file);
    }
    function clearChannelPhotoUpload() {
      channelPhotoDataUrl = null;
      const previewWrap = document.getElementById('channelPhotoPreviewWrap');
      if (previewWrap) previewWrap.style.display = 'none';
      const fileInput = document.getElementById('channelPhotoFileInput');
      if (fileInput) fileInput.value = '';
    }

    function toggleChannelVoiceRecord() {
      const wrap = document.getElementById('channelVoiceRecordWrap');
      if (!wrap) return;
      if (wrap.style.display === 'none' || !wrap.style.display) {
        window._activeChannelAudioChunks = [];
        if (navigator.mediaDevices && typeof navigator.mediaDevices.getUserMedia === 'function') {
          navigator.mediaDevices.getUserMedia({ audio: true }).then(function(stream) {
            window._activeChannelMediaStream = stream;
            var mimeType = (typeof MediaRecorder !== 'undefined' && MediaRecorder.isTypeSupported && MediaRecorder.isTypeSupported('audio/webm')) ? 'audio/webm' : 'audio/mp4';
            try {
              window._activeChannelMediaRecorder = new MediaRecorder(stream, { mimeType: mimeType });
              window._activeChannelMediaRecorder.ondataavailable = function(e) {
                if (e.data && e.data.size > 0) window._activeChannelAudioChunks.push(e.data);
              };
              window._activeChannelMediaRecorder.start(250);
            } catch (err) { console.warn("MediaRecorder start error:", err); }
          }).catch(function(err) { console.warn("Audio hardware capture error:", err); });
        }
        wrap.style.display = 'flex';
        channelRecordSeconds = 0;
        const statusEl = document.getElementById('channelVoiceStatusText');
        if (statusEl) statusEl.innerText = '🎙️ Recording Voice Dispatch (0:01)...';
        if (channelRecordTimer) clearInterval(channelRecordTimer);
        channelRecordTimer = setInterval(function() {
          channelRecordSeconds++;
          const mins = Math.floor(channelRecordSeconds / 60);
          const secs = channelRecordSeconds % 60;
          const timeStr = mins + ':' + (secs < 10 ? '0' : '') + secs;
          if (statusEl) statusEl.innerText = '🎙️ Recording Voice Dispatch (' + timeStr + ')...';
        }, 1000);
      } else {
        cancelChannelVoiceRecord();
      }
    }

    function finishChannelVoiceRecord() {
      if (channelRecordTimer) clearInterval(channelRecordTimer);
      const mins = Math.floor(channelRecordSeconds / 60);
      const secs = channelRecordSeconds % 60;
      activeChannelVoiceDuration = (channelRecordSeconds > 0 ? (mins + ':' + (secs < 10 ? '0' : '') + secs) : '0:45');
      var finalizeVoicePayload = function(dataUrl) {
              activeChannelVoiceDataUrl = dataUrl;
              const recordWrap = document.getElementById('channelVoiceRecordWrap');
              if (recordWrap) recordWrap.style.display = 'none';
              const prevWrap = document.getElementById('channelVoicePreviewWrap');
              const prevDur = document.getElementById('channelVoicePreviewDuration');
              if (prevWrap && prevDur) {
                prevDur.innerText = 'Voice Dispatch Attached (' + activeChannelVoiceDuration + ')';
                prevWrap.style.display = 'flex';
              }
              showAccountToast('🎙️ Voice dispatch audio attached!');
            };
      
            if (window._activeChannelMediaRecorder && window._activeChannelMediaRecorder.state !== 'inactive') {
              window._activeChannelMediaRecorder.onstop = function() {
                try {
                  const blob = new Blob(window._activeChannelAudioChunks || [], { type: window._activeChannelMediaRecorder.mimeType || 'audio/webm' });
                  const reader = new FileReader();
                  reader.onloadend = function() {
                    finalizeVoicePayload(reader.result || 'data:audio/webm;base64,GkXfo59ChoEBQveBAULygQ8=');
                  };
                  reader.readAsDataURL(blob);
                } catch (_) {
                  finalizeVoicePayload('data:audio/webm;base64,GkXfo59ChoEBQveBAULygQ8=');
                }
                if (window._activeChannelMediaStream) {
                  try { window._activeChannelMediaStream.getTracks().forEach(function(t) { t.stop(); }); } catch (_) {}
                  window._activeChannelMediaStream = null;
                }
              };
              try { window._activeChannelMediaRecorder.stop(); } catch (_) { finalizeVoicePayload('data:audio/webm;base64,GkXfo59ChoEBQveBAULygQ8='); }
            } else {
              finalizeVoicePayload('data:audio/wav;base64,UklGRiQAAABXQVZFZm10IBAAAAABAAEAQB8AAEAfAAABAAgAZGF0YQAAAAA=');
            }
      const recordWrap = document.getElementById('channelVoiceRecordWrap');
      if (recordWrap) recordWrap.style.display = 'none';
      const prevWrap = document.getElementById('channelVoicePreviewWrap');
      const prevDur = document.getElementById('channelVoicePreviewDuration');
      if (prevWrap && prevDur) {
        prevDur.innerText = 'Voice Dispatch Attached (' + activeChannelVoiceDuration + ')';
        prevWrap.style.display = 'flex';
      }
      showAccountToast('🎙️ Voice dispatch audio attached!');
    }

    function cancelChannelVoiceRecord() {
      if (channelRecordTimer) clearInterval(channelRecordTimer);
      const recordWrap = document.getElementById('channelVoiceRecordWrap');
      if (recordWrap) recordWrap.style.display = 'none';
      channelRecordSeconds = 0;
    }

    function clearChannelVoiceUpload() {
      activeChannelVoiceDataUrl = null;
      const prevWrap = document.getElementById('channelVoicePreviewWrap');
      if (prevWrap) prevWrap.style.display = 'none';
    }

    function toggleChannelPollCreator() {
      const wrap = document.getElementById('channelPollCreatorWrap');
      if (!wrap) return;
      wrap.style.display = (wrap.style.display === 'none' || !wrap.style.display) ? 'flex' : 'none';
      if (wrap.style.display === 'flex') {
        const qInput = document.getElementById('channelPollQuestionInput');
        if (qInput) qInput.focus();
      }
    }

    function clearChannelPollCreator() {
      const wrap = document.getElementById('channelPollCreatorWrap');
      if (wrap) wrap.style.display = 'none';
      const qInput = document.getElementById('channelPollQuestionInput');
      if (qInput) qInput.value = '';
      const o1 = document.getElementById('channelPollOpt1');
      if (o1) o1.value = '';
      const o2 = document.getElementById('channelPollOpt2');
      if (o2) o2.value = '';
    }

    function voteOnChannelPoll(postId, optIdx) {
      if (typeof feedPostsData === 'undefined') return;
      const p = feedPostsData.find(function(post) { return post.id === postId; });
      if (!p || !p.pollData) return;
      if (p.pollData.hasVoted) {
        showAccountToast('You have already voted on this community poll.');
        return;
      }
      p.pollData.hasVoted = true;
      p.pollData.options[optIdx].votes = (p.pollData.options[optIdx].votes || 0) + 1;
      p.pollData.totalVotes = (p.pollData.totalVotes || 0) + 1;
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === activeChannelRoomId; });
      if (ch) renderChannelRoomStream(ch);
      showAccountToast('🗳️ Your cryptographic vote was registered on the P2P mesh!');
    }

    function reactToBroadcast(postId, emoji) {
      if (typeof feedPostsData === 'undefined') return;
      const p = feedPostsData.find(function(post) { return post.id === postId; });
      if (!p) return;
      p.reactions = p.reactions || { '❤️': (p.likesCount || 0), '🔥': 0, '🚀': 0, '👏': 0, '💡': 0 };
      p.reactions[emoji] = (p.reactions[emoji] || 0) + 1;
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === activeChannelRoomId; });
      if (ch) renderChannelRoomStream(ch);
      showAccountToast(emoji + ' Reaction relayed over Noise_XX GossipSub!');
    }

    function pinChannelAnnouncement(postId, text) {
      if (!activeChannelRoomId) return;
      activeChannelPinnedText[activeChannelRoomId] = text;
      const pinnedWrap = document.getElementById('channelRoomPinnedWrap');
      const pinnedTextEl = document.getElementById('channelRoomPinnedText');
      if (pinnedWrap && pinnedTextEl) {
        pinnedTextEl.innerText = text;
        pinnedWrap.style.display = 'flex';
      }
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === activeChannelRoomId; });
      if (ch) renderChannelRoomStream(ch);
      showAccountToast('📌 Announcement pinned to channel top!');
    }

    function unpinChannelAnnouncement() {
      if (!activeChannelRoomId) return;
      delete activeChannelPinnedText[activeChannelRoomId];
      const pinnedWrap = document.getElementById('channelRoomPinnedWrap');
      if (pinnedWrap) pinnedWrap.style.display = 'none';
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === activeChannelRoomId; });
      if (ch) renderChannelRoomStream(ch);
      showAccountToast('Unpinned announcement.');
    }

    function scrollToPinnedBroadcast() {
      const container = document.getElementById('channelRoomStream');
      if (container) container.scrollTo({ top: 0, behavior: 'smooth' });
    }

    // --- Public Brand Page Showcase Handlers ---
    let activeShowcasePageId = null;

    function openPublicPageShowcase(pageId) {
      const pages = (typeof allPagesData !== 'undefined' ? allPagesData : []);
      const page = pages.find(function(p) { return p.id === pageId || p.handle === pageId; });
      if (!page) {
        showAccountToast('Page not found');
        return;
      }
      activeShowcasePageId = page.id;
      const m = document.getElementById('pageShowcaseModal');
      if (!m) return;

      const nameEl = document.getElementById('pageShowcaseName');
      if (nameEl) nameEl.innerText = page.name;
      const handleEl = document.getElementById('pageShowcaseHandle');
      if (handleEl) handleEl.innerText = page.handle + ' • Sovereign Entity';
      const avatarEl = document.getElementById('pageShowcaseAvatar');
      if (avatarEl) {
        avatarEl.innerText = page.avatar || '🏢';
        avatarEl.style.background = page.bg || '#4f46e5';
      }
      const catBadge = document.getElementById('pageShowcaseCategoryBadge');
      if (catBadge) catBadge.innerText = (page.category || 'business').toUpperCase();
      const bioEl = document.getElementById('pageShowcaseBio');
      if (bioEl) bioEl.innerText = page.bio || 'Official sovereign verified business & brand page.';
      const ctaBtn = document.getElementById('pageShowcaseCtaBtn');
      if (ctaBtn) ctaBtn.innerText = page.cta || 'Send Message';
      const followBtn = document.getElementById('pageShowcaseFollowBtn');
      if (followBtn) {
        followBtn.innerText = page.isFollowing ? 'Following ✓' : 'Follow Page';
        followBtn.className = page.isFollowing ? 'action-pill-btn action-pill-secondary' : 'action-pill-btn action-pill-primary';
      }
      const followersEl = document.getElementById('pageShowcaseFollowersCount');
      if (followersEl) followersEl.innerText = (page.count || 1).toLocaleString();

      const posts = (typeof feedPostsData !== 'undefined' ? feedPostsData : []).filter(function(p) {
        return (p.authorType === 'page' && (p.authorEntityId === page.id || p.authorEntityHandle === page.handle));
      });
      const dispatchesEl = document.getElementById('pageShowcaseDispatchesCount');
      if (dispatchesEl) dispatchesEl.innerText = posts.length;

      const stream = document.getElementById('pageShowcaseStream');
      if (stream) {
        if (posts.length === 0) {
          stream.innerHTML = '<div style="text-align: center; padding: 2.5rem 1rem; color: #94a3b8;">' +
            '<div style="font-size: 2rem; margin-bottom: 0.5rem;">🏢</div>' +
            '<div style="font-weight: 700; color: #f8fafc; font-size: 1rem;">No Page Updates Published Yet</div>' +
            '<div style="font-size: 0.8rem; margin-top: 4px;">Updates and announcements from ' + page.name + ' will appear here.</div>' +
            '</div>';
        } else {
          stream.innerHTML = posts.map(function(p) {
            return '<div style="background: rgba(15, 23, 42, 0.75); border: 1px solid rgba(255,255,255,0.08); border-radius: 14px; padding: 14px; display: flex; flex-direction: column; gap: 8px;">' +
              '<div style="display: flex; justify-content: space-between; align-items: center;">' +
                '<span class="badge" style="background: rgba(192, 132, 252, 0.15); color: #c084fc; font-size: 0.7rem; font-weight: 700;">🏢 PAGE UPDATE</span>' +
                '<span style="font-size: 0.72rem; color: #64748b;">' + new Date(p.timestamp || Date.now()).toLocaleDateString() + '</span>' +
              '</div>' +
              (p.mediaImage ? '<img src="' + p.mediaImage + '" style="width: 100%; max-height: 240px; object-fit: cover; border-radius: 10px;" />' : '') +
              '<div style="color: #f8fafc; font-size: 0.92rem; line-height: 1.45;">' + (p.caption || '') + '</div>' +
              '</div>';
          }).join('');
        }
      }

      m.style.display = 'flex';
    }

    function closePublicPageShowcase() {
      const m = document.getElementById('pageShowcaseModal');
      if (m) m.style.display = 'none';
      activeShowcasePageId = null;
    }

    function togglePageShowcaseFollow() {
      if (!activeShowcasePageId) return;
      const pages = (typeof allPagesData !== 'undefined' ? allPagesData : []);
      const page = pages.find(function(p) { return p.id === activeShowcasePageId; });
      if (!page) return;
      page.isFollowing = !page.isFollowing;
      page.count += page.isFollowing ? 1 : -1;
      const followBtn = document.getElementById('pageShowcaseFollowBtn');
      if (followBtn) {
        followBtn.innerText = page.isFollowing ? 'Following ✓' : 'Follow Page';
        followBtn.className = page.isFollowing ? 'action-pill-btn action-pill-secondary' : 'action-pill-btn action-pill-primary';
      }
      const followersEl = document.getElementById('pageShowcaseFollowersCount');
      if (followersEl) followersEl.innerText = (page.count || 1).toLocaleString();
      fetch('/api/social/pages/follow', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ pageId: page.id })
      }).catch(function() {});
      showAccountToast(page.isFollowing ? '✓ Followed ' + page.name : 'Unfollowed ' + page.name);
    }

    function triggerPageShowcaseCta() {
      if (!activeShowcasePageId) return;
      const pages = (typeof allPagesData !== 'undefined' ? allPagesData : []);
      const page = pages.find(function(p) { return p.id === activeShowcasePageId; });
      if (!page) return;
      if (page.ctaType === 'tip') {
        if (typeof openTipModal === 'function') openTipModal();
      } else if (page.ctaType === 'website') {
        window.open('https://sovra.network', '_blank');
      } else {
        closePublicPageShowcase();
        switchTab('messages');
        showAccountToast('💬 Opening direct encrypted thread with ' + page.name);
      }
    }

    function submitChannelBroadcast() {
      if (!activeChannelRoomId) return;
      const input = document.getElementById('channelBroadcastInput');
      const text = input ? input.value.trim() : '';

      let pollData = null;
      const qInput = document.getElementById('channelPollQuestionInput');
      const qText = qInput ? qInput.value.trim() : '';
      if (qText) {
        const o1 = document.getElementById('channelPollOpt1');
        const o2 = document.getElementById('channelPollOpt2');
        const t1 = o1 ? o1.value.trim() : 'Yes';
        const t2 = o2 ? o2.value.trim() : 'No';
        pollData = {
          question: qText,
          options: [
            { text: t1 || 'Yes', votes: 1 },
            { text: t2 || 'No', votes: 0 }
          ],
          totalVotes: 1,
          hasVoted: false
        };
      }

      if (!text && !channelPhotoDataUrl && !activeChannelVoiceDataUrl && !pollData) {
        showAccountToast('Please enter a message, record voice, or attach media to broadcast.');
        return;
      }
      const channels = (typeof allChannelsData !== 'undefined' ? allChannelsData : []);
      const ch = channels.find(function(c) { return c.id === activeChannelRoomId; });
      if (!ch) return;

      const payload = {
        caption: text || (activeChannelVoiceDataUrl ? '🎙️ Voice Dispatch' : (pollData ? ('📊 Poll: ' + pollData.question) : '')),
        postType: (activeChannelVoiceDataUrl ? 'audio' : (pollData ? 'poll' : 'text')),
        authorType: 'channel',
        authorEntityId: ch.id,
        authorBadge: '📢 Channel',
        authorEntityHandle: ch.handle,
        mediaImage: channelPhotoDataUrl || undefined,
        mediaAudio: activeChannelVoiceDataUrl || undefined,
        audioDuration: activeChannelVoiceDataUrl ? activeChannelVoiceDuration : undefined,
        isVoiceNote: !!activeChannelVoiceDataUrl,
        pollData: pollData || undefined,
      };

      fetch('/api/feed/create', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': 'Bearer ' + (localStorage.getItem('sovra_session_token') || '')
        },
        body: JSON.stringify(payload)
      })
      .then(function(res) { return res.json(); })
      .then(function(data) {
        if (data.ok && data.post) {
          if (typeof feedPostsData !== 'undefined') {
            feedPostsData.unshift(data.post);
          }
          if (input) input.value = '';
          clearChannelPhotoUpload();
          clearChannelVoiceUpload();
          clearChannelPollCreator();
          renderChannelRoomStream(ch);
          if (typeof renderFeedPosts === 'function') renderFeedPosts();
          showAccountToast('📢 Broadcast dispatched to ' + ch.name + ' subscribers!');
        } else {
          showAccountToast('Broadcast failed: ' + (data.error || 'Unknown error'));
        }
      })
      .catch(function(err) {
        console.error('[Channel] Broadcast error:', err);
        showAccountToast('Broadcast failed: ' + err.message);
      });
    }

    function publishAsEntity(val) {
      if (val && val.startsWith('channel:')) {
        openChannelRoom(val.replace('channel:', ''));
      } else if (val && val.startsWith('page:')) {
        switchToPersona(val);
        switchTab('feed');
      } else {
        switchToPersona('personal');
        switchTab('feed');
      }
    }

    // --- Feed Post Options & Actions ---
    function openPostOptionsModal(postId, author, cid) {
      var foundPost = (typeof feedPostsData !== 'undefined' && Array.isArray(feedPostsData))
        ? feedPostsData.find(function(p) { return p.id === postId; })
        : null;
      var authorDid = (foundPost && foundPost.authorDid) || (foundPost && foundPost.author);
      activeTargetPost = {
        id: postId,
        author: author || (foundPost && (foundPost.authorHandle || foundPost.authorName || foundPost.author)),
        cid: cid || (foundPost && foundPost.cid),
        authorDid: authorDid
      };

      var editBtn = document.getElementById('postOptionEditBtn');
      var deleteBtn = document.getElementById('postOptionDeleteBtn');
      var currentDid = (myProfile && myProfile.did) || '';
      var currentHandle = (myProfile && myProfile.handle) || currentUserHandle || '';
      var isAdmin = Boolean(myProfile && (myProfile.role === 'admin' || myProfile.role === 'SUPER_ADMIN' || myProfile.isAdmin));
      var isOwner = Boolean(
        isAdmin ||
        !myProfile ||
        (authorDid && currentDid && authorDid === currentDid) ||
        (activeTargetPost.author && currentHandle && activeTargetPost.author.replace('@', '').toLowerCase() === currentHandle.replace('@', '').toLowerCase())
      );

      if (editBtn) editBtn.style.display = isOwner ? 'flex' : 'none';
      if (deleteBtn) deleteBtn.style.display = isOwner ? 'flex' : 'none';

      const m = document.getElementById('postOptionsModal');
      if (m) m.style.display = 'flex';
    }
    window.openPostOptionsModal = openPostOptionsModal;

    function closePostOptionsModal() {
      const m = document.getElementById('postOptionsModal');
      if (m) m.style.display = 'none';
    }
    window.closePostOptionsModal = closePostOptionsModal;

    function triggerEditFromModal() {
      closePostOptionsModal();
      if (!activeTargetPost || !activeTargetPost.id) return;
      openEditPostModal(activeTargetPost.id);
    }
    window.triggerEditFromModal = triggerEditFromModal;

    function openEditPostModal(postId) {
      var modal = document.getElementById('editPostModal');
      var textarea = document.getElementById('editPostCaptionInput');
      if (!modal || !textarea) return;

      var currentText = '';
      var card = document.getElementById('card-' + postId);
      if (card) {
        var captionEl = card.querySelector('.post-caption-text, .post-text, .post-content-body, p');
        if (captionEl) currentText = captionEl.innerText || '';
      }
      if (!currentText && typeof feedPostsData !== 'undefined' && Array.isArray(feedPostsData)) {
        var p = feedPostsData.find(function(item) { return item.id === postId; });
        if (p) currentText = p.caption || p.text || '';
      }

      textarea.value = currentText.replace(/\s*\(edited\)\s*$/, '').trim();
      modal.style.display = 'flex';
      setTimeout(function() { textarea.focus(); }, 100);
    }
    window.openEditPostModal = openEditPostModal;

    function closeEditPostModal() {
      var modal = document.getElementById('editPostModal');
      if (modal) modal.style.display = 'none';
    }
    window.closeEditPostModal = closeEditPostModal;

    async function submitEditPost() {
      var saveBtn = document.getElementById('saveEditPostBtn');
      var textarea = document.getElementById('editPostCaptionInput');
      if (!textarea || !activeTargetPost || !activeTargetPost.id) return;
      var newCaption = textarea.value.trim();
      var postId = activeTargetPost.id;
      var token = localStorage.getItem('sovra_session_token') || (myProfile && myProfile.sessionToken) || '';

      if (saveBtn) {
        saveBtn.disabled = true;
        saveBtn.innerText = 'Saving...';
      }

      try {
        var res = await fetch('/api/feed/edit', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + token
          },
          body: JSON.stringify({
            postId: postId,
            caption: newCaption,
            sessionToken: token
          })
        });
        var data = await res.json();
        if (res.ok && data.ok) {
          if (typeof feedPostsData !== 'undefined' && Array.isArray(feedPostsData)) {
            var postObj = feedPostsData.find(function(p) { return p.id === postId; });
            if (postObj) {
              postObj.caption = newCaption;
              postObj.isEdited = true;
            }
          }
          var card = document.getElementById('card-' + postId);
          if (card) {
            var captionEl = card.querySelector('.post-caption-text, .post-text, .post-content-body, p');
            if (captionEl) {
              var safeHtml = (typeof escapeHtml === 'function') ? escapeHtml(newCaption) : newCaption;
              captionEl.innerHTML = safeHtml + ' <span class="post-edited-badge" style="font-size: 0.72rem; color: #94a3b8; font-style: italic; margin-left: 4px;">(edited)</span>';
            }
          }
          closeEditPostModal();
          showAccountToast('✅ Post updated successfully!');
        } else {
          showAccountToast('⚠️ Could not edit post: ' + (data.error || 'Server error'));
        }
      } catch (err) {
        showAccountToast('⚠️ Network error while editing post.');
      } finally {
        if (saveBtn) {
          saveBtn.disabled = false;
          saveBtn.innerText = 'Save Changes';
        }
      }
    }
    window.submitEditPost = submitEditPost;

