    window.addEventListener('beforeinstallprompt', function(e) {
      if (isRunningStandaloneMode()) {
        syncPwaInstallState();
        return;
      }
      e.preventDefault();
      deferredInstallPrompt = e;
      syncPwaInstallState();
      const banner = document.getElementById('pwaInstallBanner');
      if (banner && !sessionStorage.getItem('pwa_dismissed')) {
        banner.style.display = 'flex';
      }
      const pwaMeBtn = document.getElementById('pwaMeInstallBtn');
      if (pwaMeBtn) pwaMeBtn.style.display = 'inline-flex';
    });

    window.addEventListener('appinstalled', function() {
      deferredInstallPrompt = null;
      try {
        localStorage.setItem('sovra_pwa_installed', 'true');
        localStorage.setItem('pwa_installed', 'true');
      } catch (e) {}
      syncPwaInstallState();
      const pwaMeBtn = document.getElementById('pwaMeInstallBtn');
      const pwaMeLabel = document.getElementById('pwaMeInstallLabel');
      if (pwaMeLabel) pwaMeLabel.innerText = '✓ App Installed';
      if (pwaMeBtn) {
        pwaMeBtn.disabled = true;
      }
      showAccountToast('🎉 Sovra successfully installed on device!', 'success');
      console.log('[PWA] Sovra successfully installed on device!');
    });

    function triggerPwaInstall(event) {
      if (event && event.stopPropagation) event.stopPropagation();
      if (isRunningStandaloneMode()) {
        syncPwaInstallState();
        showAccountToast('📱 Sovra is already running as a standalone app without URL bar!', 'success');
        return;
      }
      if (deferredInstallPrompt) {
        deferredInstallPrompt.prompt();
        deferredInstallPrompt.userChoice.then(function(choiceResult) {
          if (choiceResult.outcome === 'accepted') {
            try {
              localStorage.setItem('sovra_pwa_installed', 'true');
              localStorage.setItem('pwa_installed', 'true');
            } catch (e) {}
            syncPwaInstallState();
            showAccountToast('✓ Sovra PWA installation accepted!', 'success');
          }
          deferredInstallPrompt = null;
          syncPwaInstallState();
        });
      } else {
        openPwaGuideModal();
      }
    }

