    function updateOnlineStatus() {
      const pill = document.getElementById('offlineIndicatorPill');
      if (!pill) return;
      if (!navigator.onLine) {
        pill.style.display = 'flex';
        pill.style.background = 'linear-gradient(135deg, rgba(99, 102, 241, 0.95), rgba(168, 85, 247, 0.95))';
        pill.style.border = '1px solid rgba(168, 85, 247, 0.6)';
        pill.innerHTML = '<span>📡</span> <span>Offline Mesh Active — Bluetooth GATT &amp; DTN Outbox Ready</span>';
        if (typeof showAccountToast === 'function') {
          showAccountToast('📡 Operating in Offline Mesh Mode (Bluetooth GATT & DTN Store-and-Forward Active)', 'info');
        }
        if (window.SovraBleMeshRadar && typeof window.SovraBleMeshRadar.refreshScan === 'function') {
          window.SovraBleMeshRadar.refreshScan();
        }
      } else {
        pill.style.background = 'rgba(16, 185, 129, 0.95)';
        pill.style.border = '1px solid rgba(16, 185, 129, 0.6)';
        pill.innerHTML = '<span>⚡</span> <span>Back Online — Synced 0 actions</span>';
        if (typeof showAccountToast === 'function') {
          showAccountToast('⚡ Reconnected to Mesh Network — Syncing offline actions...', 'success');
        }
        if (window.SovraOfflineOutbox) {
          window.SovraOfflineOutbox.getInstance().drainOutbox().then(function(res) {
            const count = (res && typeof res.processed === 'number') ? res.processed : 0;
            pill.innerHTML = '<span>⚡</span> <span>Back Online — Synced ' + count + ' actions</span>';
            if (count > 0 && typeof showAccountToast === 'function') {
              showAccountToast('✓ ' + count + ' offline action(s) synced to mesh network!', 'success');
            }
          }).catch(function() {});
        }
        if (window.SovraBleMeshRadar && typeof window.SovraBleMeshRadar.refreshScan === 'function') {
          window.SovraBleMeshRadar.refreshScan();
        }
        setTimeout(function() {
          if (navigator.onLine) pill.style.display = 'none';
        }, 4000);
      }
    }

