    var _sovHandleTimer = null;
    function checkSovWizardHandleLive(handle) {
      clearTimeout(_sovHandleTimer);
      var clean = (handle || '').trim().toLowerCase().replace(/^@+/, '').replace(/[^a-z0-9_]/g, '');
      sovWizardState.handle = clean;

      var didPreview = document.getElementById('sovWizardDidPreview');
      var didSuffix = '';
      for (var i = 0; i < clean.length; i++) {
        didSuffix += clean.charCodeAt(i).toString(16);
      }
      if (didSuffix.length < 8) didSuffix = (didSuffix + '8f92a10b').slice(0, 10);
      else didSuffix = didSuffix.slice(0, 10);
      var didStr = 'did:sovra:e25519_' + (clean || 'pioneer') + '_' + didSuffix;
      sovWizardState.did = didStr;
      if (didPreview) didPreview.innerText = didStr;

      var statusEl = document.getElementById('sovWizardHandleStatus');
      if (statusEl) {
        statusEl.innerText = 'Checking...';
        statusEl.style.color = '#94a3b8';
      }

      if (!clean) {
        if (statusEl) {
          statusEl.innerText = 'Required';
          statusEl.style.color = '#ef4444';
        }
        return;
      }

      _sovHandleTimer = setTimeout(function() {
        fetch('/api/user/check-handle?handle=' + encodeURIComponent(clean))
          .then(function(r) { return r.json(); })
          .then(function(data) {
            var isAvail = (data.isAvailable !== false && data.available !== false && !data.isTaken);
            sovWizardState.isHandleAvailable = isAvail;
            if (statusEl) {
              if (isAvail) {
                statusEl.innerText = '✓ Available';
                statusEl.style.color = '#10b981';
              } else {
                statusEl.innerText = '✕ Taken';
                statusEl.style.color = '#ef4444';
              }
            }
          })
          .catch(function() {
            if (statusEl) {
              statusEl.innerText = '✓ Available';
              statusEl.style.color = '#10b981';
            }
          });
      }, 150);
    }
    window.checkSovWizardHandleLive = checkSovWizardHandleLive;

