    function triggerOnboardingConfetti() {
      var container = document.createElement('div');
      container.id = 'sovOnboardingConfettiContainer';
      container.style.cssText = 'position: fixed; inset: 0; pointer-events: none; z-index: 9999999; overflow: hidden;';
      var colors = ['#38bdf8', '#10b981', '#f59e0b', '#ec4899', '#8b5cf6', '#3b82f6', '#f43f5e'];
      var count = 50;
      for (var i = 0; i < count; i++) {
        var p = document.createElement('div');
        var color = colors[Math.floor(Math.random() * colors.length)];
        var left = Math.random() * 100;
        var animDuration = 1.6 + Math.random() * 1.2;
        var animDelay = Math.random() * 0.3;
        var size = 8 + Math.floor(Math.random() * 8);
        var rot = Math.floor(Math.random() * 360);
        p.style.cssText = 'position: absolute; left: ' + left + '%; top: -20px; width: ' + size + 'px; height: ' + (size * 0.7) + 'px; background: ' + color + '; border-radius: 2px; transform: rotate(' + rot + 'deg); animation: confettiFall ' + animDuration + 's ' + animDelay + 's cubic-bezier(0.25, 0.46, 0.45, 0.94) forwards; opacity: 0.95;';
        container.appendChild(p);
      }
      document.body.appendChild(container);
      setTimeout(function() {
        if (container.parentNode) container.parentNode.removeChild(container);
      }, 3200);
    }
