    function handlePaletteSearchInput(query) {
      var t0 = performance.now();
      var q = (query || '').trim().toLowerCase();
      var results = [];

      // 1. Filter static actions
      PALETTE_ACTIONS.forEach(function(act) {
        if (!q || act.title.toLowerCase().includes(q) || act.subtitle.toLowerCase().includes(q) || act.category.toLowerCase().includes(q)) {
          results.push(act);
        }
      });

      // 2. Filter dynamic catalog people (socialOmniCatalog.people & creators)
      var peopleList = [];
      if (typeof socialOmniCatalog !== 'undefined') {
        if (Array.isArray(socialOmniCatalog.people)) {
          peopleList = peopleList.concat(socialOmniCatalog.people);
        }
        if (Array.isArray(socialOmniCatalog.creators)) {
          socialOmniCatalog.creators.forEach(function(c) {
            if (!peopleList.some(function(p) { return (p.did && p.did === c.did) || (p.handle && p.handle === c.handle); })) {
              peopleList.push(c);
            }
          });
        }
      }
      peopleList.forEach(function(u) {
        if (!u || u.isBlocked) return;
        var nameMatch = u.name && u.name.toLowerCase().includes(q);
        var handleMatch = u.handle && u.handle.toLowerCase().includes(q);
        var didMatch = u.did && u.did.toLowerCase().includes(q);
        var bioMatch = u.bio && u.bio.toLowerCase().includes(q);
        if (!q || nameMatch || handleMatch || didMatch || bioMatch) {
          results.push({
            id: 'user-' + (u.did || u.handle || u.id),
            title: (u.name || u.displayName || u.handle) + (u.handle ? (' (' + u.handle + ')') : ''),
            subtitle: u.did ? (u.did.slice(0, 24) + '...') : (u.bio || 'Mesh Peer'),
            icon: u.avatar || '👤',
            category: 'People / DIDs',
            shortcut: '@',
            run: function() {
              switchTab('chat');
              if (typeof openDirectChatWithDid === 'function' && u.did) {
                openDirectChatWithDid(u.did);
              }
            }
          });
        }
      });

      // 3. Filter channels
      if (typeof socialOmniCatalog !== 'undefined' && Array.isArray(socialOmniCatalog.channels)) {
        socialOmniCatalog.channels.forEach(function(ch) {
          if (!q || ch.name.toLowerCase().includes(q) || ch.id.toLowerCase().includes(q)) {
            results.push({
              id: 'chan-' + ch.id,
              title: ch.name + ' (' + ch.id + ')',
              subtitle: ch.desc || 'Mesh Topic Space',
              icon: ch.avatar || '🛰️',
              category: 'Channels',
              shortcut: '#',
              run: function() {
                if (typeof openChannelRoom === 'function') openChannelRoom(ch.id);
                else switchTab('feed');
              }
            });
          }
        });
      }

      // 4. Filter posts (if available)
      if (q && typeof feedPostsData !== 'undefined' && Array.isArray(feedPostsData)) {
        var postMatches = 0;
        for (var pIdx = 0; pIdx < feedPostsData.length && postMatches < 3; pIdx++) {
          var post = feedPostsData[pIdx];
          if (post && post.caption && post.caption.toLowerCase().includes(q)) {
            results.push({
              id: 'post-' + post.id,
              title: post.caption.slice(0, 40) + '...',
              subtitle: 'Post by ' + (post.authorName || post.authorHandle || 'Peer'),
              icon: '📝',
              category: 'Posts',
              shortcut: '↵',
              run: function() {
                switchTab('feed');
              }
            });
            postMatches++;
          }
        }
      }

      // Limit results for sub-10ms responsiveness
      paletteActiveItems = results.slice(0, 14);
      paletteSelectedIndex = 0;

      var t1 = performance.now();
      var elapsedMs = (t1 - t0).toFixed(2);
      var perfEl = document.getElementById('palettePerfTime');
      if (perfEl) {
        perfEl.innerText = elapsedMs + 'ms instant (' + paletteActiveItems.length + ' results)';
      }

      renderPaletteResults();
    }
    window.handlePaletteSearchInput = handlePaletteSearchInput;

    function renderPaletteResults() {
      var container = document.getElementById('globalCommandPaletteResults');
      if (!container) return;

      if (paletteActiveItems.length === 0) {
        container.innerHTML = '<div style="padding: 2.5rem 1rem; text-align: center; color: #64748b; font-size: 0.9rem;">No matching commands, users, or channels found.</div>';
        return;
      }

      var html = '';
      var currentCat = '';
      paletteActiveItems.forEach(function(item, idx) {
        if (item.category !== currentCat) {
          currentCat = item.category;
          html += '<div style="font-size: 0.68rem; font-weight: 800; color: #38bdf8; text-transform: uppercase; letter-spacing: 0.06em; padding: 6px 12px 2px 12px; margin-top: 4px;">' + currentCat + '</div>';
        }
        var isSelected = (idx === paletteSelectedIndex);
        var bg = isSelected ? 'rgba(56, 189, 248, 0.14)' : 'transparent';
        var border = isSelected ? '1px solid rgba(56, 189, 248, 0.35)' : '1px solid transparent';
        html += '<div class="palette-item" data-idx="' + idx + '" onclick="executePaletteItem(' + idx + ')" onmouseenter="selectPaletteItemHover(' + idx + ')" style="display: flex; align-items: center; justify-content: space-between; padding: 8px 12px; border-radius: 10px; background: ' + bg + '; border: ' + border + '; cursor: pointer; transition: background 0.12s ease; margin-bottom: 2px;">' +
          '<div style="display: flex; align-items: center; gap: 10px; min-width: 0;">' +
            '<div style="width: 28px; height: 28px; border-radius: 8px; background: rgba(255,255,255,0.08); display: flex; align-items: center; justify-content: center; font-size: 0.95rem; flex-shrink: 0;">' + item.icon + '</div>' +
            '<div style="min-width: 0; text-align: left;">' +
              '<div style="font-size: 0.88rem; font-weight: 700; color: #fff; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">' + item.title + '</div>' +
              '<div style="font-size: 0.72rem; color: #94a3b8; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">' + item.subtitle + '</div>' +
            '</div>' +
          '</div>' +
          (item.shortcut ? ('<kbd style="background: rgba(255,255,255,0.06); border: 1px solid rgba(255,255,255,0.14); border-radius: 6px; padding: 2px 6px; font-size: 0.68rem; color: #94a3b8; font-family: monospace;">' + item.shortcut + '</kbd>') : '') +
        '</div>';
      });

      container.innerHTML = html;
    }

    function selectPaletteItemHover(idx) {
      paletteSelectedIndex = idx;
      renderPaletteResultsSelection();
    }
    window.selectPaletteItemHover = selectPaletteItemHover;

    function renderPaletteResultsSelection() {
      var items = document.querySelectorAll('#globalCommandPaletteResults .palette-item');
      items.forEach(function(el, i) {
        var isSelected = (i === paletteSelectedIndex);
        el.style.background = isSelected ? 'rgba(56, 189, 248, 0.14)' : 'transparent';
        el.style.border = isSelected ? '1px solid rgba(56, 189, 248, 0.35)' : '1px solid transparent';
      });
    }

    function executePaletteItem(idx) {
      var item = paletteActiveItems[idx];
      if (item && typeof item.run === 'function') {
        closeGlobalCommandPalette();
        try {
          item.run();
        } catch (err) {
          console.warn('Command palette execution error:', err);
        }
      }
    }
    window.executePaletteItem = executePaletteItem;

    function handlePaletteKeydown(event) {
      if (event.key === 'ArrowDown') {
        event.preventDefault();
        if (paletteActiveItems.length > 0) {
          paletteSelectedIndex = (paletteSelectedIndex + 1) % paletteActiveItems.length;
          renderPaletteResultsSelection();
          var selEl = document.querySelector('#globalCommandPaletteResults .palette-item[data-idx="' + paletteSelectedIndex + '"]');
          if (selEl) selEl.scrollIntoView({ block: 'nearest' });
        }
      } else if (event.key === 'ArrowUp') {
        event.preventDefault();
        if (paletteActiveItems.length > 0) {
          paletteSelectedIndex = (paletteSelectedIndex - 1 + paletteActiveItems.length) % paletteActiveItems.length;
          renderPaletteResultsSelection();
          var selEl = document.querySelector('#globalCommandPaletteResults .palette-item[data-idx="' + paletteSelectedIndex + '"]');
          if (selEl) selEl.scrollIntoView({ block: 'nearest' });
        }
      } else if (event.key === 'Enter') {
        event.preventDefault();
        executePaletteItem(paletteSelectedIndex);
      } else if (event.key === 'Escape') {
        event.preventDefault();
        closeGlobalCommandPalette();
      }
    }
    window.handlePaletteKeydown = handlePaletteKeydown;

    // =========================================================================
    // 📞 WHATSAPP-GRADE 1-ON-1 SPATIAL WEBRTC CALLING & FLOATING PIP ENGINE
    // =========================================================================
    window._spatialCallState = 'idle';
    window._spatialCallPeer = null;
    window._spatialCallType = 'audio';
    window._spatialCallSeconds = 0;
    window._spatialCallTimerInterval = null;
    window._spatialCallIsScreenSharing = false;

    function formatCallTimer(totalSeconds) {
      var mins = Math.floor(totalSeconds / 60);
      var secs = totalSeconds % 60;
      return (mins < 10 ? '0' : '') + mins + ':' + (secs < 10 ? '0' : '') + secs;
    }

    function openSpatialCallOverlay(peerName, peerAvatar, callType, isIncoming, callId) {
      window._spatialCallState = isIncoming ? 'ringing' : 'connecting';
      window._spatialCallPeer = { name: peerName || 'Peer', avatar: peerAvatar || '📞', callId: callId };
      window._spatialCallType = (callType === 'video') ? 'video' : 'audio';
      window._spatialCallSeconds = 0;

      if (window._spatialCallTimerInterval) {
        clearInterval(window._spatialCallTimerInterval);
        window._spatialCallTimerInterval = null;
      }

      var overlay = document.getElementById('spatialCallOverlay');
      var pip = document.getElementById('spatialCallPipFloating');
      var nameEl = document.getElementById('spatialCallPeerName');
      var avatarEl = document.getElementById('spatialCallAvatarIcon');
      var statusEl = document.getElementById('spatialCallStatusText');
      var durationEl = document.getElementById('spatialCallDuration');
      var incActions = document.getElementById('spatialIncomingActions');
      var dockActions = document.getElementById('spatialCallActionDock');
      var videoContainer = document.getElementById('spatialVideoContainer');

      if (pip) pip.style.display = 'none';
      if (nameEl) nameEl.innerText = peerName || 'Peer';
      if (avatarEl) {
        if (peerAvatar && peerAvatar.length > 4) {
          avatarEl.innerHTML = '<img src="' + peerAvatar + '" style="width:100%;height:100%;object-fit:cover;border-radius:50%;" />';
        } else {
          avatarEl.innerText = peerAvatar || '📞';
        }
      }

      if (durationEl) durationEl.innerText = '00:00';
      if (videoContainer) videoContainer.style.display = (window._spatialCallType === 'video') ? 'block' : 'none';

      if (isIncoming) {
        if (statusEl) statusEl.innerText = 'Incoming ' + (window._spatialCallType === 'video' ? 'Video' : 'Voice') + ' Call...';
        if (incActions) incActions.style.display = 'flex';
        if (dockActions) dockActions.style.display = 'none';
        if (typeof playCallAudioRinging === 'function') playCallAudioRinging('incoming');
      } else {
        if (statusEl) statusEl.innerText = 'Calling ' + (window._spatialCallType === 'video' ? 'Video...' : 'Voice...');
        if (incActions) incActions.style.display = 'none';
        if (dockActions) dockActions.style.display = 'flex';
        if (typeof playCallAudioRinging === 'function') playCallAudioRinging('outgoing');
      }

      if (overlay) overlay.style.display = 'flex';
    }
    window.openSpatialCallOverlay = openSpatialCallOverlay;

    function closeSpatialCallOverlay() {
      var overlay = document.getElementById('spatialCallOverlay');
      if (overlay) overlay.style.display = 'none';
      var pip = document.getElementById('spatialCallPipFloating');
      if (pip) pip.style.display = 'none';
      if (window._spatialCallTimerInterval) {
        clearInterval(window._spatialCallTimerInterval);
        window._spatialCallTimerInterval = null;
      }
      window._spatialCallState = 'idle';
    }
    window.closeSpatialCallOverlay = closeSpatialCallOverlay;

    function acceptSpatialCall() {
      window._spatialCallState = 'connected';
      if (typeof stopCallAudioRinging === 'function') stopCallAudioRinging();

      var statusEl = document.getElementById('spatialCallStatusText');
      if (statusEl) statusEl.innerText = '🔒 Connected • E2EE P2P';

      var incActions = document.getElementById('spatialIncomingActions');
      if (incActions) incActions.style.display = 'none';

      var dockActions = document.getElementById('spatialCallActionDock');
      if (dockActions) dockActions.style.display = 'flex';

      window._spatialCallSeconds = 0;
      if (window._spatialCallTimerInterval) clearInterval(window._spatialCallTimerInterval);
      window._spatialCallTimerInterval = setInterval(function() {
        window._spatialCallSeconds++;
        var str = formatCallTimer(window._spatialCallSeconds);
        var durEl = document.getElementById('spatialCallDuration');
        if (durEl) durEl.innerText = str;
        var pipDurEl = document.getElementById('spatialCallPipDuration');
        if (pipDurEl) pipDurEl.innerText = str;
      }, 1000);

      // Trigger underlying WebRTC acceptance if incoming call modal was active
      if (typeof acceptIncomingCall === 'function') {
        try { acceptIncomingCall(); } catch (_) {}
      }
    }
    window.acceptSpatialCall = acceptSpatialCall;

    function declineSpatialCall() {
      window._spatialCallState = 'ended';
      if (typeof stopCallAudioRinging === 'function') stopCallAudioRinging();

      var statusEl = document.getElementById('spatialCallStatusText');
      if (statusEl) statusEl.innerText = 'Call Declined';

      if (typeof declineIncomingCall === 'function') {
        try { declineIncomingCall(); } catch (_) {}
      }

      setTimeout(function() {
        closeSpatialCallOverlay();
      }, 500);
    }
    window.declineSpatialCall = declineSpatialCall;

    function endSpatialCall() {
      window._spatialCallState = 'ended';
      if (typeof stopCallAudioRinging === 'function') stopCallAudioRinging();
      if (window._spatialCallTimerInterval) {
        clearInterval(window._spatialCallTimerInterval);
        window._spatialCallTimerInterval = null;
      }

      var durStr = formatCallTimer(window._spatialCallSeconds);
      var statusEl = document.getElementById('spatialCallStatusText');
      if (statusEl) statusEl.innerText = 'Call Ended • ' + durStr;

      if (typeof endE2eeCall === 'function') {
        try { endE2eeCall('user_hung_up'); } catch (_) {}
      }

      setTimeout(function() {
        closeSpatialCallOverlay();
      }, 600);
    }
    window.endSpatialCall = endSpatialCall;

    function minimizeSpatialCallToPip() {
      var overlay = document.getElementById('spatialCallOverlay');
      if (overlay) overlay.style.display = 'none';

      var pip = document.getElementById('spatialCallPipFloating');
      if (pip) {
        pip.style.display = 'flex';
        var nameEl = document.getElementById('spatialCallPipPeerName');
        if (nameEl && window._spatialCallPeer) nameEl.innerText = window._spatialCallPeer.name || 'Peer';
        var durEl = document.getElementById('spatialCallPipDuration');
        if (durEl) durEl.innerText = formatCallTimer(window._spatialCallSeconds);
      }
      window._spatialCallState = 'minimized';
    }
    window.minimizeSpatialCallToPip = minimizeSpatialCallToPip;

    function expandSpatialCallFromPip() {
      var pip = document.getElementById('spatialCallPipFloating');
      if (pip) pip.style.display = 'none';

      var overlay = document.getElementById('spatialCallOverlay');
      if (overlay) overlay.style.display = 'flex';

      window._spatialCallState = 'connected';
    }
    window.expandSpatialCallFromPip = expandSpatialCallFromPip;

    function toggleSpatialCallMic() {
      var btn = document.getElementById('btnToggleCallMic');
      if (typeof toggleCallMute === 'function') {
        try { toggleCallMute(); } catch (_) {}
      }
      if (btn) {
        var isMuted = btn.style.background === 'rgb(239, 68, 68)' || btn.innerText === '🔇';
        btn.style.background = isMuted ? 'rgba(255,255,255,0.08)' : '#ef4444';
        btn.innerText = isMuted ? '🎙️' : '🔇';
      }
    }
    window.toggleSpatialCallMic = toggleSpatialCallMic;

    function toggleSpatialCallCamera() {
      var btn = document.getElementById('btnToggleCallCamera');
      var container = document.getElementById('spatialVideoContainer');
      if (typeof toggleCallVideo === 'function') {
        try { toggleCallVideo(); } catch (_) {}
      }
      if (container) {
        var isVisible = (container.style.display !== 'none');
        container.style.display = isVisible ? 'none' : 'block';
        if (btn) btn.style.background = isVisible ? '#ef4444' : 'rgba(255,255,255,0.08)';
      }
    }
    window.toggleSpatialCallCamera = toggleSpatialCallCamera;

    function toggleSpatialCallScreenShare() {
      var btn = document.getElementById('btnToggleCallScreenShare');
      window._spatialCallIsScreenSharing = !window._spatialCallIsScreenSharing;
      if (btn) {
        btn.style.background = window._spatialCallIsScreenSharing ? '#38bdf8' : 'rgba(255,255,255,0.08)';
        btn.style.color = window._spatialCallIsScreenSharing ? '#0f172a' : '#fff';
      }
      var videoContainer = document.getElementById('spatialVideoContainer');
      if (videoContainer) videoContainer.style.display = 'block';
      if (typeof showAccountToast === 'function') {
        showAccountToast(window._spatialCallIsScreenSharing ? '🖥️ Screen sharing started' : '🖥️ Screen sharing stopped');
      }
    }
    window.toggleSpatialCallScreenShare = toggleSpatialCallScreenShare;

    function handleSpatialCallSignal(sig) {
      if (!sig) return;
      var type = sig.type || sig.signalType;
      if (type === 'call_invite') {
        openSpatialCallOverlay(sig.callerName, sig.callerAvatar, sig.callType, true, sig.callId);
      } else if (type === 'call_accept') {
        acceptSpatialCall();
      } else if (type === 'call_reject' || type === 'call_hangup') {
        endSpatialCall();
      }
    }
    window.handleSpatialCallSignal = handleSpatialCallSignal;


    // ========================================================
    // ⚔️ SOVRA TITAN-KILLER CLIENT-SIDE ENGINE (CYCLES 1-6)
    // ========================================================
    window._sovraTitanKillerInitialized = true;
    window._activeAlgorithmicHorizon = 'chronological';
    window._currentDAppSessionToken = null;

    // --- CYCLE 1: SOVEREIGN MINI-DAPPS ---
    async function fetchDAppsList(category) {
      try {
        var cat = category || 'all';
        var res = await fetch('/api/dapps/explore?category=' + encodeURIComponent(cat));
        var data = await res.json();
        if (data.ok && Array.isArray(data.dapps)) {
          renderDAppsGrid(data.dapps);
        }
      } catch (err) {
        console.warn('[DAPPS] Failed to load dapps:', err);
      }
    }
    window.fetchDAppsList = fetchDAppsList;

    function renderDAppsGrid(dapps) {
      var container = document.getElementById('dappsGridContainer');
      if (!container) return;
      if (!dapps || dapps.length === 0) {
        container.innerHTML = '<div style="grid-column: 1/-1; padding: 2rem; text-align: center; color: #94a3b8;">No Mini-DApps found in this category.</div>';
        return;
      }
      var html = '';
      for (var i = 0; i < dapps.length; i++) {
        var d = dapps[i];
        var permsBadges = (d.permissions || []).map(function(p) {
          return '<span style="font-size: 0.65rem; padding: 2px 6px; border-radius: 4px; background: rgba(99,102,241,0.15); color: #a5b4fc; border: 1px solid rgba(99,102,241,0.3);">' + p + '</span>';
        }).join(' ');

        html += '<div style="background: rgba(15, 23, 42, 0.7); border: 1px solid rgba(255, 255, 255, 0.08); border-radius: 16px; padding: 1.25rem; display: flex; flex-direction: column; justify-content: space-between; transition: all 0.2s;">';
        html += '<div>';
        html += '  <div style="display: flex; align-items: center; justify-content: space-between; margin-bottom: 10px;">';
        html += '    <span style="font-size: 2rem;">' + (d.iconUrl || '📱') + '</span>';
        html += '    <span style="font-size: 0.75rem; color: #f59e0b; font-weight: 700;">★ ' + (d.rating || 5.0) + '</span>';
        html += '  </div>';
        html += '  <div style="font-weight: 800; color: #fff; font-size: 1.05rem; margin-bottom: 4px;">' + d.name + '</div>';
        html += '  <div style="font-size: 0.78rem; color: #94a3b8; line-height: 1.4; margin-bottom: 12px;">' + (d.description || '') + '</div>';
        html += '  <div style="display: flex; gap: 4px; flex-wrap: wrap; margin-bottom: 14px;">' + permsBadges + '</div>';
        html += '</div>';
        html += '<div style="display: flex; align-items: center; justify-content: space-between; border-top: 1px solid rgba(255,255,255,0.06); padding-top: 10px;">';
        html += '  <span style="font-size: 0.72rem; color: #64748b;">' + (d.installsCount || 0) + ' runs</span>';
        html += '  <button type="button" data-dappid="' + d.id + '" onclick="launchMiniDApp(this.getAttribute(&quot;data-dappid&quot;))" class="btn btn-primary" style="background: #6366f1; border: none; padding: 6px 14px; border-radius: 8px; font-weight: 700; font-size: 0.8rem; cursor: pointer; color: #fff;">Launch ⚡</button>';
        html += '</div>';
        html += '</div>';
      }
      container.innerHTML = html;
    }
    window.renderDAppsGrid = renderDAppsGrid;

    function filterDAppsCategory(cat, btn) {
      document.querySelectorAll('.dapp-cat-pill').forEach(function(p) {
        p.classList.remove('active');
        p.style.background = 'rgba(255,255,255,0.05)';
        p.style.color = '#94a3b8';
        p.style.borderColor = 'rgba(255,255,255,0.08)';
      });
      if (btn) {
        btn.classList.add('active');
        btn.style.background = 'rgba(255,255,255,0.15)';
        btn.style.color = '#fff';
        btn.style.borderColor = 'rgba(255,255,255,0.2)';
      }
      fetchDAppsList(cat);
    }
    window.filterDAppsCategory = filterDAppsCategory;

    async function launchMiniDApp(dappId) {
      try {
        var myDid = (window.SovraState && window.SovraState.currentUser && window.SovraState.currentUser.did) || 'did:sovra:anonymous';
        var res = await fetch('/api/dapps/launch', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ dappId: dappId, userDid: myDid })
        });
        var data = await res.json();
        if (data.ok) {
          window._currentDAppSessionToken = data.launchToken;
          var modal = document.getElementById('dappRunnerModal');
          var iframe = document.getElementById('dappSandboxIframe');
          var titleEl = document.getElementById('dappRunnerTitle');
          if (titleEl) titleEl.textContent = data.dapp.name;
          if (iframe) iframe.src = data.sandboxUrl;
          if (modal) modal.style.display = 'flex';
        } else {
          showAccountToast('Failed to launch DApp: ' + (data.error || 'Unknown error'));
        }
      } catch (err) {
        showAccountToast('DApp launch error: ' + err.message);
      }
    }
    window.launchMiniDApp = launchMiniDApp;

    function closeDAppRunner() {
      var modal = document.getElementById('dappRunnerModal');
      var iframe = document.getElementById('dappSandboxIframe');
      if (modal) modal.style.display = 'none';
      if (iframe) iframe.src = 'about:blank';
      window._currentDAppSessionToken = null;
    }
    window.closeDAppRunner = closeDAppRunner;

    function openPublishDAppPrompt() {
      var name = prompt('Mini-DApp Name:');
      if (!name) return;
      var cat = prompt('Category (games, defi, tools, social):', 'tools');
      var desc = prompt('Description:');
      var myDid = (window.SovraState && window.SovraState.currentUser && window.SovraState.currentUser.did) || 'did:sovra:anonymous';

      fetch('/api/dapps/publish', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: name,
          category: cat || 'tools',
          description: desc || '',
          bundleCid: 'bafybeic' + (window.sovraCSPRNG ? window.sovraCSPRNG(10) : Date.now().toString(36)),
          authorDid: myDid,
          permissions: ['identity:profile', 'wallet:pay']
        })
      }).then(function(r) { return r.json(); }).then(function(d) {
        if (d.ok) {
          showAccountToast('Mini-DApp registered successfully!');
          fetchDAppsList();
        } else {
          showAccountToast('Error: ' + d.error);
        }
      });
    }
    window.openPublishDAppPrompt = openPublishDAppPrompt;

    // Sandboxed postMessage RPC Listener for Mini-DApps
    window.addEventListener('message', async function(event) {
      if (!event.data || event.data.type !== 'SOVRA_RPC_REQUEST') return;
      var reqData = event.data;
      var token = window._currentDAppSessionToken;
      if (!token) return;

      try {
        var r = await fetch('/api/dapps/rpc', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({
            launchToken: token,
            method: reqData.method,
            params: reqData.params
          })
        });
        var resData = await r.json();
        if (event.source) {
          event.source.postMessage({
            type: 'SOVRA_RPC_RESPONSE',
            id: reqData.id,
            result: resData.result,
            error: resData.error
          }, '*');
        }
      } catch (err) {
        if (event.source) {
          event.source.postMessage({
            type: 'SOVRA_RPC_RESPONSE',
            id: reqData.id,
            error: err.message
          }, '*');
        }
      }
    });

